__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"lorePack",{enumerable:!0,get:function(){return f}});var s=r(d[0]),o=r(d[1]),t=r(d[2]),n=r(d[3]),l=r(d[4]),c=r(d[5]),u=r(d[6]),h=r(d[7]),p=r(d[8]),w=r(d[9]);const f={entries:{...s.chapters1,...o.chapters2,...t.classes,...n.races,...l.zones1,...c.zones2,...u.instances1,...h.instances2,...p.items,...w.terms},eras:{creation:{title:"Titanes y Dioses Antiguos",when:"Antes de la historia escrita"},"ancient-kalimdor":{title:"El imperio kaldorei",when:"Diez mil a\xf1os o m\xe1s antes del Portal Oscuro"},"elder-kingdoms":{title:"Los reinos antiguos",when:"Entre unos 7000 y 200 a\xf1os antes del Portal Oscuro"},draenor:{title:"Los orcos de Draenor",when:"Las d\xe9cadas anteriores al Portal Oscuro"},"first-war":{title:"La Primera Guerra",when:"La apertura del Portal Oscuro (a\xf1o 0)"},"second-war":{title:"La Segunda Guerra",when:"Pocos a\xf1os despu\xe9s del Portal Oscuro"},interwar:{title:"Entre guerras",when:"Los a\xf1os posteriores a la Segunda Guerra"},"third-war":{title:"La Tercera Guerra",when:"Unos veinte a\xf1os despu\xe9s del Portal Oscuro"},"new-homes":{title:"Nuevos hogares en Kalimdor",when:"Los a\xf1os posteriores a la Tercera Guerra"},classic:{title:"La era de World of Warcraft",when:"A\xf1o 25 despu\xe9s del Portal Oscuro, la \xe9poca de Forever"},beyond:{title:"Despu\xe9s de Classic",when:"Expansiones posteriores (no forman parte de Forever)"}},categories:{chapter:"La historia de Warcraft",class:"Clases",race:"Razas",zone:"Zonas",instance:"Mazmorras y bandas",item:"Objetos legendarios",term:"Glosario"},notice:"Texto original escrito para WoW Forever Path. Los datos se contrastaron con las fuentes indicadas; las p\xe1ginas de warcraft.wiki.gg (CC BY-SA 4.0) y los art\xedculos de Blizzard se usaron como referencia, sin copiar su texto. World of Warcraft y Blizzard son marcas comerciales de Blizzard Entertainment, Inc."}},983,[984,985,986,987,988,989,990,991,992,993]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters1",{enumerable:!0,get:function(){return o}});const o={"chapter:titans-and-old-gods":{title:"Los titanes y los Dioses Antiguos",summary:"Antes de cualquier reino mortal, los titanes del Pante\xf3n lucharon contra los Dioses Antiguos por el alma de un mundo joven, y Azeroth a\xfan lleva las cicatrices.",when:"Antes de la historia escrita",body:["Mucho antes de que los mortales llevaran registros, los titanes recorr\xedan la inmensa oscuridad del cosmos: almas del mundo convertidas en gigantes vivientes. Los m\xe1s nobles se reunieron en el Pante\xf3n y buscaron entre las estrellas almas del mundo dormidas como las suyas. En lo m\xe1s hondo de Azeroth percibieron una de una promesa extraordinaria, pero poderes m\xe1s oscuros la hab\xedan encontrado antes.","Los se\xf1ores del Vac\xedo hab\xedan arrojado a sus siervos, los Dioses Antiguos, sobre aquel mundo joven. Y'Shaarj, C'Thun, Yogg-Saron y N'Zoth hundieron sus cuerpos en la corteza y alzaron el Imperio Negro, con los se\xf1ores elementales del fuego, la tierra, el aire y el agua como generales. Cuando lleg\xf3 el Pante\xf3n, sus ej\xe9rcitos forjados por los titanes destrozaron las ciudadelas del imperio. El Gran Padre Aman'Thul arranc\xf3 a Y'Shaarj del suelo, pero el golpe abri\xf3 una herida por la que se desangraba la savia arcana del mundo. Los titanes comprendieron que matar a los dem\xe1s pod\xeda acabar con la propia Azeroth.","As\xed que los guardianes eligieron prisiones. C'Thun, Yogg-Saron y N'Zoth fueron encadenados en las profundidades de la tierra, y los se\xf1ores elementales fueron desterrados al Plano Elemental, cuyos reinos incluyen Skywall y las Tierras de Fuego. Los guardianes calmaron la herida sangrante hasta convertirla en un lago resplandeciente, el Pozo de la Eternidad, moldearon monta\xf1as y mares y dejaron c\xe1maras tit\xe1nicas como Uldaman. Tras la ca\xedda de un monstruoso protodrag\xf3n llamado Galakrond, el Pante\xf3n elev\xf3 a cinco grandes dragones a Aspectos para proteger el mundo y despu\xe9s parti\xf3 hacia las estrellas."]},"chapter:sargeras-and-the-burning-legion":{title:"Sargeras y la Legi\xf3n Ardiente",summary:"El mayor campe\xf3n del Pante\xf3n perdi\xf3 la fe en la creaci\xf3n y alz\xf3 una cruzada demon\xedaca para quemarla, y Azeroth se convirti\xf3 en el premio que m\xe1s ansiaba.",when:"Mucho antes de los elfos de la noche",body:["Sargeras era el campe\xf3n del Pante\xf3n, el tit\xe1n que persegu\xeda demonios por todo el cosmos y los encerraba en un mundo prisi\xf3n llamado Mardum. A lo largo de eras de guerra descubri\xf3 lo que de verdad quer\xedan los se\xf1ores del Vac\xedo: corromper un alma del mundo y engendrar su propio tit\xe1n oscuro. Convencido de que la creaci\xf3n ten\xeda defectos que no se pod\xedan salvar, decidi\xf3 que ser\xeda m\xe1s compasivo quemarlo todo.","Destroz\xf3 la prisi\xf3n de Mardum y liber\xf3 a sus demonios como primeras filas de la Legi\xf3n Ardiente. En el mundo de Argus ofreci\xf3 conocimiento y poder a los eredar; sus l\xedderes Kil'jaeden y Archimonde aceptaron, mientras el profeta Velen hu\xeda con quienes se negaron, el pueblo al que m\xe1s tarde llamar\xedan draenei. El Pante\xf3n intent\xf3 detener a su antiguo campe\xf3n y cay\xf3 por su mano.","Desde entonces, la Legi\xf3n fue de mundo en mundo, dirigida por Sargeras y servida por los eredar, los se\xf1ores del terror llamados nathrezim e incontables demonios menores. Azeroth importaba m\xe1s que la mayor\xeda: un alma del mundo a\xfan dormida y ya marcada por los Dioses Antiguos. En la \xe9poca de World of Warcraft, la Legi\xf3n la hab\xeda invadido dos veces, y sus susurros hab\xedan moldeado por igual la historia de elfos, orcos y humanos."]},"chapter:rise-of-the-kaldorei":{title:"El ascenso de los kaldorei",summary:"Los trols dominaron la antigua Kalimdor hasta que una tribu atra\xedda por el Pozo de la Eternidad se convirti\xf3 en los elfos de la noche, cuya reina Azshara levant\xf3 un imperio de una magia asombrosa.",when:"Unos 15 000 a 10 000 a\xf1os antes del Portal Oscuro",body:["En las eras posteriores a la partida de los titanes, Kalimdor era un \xfanico gran continente. Los trols, guiados por los Zandalari, libraron una larga guerra contra los aqir, seres insectoides, restos de los siervos de los Dioses Antiguos, y los empujaron hasta los confines norte y sur de la tierra, donde sus descendientes se convertir\xedan en los nerubianos y los qiraji. Tras la victoria, los trols se dividieron en imperios rivales como los de los Gurubashi y los Amani.","Una tribu trol eligi\xf3 un camino m\xe1s tranquilo. Se asent\xf3 a orillas del Pozo de la Eternidad y, generaci\xf3n tras generaci\xf3n, el poder del Pozo la transform\xf3: su gente se volvi\xf3 m\xe1s alta y longeva, vener\xf3 a la diosa lunar Elune y se llam\xf3 a s\xed misma kaldorei, \xabhijos de las estrellas\xbb. Guiados por el semidi\xf3s Cenarius y otros antiguos esp\xedritus de la naturaleza, pronto eclipsaron a sus primos trols.","Su mayor soberana fue la reina Azshara, adorada por su pueblo y servida por los Altonato, una aristocracia de hechiceros que extra\xedan cada vez m\xe1s poder del Pozo. Su palacio de Zin-Azshari se alzaba en su orilla, y su imperio se extend\xeda por toda Kalimdor. Sin embargo, el hambre de magia de los Altonato envi\xf3 ondas mucho m\xe1s all\xe1 del mundo, y algo inmenso en el Vac\xedo Abisal las sinti\xf3."]},"chapter:war-of-the-ancients":{title:"La Guerra de los Ancestros",summary:"Azshara abri\xf3 el camino a la Legi\xf3n Ardiente, y el mundo estuvo a punto de acabar antes de que el Pozo de la Eternidad se desgarrara a s\xed mismo.",when:"Unos 10 000 a\xf1os antes del Portal Oscuro",body:["Sargeras susurr\xf3 a Azshara y a sus Altonato y les prometi\xf3 un mundo rehecho a su imagen. Le creyeron y, a trav\xe9s del Pozo de la Eternidad, abrieron un portal para la Legi\xf3n Ardiente. Los demonios, dirigidos por Archimonde y Mannoroth, se derramaron sobre Kalimdor y empezaron a masacrar a los mismos kaldorei sobre los que reinaba la reina.","La resistencia se reuni\xf3 en torno a l\xedderes inesperados: Malfurion Tempestira, el primer elfo de la noche que aprendi\xf3 el druidismo de Cenarius; su hermano gemelo Illidan, un hechicero de gran talento; y Tyrande Susurravientos, sacerdotisa de Elune. Los semidioses de la naturaleza y la mayor\xeda de los vuelos dragontinos lucharon a su lado. El Aspecto negro Neltharion ofreci\xf3 un arma, el Alma de Drag\xf3n, pero la volvi\xf3 contra sus aliados; esa traici\xf3n le valdr\xeda el nombre de Alamuerte.","Cuando el propio Sargeras intent\xf3 cruzar el portal, Malfurion y sus aliados desbarataron el hechizo de los Altonato. El Pozo, inestable, implosion\xf3, y lleg\xf3 la Gran Escisi\xf3n: el mar engull\xf3 Zin-Azshari, Kalimdor se parti\xf3 y una tormenta llamada la Vor\xe1gine empez\xf3 a girar donde hab\xeda estado el Pozo. Azshara y su corte desaparecieron bajo las olas, para regresar alg\xfan d\xeda como los naga. De aquel continente \xfanico surgieron las tierras que hoy se conocen como Kalimdor, los Reinos del Este y Rasganorte."]},"chapter:the-long-watch-of-hyjal":{title:"La larga vigilia de Hyjal",summary:"Los supervivientes hicieron crecer un \xc1rbol del Mundo sobre un segundo Pozo, encerraron a Illidan bajo tierra y montaron guardia durante diez mil a\xf1os.",when:"Desde unos 10 000 a\xf1os antes del Portal Oscuro",body:["Los elfos de la noche que escaparon de la Escisi\xf3n se reunieron en el monte Hyjal. All\xed descubrieron que Illidan hab\xeda llevado consigo viales con el agua del antiguo Pozo y hab\xeda vertido una parte en un lago de monta\xf1a, creando un nuevo Pozo de la Eternidad. Temiendo que alg\xfan d\xeda volviera a llamar a la Legi\xf3n, Malfurion y Cenarius encerraron a Illidan en las Barrow Deeps, una prisi\xf3n bajo tierra donde la celadora Maiev Cantosombr\xedo lo vigilar\xeda durante diez mil a\xf1os.","Tres Aspectos, Alexstrasza, Ysera y Nozdormu, respondieron haciendo crecer Nordrassil, el \xc1rbol del Mundo, sobre el nuevo Pozo. Sus ra\xedces sellaron las aguas, y su bendici\xf3n concedi\xf3 a los elfos de la noche la inmortalidad y a los druidas un v\xednculo con el Sue\xf1o Esmeralda, donde muchos de ellos dorm\xedan durante siglos. Tyrande dirig\xeda la Hermandad de Elune y a las Centinelas, que guardaban los bosques mientras los druidas so\xf1aban. La magia arcana qued\xf3 prohibida entre los kaldorei.","No todos los Altonato obedecieron. Algunos fueron desterrados al otro lado del mar y fundaron Quel'Thalas; otros, los Shen'dralar, se ocultaron en la ciudad de Eldre'Thalas, en lo que hoy es Feralas. Sus ruinas se conocen hoy como La Masacre."]},"chapter:exiles-of-quelthalas":{title:"Los exiliados de Quel'Thalas",summary:"Altonato desterrados cruzaron el mar, encendieron la Fuente del Sol y construyeron un reino \xe9lfico en los bosques del norte de Lordaeron.",when:"Unos 6800 a\xf1os antes del Portal Oscuro",body:["Mucho despu\xe9s de la Escisi\xf3n, un grupo de Altonato segu\xeda sin poder renunciar a lo arcano. Sus hechizos imprudentes desataron tormentas sobre Vallefresno, y los elfos de la noche acabaron por desterrarlos. Guiados por Dath'Remar Caminante del Sol, los exiliados navegaron hacia el este a trav\xe9s del Gran Mar y vagaron durante a\xf1os por el nuevo continente en busca de una tierra donde la magia fluyera con fuerza.","Unos 6800 a\xf1os antes del Portal Oscuro la encontraron en el norte de Lordaeron. Dath'Remar verti\xf3 un vial robado de agua del Pozo de la Eternidad en un lago situado sobre un nexo de l\xedneas Ley, y la Fuente del Sol cobr\xf3 vida en un estallido de luz. A su alrededor se alzaron Quel'Thalas y su capital, Lunargenta. Al vivir bajo el sol y no bajo la luna, los exiliados cambiaron con los siglos y se convirtieron en los altos elfos, los quel'dorei.","La tierra no estaba vac\xeda. Guardaba ruinas antiguas sagradas para los trols Amani, que atacaron a los reci\xe9n llegados en cantidades abrumadoras. Los elfos los contuvieron con magia y levantaron Ban'dinoriel, una barrera de piedras r\xfanicas que mantuvo a raya a los Amani. Durante unos cuatro mil a\xf1os, Quel'Thalas prosper\xf3 tras ella mientras los trols esperaban su venganza."]},"chapter:arathor-and-the-troll-wars":{title:"Arathor y las Guerras Trol",summary:"Las tribus dispersas de la humanidad se unieron bajo el rey Thoradin, y una alianza con los elfos quebr\xf3 el Imperio Amani al pie de las Monta\xf1as de Alterac.",when:"Unos 2800 a\xf1os antes del Portal Oscuro",body:["Durante milenios, las tribus humanas de los Reinos del Este lucharon entre s\xed mientras los asaltantes Amani atacaban desde el norte. Unos 2800 a\xf1os antes del Portal Oscuro, Thoradin, de la tribu Arathi, comprendi\xf3 que una humanidad dividida ser\xeda destruida. Mediante matrimonios, promesas y conquistas uni\xf3 a las tribus en el reino de Arathor y construy\xf3 su capital, la ciudad fortaleza de Strom, en las actuales Tierras Altas de Arathi.","Los Amani, revitalizados con ayuda de los Zandalari, atacaron Quel'Thalas en enormes cantidades. Los elfos recurrieron a Arathor. A cambio de soldados humanos, aceptaron ense\xf1ar magia a cien humanos escogidos, los primeros magos humanos. Juntos, elfos y humanos aplastaron al ej\xe9rcito Amani al pie de las Monta\xf1as de Alterac, y el fuego de los magos dispers\xf3 a los trols tan a fondo que su imperio nunca se recuper\xf3.","En se\xf1al de gratitud, los elfos de Quel'Thalas juraron lealtad al linaje de los reyes de Arathor. Strom prosper\xf3 y su pueblo se extendi\xf3 por todo el norte. Los Amani volver\xedan a alzarse muchas veces, y en las Tierras del Interior y las Tierras Altas de Arathi a\xfan hay tribus de trols del bosque que rondan las ruinas de aquella vieja guerra."]},"chapter:guardians-and-the-seven-kingdoms":{title:"Los Guardianes y los Siete Reinos",summary:"La magia humana atrajo a los demonios, as\xed que los magos fundaron Dalaran y eligieron Guardianes que lucharan en secreto, mientras Arathor se divid\xeda en siete reinos.",when:"Los milenios posteriores a las Guerras Trol",body:["La magia se extendi\xf3 por Arathor m\xe1s deprisa que la sabidur\xeda. Los hechizos de los magos debilitaron los muros del mundo y atrajeron la atenci\xf3n de los demonios, de modo que los altos elfos y los magos humanos formaron el Consejo de Tirisfal. En secreto, el consejo eleg\xeda a un \xfanico Guardi\xe1n que portara su poder combinado y persiguiera a los agentes de la Legi\xf3n Ardiente.","Los magos construyeron adem\xe1s su propia ciudad, Dalaran, donde gobernar\xeda el Kirin Tor. Entretanto, los herederos de Arathor se alejaron de Strom y, con los siglos, el imperio se fragment\xf3 en siete reinos humanos: Lordaeron, Stromgarde, Gilneas, Alterac, Kul Tiras, Dalaran y, en el sur, Ventormenta, que durante mucho tiempo se llam\xf3 el reino de Azeroth.","La Guardiana m\xe1s famosa fue Aegwynn, que en Rasganorte abati\xf3 a un avatar del propio Sargeras y sell\xf3 su cuerpo en una tumba bajo el mar. Nunca supo que el esp\xedritu del tit\xe1n oscuro se hab\xeda deslizado dentro de ella. Cuando dio a luz a un hijo, Medivh, el esp\xedritu pas\xf3 a \xe9l, y el \xfaltimo Guardi\xe1n creci\xf3 con un traidor oculto en el alma. Desde su torre de Karazhan, un d\xeda abrir\xeda la puerta a los orcos."]},"chapter:war-of-the-three-hammers":{title:"La Guerra de los Tres Martillos",summary:"Los tres clanes enanos de Forjaz lucharon por el trono, y un thane hechicero derrotado invoc\xf3 a Ragnaros, que abras\xf3 la tierra hasta formar la Monta\xf1a Roca Negra.",when:"Unos 230 a\xf1os antes del Portal Oscuro",body:["Bajo las nieves de Dun Morogh, los enanos excavaron Forjaz, un reino de piedra y artesan\xeda que hund\xeda sus ra\xedces en los terr\xe1neos de los titanes. Tres clanes lo compart\xedan a disgusto: los Barbabronce, los Martillo Salvaje y los Hierro Negro, amantes de la hechicer\xeda. Cuando muri\xf3 el gran rey Modimus Yunquemar, unos 230 a\xf1os antes del Portal Oscuro, su rivalidad estall\xf3 en guerra civil.","Los Barbabronce vencieron y expulsaron a los dem\xe1s. Los Martillo Salvaje construyeron Grim Batol al este, y los Hierro Negro fundaron su propio reino al sur, en las Monta\xf1as Crestagrana. El thane hechicero Thaurissan no pudo aceptar la derrota. Atac\xf3 a ambos rivales a la vez, pero sus ej\xe9rcitos fueron aplastados y su esposa Modgud cay\xf3 en Grim Batol.","Desesperado, Thaurissan busc\xf3 un poder mayor e invoc\xf3 a Ragnaros el Se\xf1or del Fuego, un se\xf1or elemental al que los titanes hab\xedan encarcelado. La llegada del Se\xf1or del Fuego mat\xf3 al thane, desgarr\xf3 la tierra hasta formar La Garganta de Fuego y Las Estepas Ardientes, y alz\xf3 la Monta\xf1a Roca Negra, donde los Hierro Negro supervivientes se convirtieron en sus esclavos. Los Martillo Salvaje abandonaron la maldita Grim Batol por las Tierras del Interior. Sus vecinos gnomos, cuya ciudad de Gnomeregan quedaba muy cerca, se convirtieron en fieles amigos de Forjaz."]},"chapter:corruption-of-the-orcs":{title:"La corrupci\xf3n de los orcos",summary:"En la lejana Draenor, Kil'jaeden convirti\xf3 a los clanes cham\xe1nicos de los orcos en una Horda sanguinaria unida por la sangre demon\xedaca.",when:"Las d\xe9cadas anteriores al Portal Oscuro",body:["En el mundo de Draenor, los orcos viv\xedan en orgullosos clanes de cazadores y chamanes que honraban a sus ancestros y a los esp\xedritus de los elementos. Compart\xedan su mundo, no sin recelos, con los draenei, los eredar que hab\xedan huido de Argus con Velen. Kil'jaeden nunca hab\xeda dejado de perseguir a aquellos exiliados, y en los orcos vio un arma.","Disfrazado como el esp\xedritu de la difunta esposa de Ner'zhul, el se\xf1or demon\xedaco susurr\xf3 al anciano cham\xe1n y lo puso en contra de los draenei. Cuando Ner'zhul vacil\xf3, Kil'jaeden encontr\xf3 un alumno m\xe1s dispuesto en Gul'dan, que fund\xf3 el secreto Consejo de la Sombra y ense\xf1\xf3 a los orcos la magia vil; fueron los primeros brujos. Los elementos enmudecieron y la verde tierra de los orcos empez\xf3 a morir.","En una gran reuni\xf3n, los jefes de clan bebieron la sangre del se\xf1or del foso Mannoroth, y Grom Grito Infernal, del clan Grito de Guerra, bebi\xf3 primero. Llena de furia demon\xedaca, la Horda unida cay\xf3 sobre los draenei y casi los extermin\xf3. Solo el clan Lobo G\xe9lido de Durotan se mantuvo en parte al margen. Cuando termin\xf3 la matanza, Gul'dan necesitaba una nueva guerra, y el amo de Kil'jaeden ya ten\xeda una esperando en Azeroth."]},"chapter:the-first-war":{title:"El Portal Oscuro y la Primera Guerra",summary:"Medivh ayud\xf3 a los orcos a abrir el Portal Oscuro, y la Horda arras\xf3 el reino de Ventormenta.",when:"A\xf1o 0: se abre el Portal Oscuro",body:["Guiados por un Medivh pose\xeddo, los brujos de Gul'dan y el Guardi\xe1n abrieron una grieta entre Draenor y Azeroth en La Ci\xe9naga Negra, el pantano que m\xe1s tarde se marchitar\xeda hasta convertirse en Las Tierras Devastadas. Los orcos cruzaron en tropel lo que lleg\xf3 a conocerse como el Portal Oscuro, y sus exploradores pronto encontraron los ricos campos del reino de Azeroth, la actual Ventormenta.","El rey Llane Wrynn y su campe\xf3n Anduin Lothar resistieron durante a\xf1os. El propio aprendiz de Medivh, Khadgar, descubri\xf3 la traici\xf3n de su maestro y, junto con Lothar y la semiorco Garona, se enfrent\xf3 al Guardi\xe1n en Karazhan y le dio muerte. La victoria lleg\xf3 demasiado tarde. Las partidas de guerra de la Horda arrasaron el reino a sangre y fuego, y dentro de la Horda el astuto Orgrim Martillo Maldito derroc\xf3 a Pu\xf1o Negro y se convirti\xf3 en Jefe de Guerra.","Garona, atada por los hechizos de Gul'dan, asesin\xf3 al rey Llane, y la ciudad de Ventormenta cay\xf3 entre llamas. Lothar reuni\xf3 a los supervivientes, entre ellos al joven hijo de Llane, Varian, y los condujo al otro lado del mar, hasta Lordaeron. Muy al este, en las Riverglades, una regi\xf3n que solo existe en Forever, la Horda arras\xf3 el pueblo de Sunnyglade y se llev\xf3 a sus supervivientes como esclavos."]},"chapter:the-second-war":{title:"La Segunda Guerra",summary:"Los reinos humanos, los elfos, los enanos y los gnomos se unieron en la Alianza de Lordaeron y quebraron la Horda de Martillo Maldito en la Cumbre de Roca Negra.",when:"Unos cinco o seis a\xf1os despu\xe9s del Portal Oscuro",body:["La advertencia de Lothar llev\xf3 al rey Terenas Menethil de Lordaeron a convocar a los reinos humanos. Formaron la Alianza de Lordaeron, con Lothar como comandante supremo; se les unieron los enanos de Forjaz, los gnomos y, fieles a su antiguo juramento al linaje de Arathor, los altos elfos de Quel'Thalas. Para dar esperanza a los soldados, el arzobispo Alonsus Faol fund\xf3 los Caballeros de la Mano de Plata, los primeros paladines, con Uther el Iluminado al frente.","La Horda de Martillo Maldito tambi\xe9n hab\xeda crecido. Ogros, trols Amani al mando de Zul'jin y zapadores goblin luchaban junto a los orcos; el clan Faucedraco us\xf3 el Alma de Drag\xf3n de Alamuerte para esclavizar a los dragones rojos en Grim Batol; Gul'dan alz\xf3 a los primeros caballeros de la muerte. La Horda invadi\xf3 Khaz Modan, quem\xf3 parte de Quel'Thalas y asedi\xf3 la capital de Lordaeron.","En el momento decisivo, Gul'dan traicion\xf3 a Martillo Maldito y zarp\xf3 para hacer emerger la Tumba de Sargeras, llev\xe1ndose dos clanes, los Stormreaver y el Martillo Crepuscular. La Horda, debilitada, se repleg\xf3 a la Monta\xf1a Roca Negra. En la batalla de la Cumbre de Roca Negra, Martillo Maldito mat\xf3 a Lothar, pero su lugarteniente Turalyon quebr\xf3 a la Horda y Khadgar destruy\xf3 el Portal Oscuro. Los orcos supervivientes fueron recluidos en campos de internamiento. En las Riverglades de Forever, ogros del Martillo Crepuscular y orcos Stormreaver que hu\xedan de la Tumba encontraron un nuevo hogar."]}}},984,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters2",{enumerable:!0,get:function(){return o}});const o={"chapter:beyond-the-dark-portal":{title:"M\xe1s all\xe1 del Portal Oscuro",summary:"Ner'zhul reabri\xf3 el portal y desgarr\xf3 Draenor, y Kil'jaeden convirti\xf3 al viejo cham\xe1n en el Rey Ex\xe1nime.",when:"Poco despu\xe9s de la Segunda Guerra",body:["Con Gul'dan muerto y la Horda encarcelada, el anciano Ner'zhul reuni\xf3 a los orcos que quedaban en Draenor. Reabri\xf3 el Portal Oscuro y envi\xf3 asaltantes a Azeroth para robar artefactos poderosos, con la esperanza de abrir portales a nuevos mundos donde su pueblo pudiera escapar.","La Alianza respondi\xf3 con una expedici\xf3n a trav\xe9s del portal al mando de Turalyon y Khadgar, a la que se sumaron la forestal Alleria Brisaveloz, el enano Kurdran Martillo Salvaje y el guerrero Danath Aterratrols. Combatieron a la nueva Horda por todo Draenor, pero los portales de Ner'zhul ya estaban desgarrando el mundo. Para salvar Azeroth, la expedici\xf3n destruy\xf3 el Portal Oscuro desde el otro lado y qued\xf3 atrapada en los restos destrozados que se convertir\xedan en Terrallende.","Ner'zhul escap\xf3 por una de sus grietas y cay\xf3 directamente en manos de Kil'jaeden. El demonio le arrebat\xf3 el cuerpo pero conserv\xf3 su esp\xedritu, lo at\xf3 a una armadura encantada y lo sell\xf3 en un bloque de hielo junto con la espada r\xfanica Agon\xeda de Escarcha. Arrojado a los p\xe1ramos helados de Rasganorte, el Trono Helado se convirti\xf3 en la sede de un nuevo poder: el Rey Ex\xe1nime, cuya tarea era propagar una plaga de no-muerte y debilitar Azeroth para el regreso de la Legi\xf3n."]},"chapter:thrall-and-the-new-horde":{title:"Thrall y la nueva Horda",summary:"Un orco criado como esclavo escap\xf3 de Durnholde, redescubri\xf3 el chamanismo y liber\xf3 a su pueblo de los campos de internamiento.",when:"Los a\xf1os anteriores a la Tercera Guerra",body:["En los campos de internamiento, los orcos se hundieron en un extra\xf1o letargo a medida que la furia demon\xedaca los abandonaba. Lord Aedelas Blackmoore, del castillo de Durnholde, en las Laderas de Trabalomas, hab\xeda encontrado a\xf1os atr\xe1s a un beb\xe9 orco hu\xe9rfano y lo hab\xeda criado como gladiador y futura arma. Llam\xf3 al ni\xf1o Thrall, una palabra que significa esclavo. Solo Taretha Foxton, una joven sirvienta, lo trat\xf3 con bondad, y con su ayuda Thrall logr\xf3 escapar por fin.","Libre por primera vez, Thrall busc\xf3 las leyendas de su propio pueblo. Grom Grito Infernal le mostr\xf3 lo que pod\xeda ser un orco, el anciano Orgrim Martillo Maldito lo nombr\xf3 su segundo, y entre el clan Lobo G\xe9lido, en las Monta\xf1as de Alterac, el cham\xe1n Drek'Thar le ense\xf1\xf3 a hablar con los elementos. All\xed descubri\xf3 que era hijo de Durotan, el jefe de los Lobo G\xe9lido.","Thrall, Grom y Martillo Maldito liberaron un campo tras otro. Martillo Maldito cay\xf3 en combate y leg\xf3 a Thrall su armadura negra y su martillo, y Thrall se convirti\xf3 en Jefe de Guerra de una nueva Horda basada en el honor y el chamanismo, no en la sangre demon\xedaca. En Durnholde derrot\xf3 a Blackmoore, aunque Taretha no sobrevivi\xf3. Ahora Thrall solo quer\xeda un hogar donde su pueblo pudiera vivir en paz."]},"chapter:the-lich-king-and-the-plague":{title:"El Rey Ex\xe1nime y la plaga",summary:"Desde Rasganorte, el Rey Ex\xe1nime extendi\xf3 su alcance hacia el sur, y el archimago Kel'Thuzad propag\xf3 una plaga de no-muerte a trav\xe9s del grano de Lordaeron.",when:"Los preparativos de la Tercera Guerra",body:["Aunque atrapado en el Trono Helado, la mente del Rey Ex\xe1nime alcanzaba todo Rasganorte. Conquist\xf3 el reino ar\xe1cnido de Azjol-Nerub, alz\xf3 a su pueblo como siervos y construy\xf3 una fortaleza alrededor de su trono en Corona de Hielo. Despu\xe9s volvi\xf3 la mirada al sur, hacia los reinos humanos cansados de la guerra.","En Dalaran, el respetado archimago Kel'Thuzad se hab\xeda obsesionado con la nigromancia. Cuando el Kirin Tor rechaz\xf3 sus estudios, respondi\xf3 a la llamada del Rey Ex\xe1nime, viaj\xf3 a Rasganorte y regres\xf3 como su profeta. Fund\xf3 el Culto de los Malditos, que promet\xeda a los pobres de Lordaeron igualdad y vida eterna, y se vali\xf3 de sus miembros para propagar una plaga oculta en cargamentos de grano.","La plaga mataba a sus v\xedctimas y luego las alzaba como no-muertos sin mente: la Plaga. Las aldeas del norte de Lordaeron cayeron una tras otra mientras los reinos discut\xedan sobre impuestos y el coste de los campos de internamiento. Cuando el Kirin Tor y la Mano de Plata comprendieron el peligro, la plaga ya se hab\xeda extendido por las provincias del norte de Lordaeron. Se\xf1ores del terror de la Legi\xf3n Ardiente velaban por la obra del Rey Ex\xe1nime, pues deb\xeda allanar el camino para el regreso de sus amos."]},"chapter:fall-of-lordaeron":{title:"La ca\xedda de Lordaeron",summary:"El pr\xedncipe Arthas persigui\xf3 la plaga hasta su origen, empu\xf1\xf3 Agon\xeda de Escarcha y volvi\xf3 para destruir su propio reino, Quel'Thalas y Dalaran.",when:"La Tercera Guerra, unos 20 a\xf1os despu\xe9s del Portal Oscuro",body:["El pr\xedncipe Arthas Menethil, un joven palad\xedn de la Mano de Plata, parti\xf3 con la hechicera Jaina Valiente para detener la plaga. En Stratholme descubri\xf3 que el grano de la ciudad ya estaba contaminado y orden\xf3 matar a sus habitantes antes de que se alzaran como no-muertos. Uther y Jaina se negaron a seguirlo. Arthas persigui\xf3 al se\xf1or del terror Mal'Ganis hasta Rasganorte, quem\xf3 sus propios barcos para que sus hombres no pudieran marcharse y se hizo con la espada r\xfanica Agon\xeda de Escarcha. La espada le arrebat\xf3 el alma.","Arthas volvi\xf3 a casa como caballero de la muerte del Rey Ex\xe1nime y asesin\xf3 a su padre, el rey Terenas, en su propio sal\xf3n del trono. La Plaga arras\xf3 Lordaeron. Uther cay\xf3 defendiendo la urna que guardaba las cenizas de Terenas, y Arthas condujo a su ej\xe9rcito a Quel'Thalas, quebr\xf3 las defensas de los elfos y us\xf3 la Fuente del Sol para resucitar a Kel'Thuzad como liche. Sylvanas Brisaveloz, general forestal de Lunargenta, muri\xf3 combati\xe9ndolo y fue alzada como alma en pena.","Despu\xe9s, Kel'Thuzad invoc\xf3 al se\xf1or demon\xedaco Archimonde en Dalaran, y la Legi\xf3n Ardiente regres\xf3 a Azeroth. Dalaran qued\xf3 destrozada, y Lordaeron, el mayor de los reinos humanos, desapareci\xf3. En el norte solo quedaron supervivientes dispersos, refugiados y fan\xe1ticos, mientras los no-muertos de Arthas dominaban la tierra."]},"chapter:battle-for-mount-hyjal":{title:"La batalla del monte Hyjal",summary:"Advertidos por un profeta, orcos y humanos navegaron hasta Kalimdor, donde se unieron a los elfos de la noche para detener a Archimonde ante el \xc1rbol del Mundo.",when:"El final de la Tercera Guerra",body:["Un misterioso profeta, Medivh regresado de la muerte, inst\xf3 a Thrall y a Jaina a navegar hacia el oeste, hasta Kalimdor. La Horda de Thrall desembarc\xf3 en sus costas, trab\xf3 amistad con los tauren de Cairne Pezu\xf1a de Sangre y se abri\xf3 paso a trav\xe9s de Los Bald\xedos, y Jaina condujo a refugiados de Lordaeron al mismo continente. En los bosques de Vallefresno, Grom Grito Infernal y su clan Grito de Guerra volvieron a beber sangre demon\xedaca y mataron al semidi\xf3s Cenarius.","Thrall y Jaina colaboraron por primera vez para salvar a Grom. En un \xfaltimo duelo, Grom acab\xf3 con Mannoroth y liber\xf3 a los orcos de la maldici\xf3n de sangre a costa de su propia vida. Mientras tanto, Tyrande Susurravientos despert\xf3 a los druidas y liber\xf3 a Illidan de las Barrow Deeps, con la esperanza de que su poder les sirviera de ayuda. En cambio, \xe9l consumi\xf3 el Cr\xe1neo de Gul'dan, se convirti\xf3 en medio demonio y fue desterrado por su propio hermano.","Archimonde march\xf3 sobre Nordrassil para drenar su poder. Elfos de la noche, humanos y orcos defendieron juntos las laderas del monte Hyjal, ganando tiempo mientras Malfurion preparaba una trampa. Cuando el demonio alcanz\xf3 el \xe1rbol, miles de fuegos fatuos se abalanzaron sobre \xe9l y el poder de Nordrassil lo hizo pedazos. El ej\xe9rcito de la Legi\xf3n qued\xf3 destrozado, pero el \xc1rbol del Mundo sufri\xf3 heridas graves y los elfos de la noche perdieron la inmortalidad que les hab\xeda otorgado."]},"chapter:rise-of-the-forsaken":{title:"El alzamiento de los Renegados",summary:"Al debilitarse el Rey Ex\xe1nime, Sylvanas Brisaveloz se liber\xf3 junto con otros no-muertos y reclam\xf3 las ruinas de Lordaeron como los Renegados.",when:"Justo despu\xe9s de la Tercera Guerra",body:["Tras la ca\xedda de Archimonde, el control del Rey Ex\xe1nime empez\xf3 a flaquear. Illidan, ahora al servicio de Kil'jaeden, atac\xf3 el Trono Helado, y Arthas corri\xf3 al norte para defender a su amo. En Lordaeron, los se\xf1ores del terror intentaron hacerse con la Plaga, y en medio del caos muchos no-muertos recuperaron su propia voluntad.","Sylvanas Brisaveloz fue la primera. Con sus almas en pena y otros no-muertos libres, y con el se\xf1or del terror Varimathras obligado a servirla, derrot\xf3 a sus rivales y reclam\xf3 la capital en ruinas de Lordaeron. Bajo ella se extend\xedan las antiguas criptas reales y las alcantarillas, que se convirtieron en Entra\xf1as. Su pueblo se llam\xf3 a s\xed mismo los Renegados: ya no humanos, rechazados por los vivos y libres del Rey Ex\xe1nime.","Arthas lleg\xf3 a Corona de Hielo, se puso el yelmo del Rey Ex\xe1nime y se fusion\xf3 con \xe9l sobre el Trono Helado; despu\xe9s enmudeci\xf3 tras el hielo. Rodeados de enemigos, los Renegados se unieron a la Horda de Thrall como aliados inc\xf3modos, mientras la Plaga, la Cruzada Escarlata y lo que quedaba de la nobleza de Lordaeron se disputaban las Tierras de la Peste. La historia de Forever contin\xfaa tras la campa\xf1a \xabForsaken Kingdom\xbb de Warcraft III: Reforged, cuyos acontecimientos esta gu\xeda a\xfan no recoge."],unknowns:["Lo que ocurre en la campa\xf1a \xabForsaken Kingdom\xbb de Warcraft III: Reforged, que Forever contin\xfaa, no se describe en las fuentes que usa esta gu\xeda."]},"chapter:durotar-and-theramore":{title:"Durotar y Theramore",summary:"Thrall fund\xf3 Durotar y Orgrimmar, Jaina construy\xf3 Theramore, y ambos mantuvieron una paz fr\xe1gil incluso cuando el padre de Jaina lleg\xf3 para hacer la guerra.",when:"Los a\xf1os posteriores a la Tercera Guerra",body:["Despu\xe9s de Hyjal, Thrall condujo a los orcos a una dura tierra roja en la costa oriental de Kalimdor y la llam\xf3 Durotar en honor a su padre. Su capital, Orgrimmar, honraba a Orgrim Martillo Maldito. Los tauren de Cairne Pezu\xf1a de Sangre se asentaron en las praderas de Mulgore, alrededor de las mesetas de Cima del Trueno, y los trols Lanza Negra de Vol'jin, a quienes Thrall hab\xeda rescatado en su viaje hacia el oeste, se establecieron en las Islas del Eco, frente a la costa de Durotar.","Jaina Valiente fund\xf3 Theramore en una isla del Marjal Revolcafango para los supervivientes humanos que hab\xeda tra\xeddo de Lordaeron. Ella y Thrall hab\xedan luchado codo con codo en Hyjal y acordaron mantener la paz. Esa paz se puso a prueba cuando su padre, el gran almirante Daelin Valiente de Kul Tiras, lleg\xf3 con su flota decidido a destruir a los orcos.","Daelin atac\xf3 la costa de Durotar. Rexxar, un errante semiogro de los Mok'Nathal que se convirti\xf3 en el campe\xf3n de la Horda, uni\xf3 a orcos, trols y tauren contra \xe9l, y Jaina, dividida entre su pueblo y su padre, permiti\xf3 que la Horda atacara a sus tropas en Theramore. Daelin muri\xf3 en la batalla. Jaina lo llor\xf3, pero cumpli\xf3 su palabra, y la inc\xf3moda tregua entre Theramore y Orgrimmar se convirti\xf3 en uno de los pocos puentes entre la Alianza y la Horda."]},"chapter:stormwind-in-shadow":{title:"Ventormenta en la sombra",summary:"La reconstruida Ventormenta se enfrenta a un gremio de canteros traicionado, a un rey desaparecido y a un drag\xf3n oculto en la corte, mientras los gnomos han perdido su ciudad.",when:"A\xf1o 25 despu\xe9s del Portal Oscuro",body:["Tras la Segunda Guerra, el Gremio de Canteros, dirigido por Edwin VanCleef, reconstruy\xf3 la ciudad de Ventormenta a partir de sus cenizas. Cuando terminaron, la C\xe1mara de los Nobles se neg\xf3 a pagarles. Los canteros se rebelaron, fueron expulsados y se convirtieron en la Hermandad Defias, que ahora acecha los P\xe1ramos de Poniente desde minas ocultas y conspira contra la corona.","El rey Varian Wrynn, el ni\xf1o al que Lothar salv\xf3 una vez, desapareci\xf3 de camino a una reuni\xf3n diplom\xe1tica en Theramore; se rumorea que los Defias lo secuestraron y lo retienen en la isla de Alcaz. Su joven hijo Anduin fue coronado, con el Alto Se\xf1or Bolvar Fordrag\xf3n como regente. En la corte, una noble encantadora, Lady Katrana Prestor, gan\xf3 una gran influencia. En realidad era Onyxia, hija de Alamuerte, que conduc\xeda el reino en silencio hacia la ruina.","La Alianza ha cambiado. Lordaeron se ha perdido y los elfos de la noche se unieron a la Alianza despu\xe9s de Hyjal. En Dun Morogh, los trogg brotaron de las profundidades e invadieron Gnomeregan; el desesperado intento de los gnomos de expulsarlos con radiaci\xf3n envenen\xf3 su propia ciudad, y el Manitas Mayor Mekkatorque llev\xf3 a los supervivientes a refugiarse en Forjaz. All\xed reina el rey Magni Barbabronce, cuya Liga de Expedicionarios excava por todo el mundo en busca de los secretos de los titanes."]},"chapter:fire-beneath-blackrock":{title:"Fuego bajo Roca Negra",summary:"En la Monta\xf1a Roca Negra, los enanos Hierro Negro sirven a Ragnaros mientras los orcos de Nefarian dominan la cumbre, y Onyxia protege a su prole en el Marjal Revolcafango.",when:"A\xf1o 25 despu\xe9s del Portal Oscuro",body:["Dos siglos despu\xe9s del error de Thaurissan, sus descendientes a\xfan gobiernan bajo la Monta\xf1a Roca Negra. El emperador Dagran Thaurissan mantiene su corte en Ciudad Forjatiniebla, la ciudad de los Hierro Negro, en lo m\xe1s hondo de las Profundidades de Roca Negra, mientras Ragnaros arde abajo, en el N\xfacleo de Magma, y los enanos trabajan para \xe9l. La princesa Moira Barbabronce, hija del rey Magni, lleg\xf3 a la monta\xf1a como cautiva y se qued\xf3 como esposa del emperador, para furia de su padre.","Las salas superiores pertenecen al Vuelo Negro. Nefarian, hijo de Alamuerte, gobierna la Guarida Alanegra bajo la apariencia de lord V\xedctor Nefarius y dirige a los orcos Roca Negra que nunca se unieron a Thrall, encabezados por el Jefe de Guerra Rend Pu\xf1o Negro en la Cumbre de Roca Negra. El fuego y la sombra libran una guerra fr\xeda dentro de la misma monta\xf1a, y Las Estepas Ardientes y La Garganta de Fuego sufren las consecuencias.","La hermana de Nefarian, Onyxia, la falsa Lady Prestor, tiene su guarida en el Marjal Revolcafango, donde protege a su prole. Para llegar hasta ella hace falta el Drakefire Amulet, que se obtiene con una larga cadena de misiones de cada facci\xf3n que pasa por la Cumbre de Roca Negra. En Forever, la Guarida de Onyxia es una de las tres bandas que abren el 9 de diciembre, junto a dos bandas nuevas en el monte Hyjal."]},"chapter:plaguelands-and-the-scarlet-crusade":{title:"Las Tierras de la Peste y la Cruzada Escarlata",summary:"La Plaga de Kel'Thuzad domina el norte, los fan\xe1ticos de la Cruzada Escarlata combaten por igual a no-muertos y vivos, y unas pocas \xf3rdenes firmes resisten.",when:"A\xf1o 25 despu\xe9s del Portal Oscuro",body:["El coraz\xf3n de Lordaeron es ahora las Tierras de la Peste. Kel'Thuzad dirige all\xed la Plaga desde la necr\xf3polis flotante de Naxxramas, el bar\xf3n Osahendido gobierna a los no-muertos en la arruinada Stratholme y, en la antigua escuela de la familia Barov, Scholomance, el Culto de los Malditos forma a nuevos nigromantes.","Los supervivientes de la Mano de Plata se reagruparon como la Cruzada Escarlata, que jur\xf3 purgar la plaga de la tierra con fuego. Su Gran Cruzado, Saidan Dathrohan, es en secreto el se\xf1or del terror Balnazzar, y la Cruzada se ha vuelto tan fan\xe1tica que mata a cualquier forastero del que sospeche que est\xe1 contaminado. Entre sus bastiones est\xe1n el Monasterio Escarlata en los Claros de Tirisfal, Vega del Amparo, Mano de Tyr y una fortaleza en Stratholme. Incluso sus h\xe9roes arrastran historias m\xe1s oscuras: Renault Mograine traicion\xf3 a su padre Alexandros, el Crematoria, y lo condujo a la muerte.","No todos los paladines se volvieron fan\xe1ticos. Quienes rechazaron la crueldad de la Cruzada formaron el Alba Argenta, que colabora desde la Capilla de la Esperanza de la Luz con cualquiera que luche contra la Plaga. El palad\xedn exiliado Tirion Fordring vive como ermita\xf1o cerca de Vega del Amparo, y los Renegados avanzan hacia el norte desde Tirisfal. El destino de Lordaeron a\xfan no est\xe1 decidido."]},"chapter:azeroth-in-year-twenty-five":{title:"Azeroth en el a\xf1o 25",summary:"El mundo del primer a\xf1o de World of Warcraft, donde transcurre la historia de Forever: una paz fr\xe1gil, viejas amenazas que despiertan y lugares nuevos en el mapa.",when:"A\xf1o 25: la \xe9poca de Forever",body:["Veinticinco a\xf1os despu\xe9s de que el Portal Oscuro se abriera por primera vez, Azeroth es un mundo de supervivientes. La Alianza de Ventormenta, Forjaz, los gnomos y los elfos de la noche se enfrenta a una Horda de orcos, trols, tauren y Renegados, y ning\xfan bando conf\xeda en el otro. En los m\xe1rgenes del mapa despiertan viejos enemigos: siervos del Dios Antiguo C'Thun en Silithus, sacerdotes del dios de la sangre Hakkar en las ruinas trols del sur y la corrupci\xf3n de la Pesadilla Esmeralda, que se cuela en los sue\xf1os de los druidas.","World of Warcraft: Forever transcurre justo en este momento. Blizzard lo mantiene ah\xed de forma indefinida, despu\xe9s de la campa\xf1a \xabForsaken Kingdom\xbb de Warcraft III: Reforged y antes de The Burning Crusade, y afirma que su historia no comparte la continuidad del World of Warcraft actual. Forever a\xf1ade lugares que el juego original nunca tuvo: las Riverglades, al este de las Tierras Inh\xf3spitas, donde Farholde Keep resiste frente al Martillo Crepuscular; una Dalaran en restauraci\xf3n cuya barrera de ocultaci\xf3n ha ca\xeddo; y mazmorras que van desde las tumbas reales del Hall of Thanes hasta la instalaci\xf3n tit\xe1nica de Shaper's Terrace.","Forever tambi\xe9n abre a los jugadores un pueblo nuevo: los Skyborne de Zephras Isle, una isla que flota en Skywall, el Plano Elemental del Aire. Sus elementales de aire desaparecieron hace siglos y la magia que mantiene la isla en el cielo se desvanece; su High Order sirve a la Alianza y sus Windshapers a la Horda. El final de estas historias a\xfan est\xe1 por escribir. Blizzard ha anunciado nuevas bandas, mazmorras y una cadena de misiones legendaria para 2027, y las bandas del monte Hyjal abren el 9 de diciembre."]},"chapter:after-classic":{title:"Ep\xedlogo: despu\xe9s de Classic",summary:"En la l\xednea temporal original, la historia sigui\xf3 por Terrallende, Rasganorte y m\xe1s all\xe1; Forever se queda en el a\xf1o 25 y cuenta la suya.",when:"Expansiones posteriores (no forman parte de Forever)",body:["En la l\xednea temporal original de World of Warcraft, la historia sigui\xf3 avanzando. El Portal Oscuro volvi\xf3 a abrirse y The Burning Crusade llev\xf3 a los aventureros a Terrallende, donde cayeron Illidan y Kael'thas Caminante del Sol. En Wrath of the Lich King, la Alianza y la Horda marcharon sobre Rasganorte, y Arthas fue derrotado en lo alto de la Ciudadela de la Corona de Hielo. En Cataclysm, Alamuerte surgi\xf3 de las profundidades y quebr\xf3 la faz del mundo antes de que los Aspectos y sus aliados mortales lo abatieran.","Las expansiones posteriores llevaron la saga a Pandaria, a un Draenor alternativo, a la derrota final de la Legi\xf3n Ardiente en Argus, a la guerra abierta entre las facciones, a los reinos de los muertos, a las Islas Drag\xf3n y a la larga lucha en torno a la propia alma del mundo de Azeroth. Muchos lugares de esta gu\xeda cambiaron por el camino hasta volverse irreconocibles.","World of Warcraft: Forever no toma ninguno de esos caminos. Se queda en el a\xf1o 25, en una \xabburbuja temporal\xbb al margen de la continuidad del juego actual, y construye su futuro sobre los cimientos del mundo original. La hoja de ruta de Blizzard promete para 2027 nuevas bandas, mazmorras, misiones y una banda ic\xf3nica renovada, de modo que los pr\xf3ximos cap\xedtulos de esta historia ser\xe1n solo de Forever."]}}},985,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"classes",{enumerable:!0,get:function(){return o}});const o={"class:mage":{title:"Mago",summary:"Herederos de los Altonato y de los primeros magos humanos, los magos doblegan el poder arcano en bruto, y cada \xe9poca de la historia gira en torno a uno de ellos.",body:["Los magos dominan lo arcano, la magia pura del orden que anta\xf1o brotaba del Pozo de la Eternidad. Los Altonato de los elfos de la noche fueron los primeros grandes hechiceros, y sus descendientes exiliados, los altos elfos de Quel'Thalas, ense\xf1aron el arte a cien humanos durante las Guerras Trol. Aquellos primeros magos humanos fundaron despu\xe9s Dalaran, donde el Kirin Tor a\xfan custodia los secretos de la hechicer\xeda.","Cada \xe9poca de la historia gira en torno a un mago: Medivh, el \xfaltimo Guardi\xe1n; su aprendiz Khadgar, que destruy\xf3 el Portal Oscuro; el archimago Antonidas, que muri\xf3 defendiendo Dalaran; y Jaina Valiente, que hoy gobierna Theramore. En el a\xf1o 25, nuevos alumnos se forman en el Barrio de los Magos de Ventormenta y en el Barrio de la Magia de Entra\xf1as, y los magos gnomos y trols llevan mucho tiempo junto a humanos y Renegados. Forever abre el camino a los orcos, cuyos lanzadores de hechizos solo conoc\xedan antes el chamanismo y la magia vil, y a la High Order, los \xfanicos Skyborne que pueden ser magos."]},"class:warrior":{title:"Guerrero",summary:"Todos los pueblos de Azeroth tienen sus guerreros, y buena parte de la historia del mundo se escribi\xf3 con su acero.",body:["Todos los pueblos de Azeroth tienen sus guerreros, y buena parte de su historia se escribi\xf3 con su acero. Los soldados de Arathor defendieron la Muralla de Thoradin frente a los Amani; los thanes enanos lucharon por Forjaz en la Guerra de los Tres Martillos; los clanes orcos viv\xedan de la fuerza de sus campeones mucho antes de que se forjara la Horda. Los guerreros conf\xedan en el entrenamiento, la armadura y la furia del combate, no en los hechizos.","Sus h\xe9roes llenan las cr\xf3nicas: Anduin Lothar, el Le\xf3n de Azeroth, que dirigi\xf3 a la Alianza hasta caer en la Cumbre de Roca Negra; Grom Grito Infernal, cuyo sacrificio en el monte Hyjal liber\xf3 a los orcos de la sangre demon\xedaca; y Danath Aterratrols, que se qued\xf3 en Draenor con la expedici\xf3n de la Alianza. En el a\xf1o 25, los guerreros sirven bajo todas las banderas, de los guardias de Ventormenta a los soldados de Orgrimmar, y todas las razas jugables pueden empu\xf1ar las armas. Forever a\xf1ade a sus filas a los Skyborne de ambas \xf3rdenes."]},"class:paladin":{title:"Palad\xedn",summary:"Guerreros sagrados nacidos en la Segunda Guerra, los paladines de la Mano de Plata fueron destrozados por uno de los suyos y hoy siguen luchando bajo nuevas banderas.",body:["Los paladines son guerreros sacerdotes de la Luz Sagrada. El arzobispo Alonsus Faol fund\xf3 su orden, los Caballeros de la Mano de Plata, durante la Segunda Guerra para dar a la Alianza campeones capaces de sanar adem\xe1s de combatir. Uther el Iluminado fue el primero de ellos, y Turalyon, Tirion Fordring y el pr\xedncipe Arthas Menethil prestaron juramento.","La orden fue destrozada por uno de los suyos. Arthas asesin\xf3 a Uther y ayud\xf3 a destruir Lordaeron, y los supervivientes de la Mano de Plata se dispersaron: a un lado, los fan\xe1ticos de la Cruzada Escarlata; al otro, el Alba Argenta y el exiliado Tirion. Los enanos de Forjaz tambi\xe9n llevan la Luz a la batalla. El cambio m\xe1s sorprendente de Forever es que ahora los Renegados tambi\xe9n pueden ser paladines, aunque las fuentes usadas aqu\xed a\xfan no explican c\xf3mo los no-muertos llegaron a empu\xf1ar la Luz."],unknowns:["Las fuentes que usa esta gu\xeda no explican c\xf3mo los paladines Renegados llegaron a empu\xf1ar la Luz en Forever."]},"class:hunter":{title:"Cazador",summary:"Forestales, fusileros y maestros de bestias, los cazadores viven del arco, del arma de fuego y del v\xednculo con un animal leal.",body:["Los cazadores viven del arco, del arma de fuego y del v\xednculo con una bestia. Los forestales de Quel'Thalas, dirigidos durante generaciones por la familia Brisaveloz, guardaban los bosques \xe9lficos; los fusileros enanos y los jinetes de grifo Martillo Salvaje lucharon en la Segunda Guerra; las Centinelas elfas de la noche y los cazadores de cabezas trols recorren los bosques de Kalimdor y de la Vega de Tuercespina.","Algunos de los supervivientes m\xe1s tenaces de la historia son cazadores. Alleria Brisaveloz march\xf3 m\xe1s all\xe1 del Portal Oscuro y nunca volvi\xf3, su hermana Sylvanas luch\xf3 contra Arthas hasta su \xfaltimo aliento, y el maestro de bestias Rexxar se convirti\xf3 en el campe\xf3n de la Horda frente a Daelin Valiente. En Forever, los humanos tambi\xe9n pueden seguir esta vocaci\xf3n, y ambas \xf3rdenes Skyborne cuentan con cazadores entre los suyos."]},"class:rogue":{title:"P\xedcaro",summary:"Esp\xedas, ladrones y asesinos, los p\xedcaros act\xfaan donde el honor dudar\xeda, y algunos de sus gremios han moldeado la historia en silencio.",body:["Los p\xedcaros act\xfaan donde el honor dudar\xeda. Hay ladrones, esp\xedas y asesinos en todas las ciudades, pero algunas de sus organizaciones moldean la historia: el servicio de inteligencia de Ventormenta, el IV:7, dirigido por Mathias Shaw; los asesinos de Ravenholdt, ocultos en las Monta\xf1as de Alterac; el Sindicato, surgido de la nobleza ca\xedda en desgracia de Alterac; y la Hermandad Defias que acecha los P\xe1ramos de Poniente.","La p\xedcara m\xe1s famosa de las primeras guerras fue Garona Halforcen, la esp\xeda semiorco cuya hoja mat\xf3 al rey Llane. En el a\xf1o 25, los instructores de p\xedcaros ense\xf1an en el Casco Antiguo de Ventormenta y en el Barrio de los P\xedcaros de Entra\xf1as, y todas las razas jugables menos los tauren pueden aprender el oficio. Forever a\xf1ade a las sombras a los Skyborne de ambas \xf3rdenes."]},"class:priest":{title:"Sacerdote",summary:"Los sacerdotes sirven a la Luz Sagrada, a la diosa lunar Elune o a poderes m\xe1s antiguos y oscuros; sanan a sus aliados y, cuando es preciso, aniquilan a sus enemigos.",body:["Los sacerdotes sirven a la fe de muchas formas. La Iglesia de la Luz Sagrada de los humanos, con centro en la Catedral de la Luz de Ventormenta y dirigida anta\xf1o por el arzobispo Alonsus Faol, ense\xf1a que la Luz vive en la virtud y no en un \xfanico dios, y los enanos tambi\xe9n la abrazaron. Las sacerdotisas elfas de la noche sirven a la diosa lunar Elune en una hermandad que Tyrande Susurravientos dirige desde la Guerra de los Ancestros.","Otros siguen caminos m\xe1s oscuros. Los sacerdotes Renegados mantienen una fe sombr\xeda propia, los sacerdotes trols honran a los loa de sus ancestros y la magia de las sombras forma parte del oficio de muchos sacerdotes. En Forever, los gnomos, conocidos desde hace mucho como un pueblo de ingenieros, pueden ser sacerdotes por primera vez, y Blizzard les dio hechizos raciales de sacerdote propios."]},"class:shaman":{title:"Cham\xe1n",summary:"Los chamanes piden ayuda a los esp\xedritus de la tierra, el fuego, el agua y el aire; perdida para los orcos durante una generaci\xf3n, Thrall restaur\xf3 la tradici\xf3n.",body:["Los chamanes hablan con los esp\xedritus de la tierra, el fuego, el agua y el aire, y piden en lugar de ordenar. En Draenor, los chamanes orcos guiaban a su pueblo hasta que la corrupci\xf3n de Ner'zhul los sustituy\xf3 por brujos, y durante una generaci\xf3n los elementos dejaron de responder a los orcos. Thrall restaur\xf3 la tradici\xf3n, instruido por Drek'Thar de los Lobo G\xe9lido, y reconstruy\xf3 la Horda en torno a ella.","Los tauren de Mulgore y los trols Lanza Negra mantienen sus propias costumbres cham\xe1nicas, y Thrall sigue dirigiendo a los chamanes de Orgrimmar. Forever a\xf1ade dos reci\xe9n llegados: los enanos, que no ten\xedan chamanes en el juego original, y los Skyborne Windshaper de Zephras Isle, cuya isla flota en Skywall, el Plano Elemental del Aire."],unknowns:["Las fuentes que usa esta gu\xeda no explican c\xf3mo los enanos adoptaron el chamanismo en Forever."]},"class:warlock":{title:"Brujo",summary:"Maestros de la magia vil y de los demonios sometidos, los brujos llegaron a Azeroth con la Horda y caminan por una l\xednea estrecha entre el poder y la ruina.",body:["Los brujos obtienen su poder de la magia vil y someten a los demonios a su voluntad. El arte lleg\xf3 a Azeroth con la Horda: Kil'jaeden se lo ense\xf1\xf3 a Gul'dan, cuyo Consejo de la Sombra convirti\xf3 a los chamanes orcos en brujos y consumi\xf3 la vida de Draenor para alimentar sus hechizos. Los caballeros de la muerte y la maldici\xf3n de la sangre demon\xedaca estuvieron entre sus frutos m\xe1s oscuros.","No todos los brujos sirven a la Legi\xf3n. Los brujos humanos se re\xfanen en secreto bajo la taberna El Cordero Degollado, en Ventormenta, los gnomos y los Renegados estudian el arte y la Horda de Thrall tolera con recelo a sus brujos orcos. Todos los brujos caminan por la misma cuerda floja: el poder es real, y tambi\xe9n el riesgo de que los consuma. En Forever, los trols tambi\xe9n pueden ser brujos."]},"class:druid":{title:"Druida",summary:"Guardianes cambiaformas de la naturaleza instruidos primero por el semidi\xf3s Cenarius, los druidas mantienen el equilibrio del mundo, del Claro de la Luna al Sue\xf1o Esmeralda.",body:["Los druidas protegen el equilibrio de la naturaleza y pueden adoptar la forma de las bestias. Malfurion Tempestira aprendi\xf3 el arte del semidi\xf3s Cenarius y se convirti\xf3 en el primer druida; sus seguidores durmieron durante siglos en el Sue\xf1o Esmeralda mientras las Centinelas vigilaban los bosques de los elfos de la noche. El C\xedrculo Cenarion, con sede en el sagrado Claro de la Luna, re\xfane hoy a druidas de todas las razas.","Tras la Tercera Guerra, Malfurion ense\xf1\xf3 las artes dru\xeddicas a los tauren, y Hamuul T\xf3tem de Runa se convirti\xf3 en el primer druida tauren. En el a\xf1o 25, los druidas tienen graves preocupaciones: el \xc1rbol del Mundo Nordrassil est\xe1 herido, Teldrassil creci\xf3 sin la bendici\xf3n de los Aspectos y una pesadilla se extiende por el Sue\xf1o Esmeralda. En Forever, ambas \xf3rdenes Skyborne cuentan con druidas entre los suyos."]}}},986,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"races",{enumerable:!0,get:function(){return o}});const o={"race:human":{title:"Humanos",summary:"Herederos de Arathor y columna vertebral de la Alianza, los humanos han pagado por cada guerra de la historia de Azeroth y aun as\xed siguen reconstruyendo.",body:["Los humanos descienden de las tribus que el rey Thoradin uni\xf3 en Arathor casi tres mil a\xf1os antes del Portal Oscuro. Los herederos de Arathor fundaron los siete reinos humanos, los elfos instruyeron a sus primeros magos y su fe en la Luz Sagrada dio origen m\xe1s tarde a los paladines. La humanidad sostuvo a la Alianza durante la Primera, la Segunda y la Tercera Guerra, y lo pag\xf3 caro: Ventormenta ardi\xf3 una vez y Lordaeron cay\xf3 ante la Plaga.","En el a\xf1o 25, Ventormenta es el coraz\xf3n del poder humano, reconstruida en piedra blanca pero inquieta por los Defias, la desaparici\xf3n del rey Varian y una corte hechizada por Lady Prestor. Los nuevos humanos empiezan en la Abad\xeda de Villanorte, en el Bosque de Elwynn. Forever permite a los humanos ser cazadores, una vocaci\xf3n que el juego original reservaba a otras razas."]},"race:gnome":{title:"Gnomos",summary:"Brillantes inventores cuyos ancestros fueron m\xe1quinas forjadas por los titanes, los gnomos han perdido su ciudad de Gnomeregan y viven exiliados en Forjaz.",body:["Los gnomos son peque\xf1os de estatura y enormes en ingenio. Sus ancestros, los mecagnomos, eran m\xe1quinas forjadas por los titanes a las que m\xe1s tarde afect\xf3 la maldici\xf3n de la carne, que las convirti\xf3 en seres vivos. En Dun Morogh construyeron Gnomeregan, una ciudad de engranajes y vapor, y se convirtieron en firmes aliados de los enanos de la cercana Forjaz, junto a quienes lucharon en la Segunda Guerra.","Esa ciudad est\xe1 perdida. Los trogg brotaron de las profundidades, y el consejo del mekigeniero Sicco Thermaplugg de inundar Gnomeregan con radiaci\xf3n la envenen\xf3 en su lugar; muchos gnomos murieron y algunos supervivientes se convirtieron en retorcidos gnomos leprosos. El Manitas Mayor Gelbin Mekkatorque llev\xf3 al resto al exilio en Forjaz, mientras Thermaplugg gobierna las ruinas. Forever abre por primera vez el sacerdocio a los gnomos."]},"race:night-elf":{title:"Elfos de la noche",summary:"Los antiguos kaldorei vigilaron Kalimdor durante diez mil a\xf1os; ahora mortales, han plantado un nuevo \xc1rbol del Mundo y se han unido a la Alianza.",body:["Los elfos de la noche, o kaldorei, son el m\xe1s antiguo de los pueblos jugables. Descendientes de trols transformados por el Pozo de la Eternidad, construyeron un imperio de magia, sobrevivieron a la Guerra de los Ancestros y pasaron diez mil a\xf1os como un pueblo retra\xeddo de druidas y Centinelas a la sombra del monte Hyjal. La magia arcana sigue prohibida entre ellos.","La Tercera Guerra les cost\xf3 su inmortalidad, cuando Nordrassil fue herido para destruir a Archimonde. Con Malfurion perdido en el Sue\xf1o Esmeralda, el archidruida Fandral Corzocelada hizo crecer un nuevo \xc1rbol del Mundo, Teldrassil, frente a la costa de Costa Oscura, y la capital Darnassus se alz\xf3 entre sus ramas. Bajo el mando de Tyrande Susurravientos, los elfos de la noche se unieron a la Alianza. Los nuevos elfos de la noche empiezan entre los claros de Teldrassil."]},"race:dwarf":{title:"Enanos",summary:"Hijos de los terr\xe1neos de los titanes, los enanos de Forjaz son aliados tozudos, exploradores incansables y guardianes de una herencia dividida.",body:["Los enanos son tozudos, afectuosos y nacidos de la piedra: sus ancestros fueron los terr\xe1neos, guardianes forjados por los titanes a los que transform\xf3 la maldici\xf3n de la carne. Forjaz, tallada en una monta\xf1a de Dun Morogh, es su capital desde hace eras. La Guerra de los Tres Martillos dividi\xf3 a los clanes: los Barbabronce se quedaron con la ciudad, los Martillo Salvaje se asentaron en las Tierras del Interior y los Hierro Negro cayeron al servicio de Ragnaros.","Bajo el rey Magni Barbabronce, los enanos han luchado en todas las guerras de la Alianza, y la Liga de Expedicionarios, de la que su hermano Brann es una figura destacada, excava ruinas tit\xe1nicas como Uldaman en busca del origen de los enanos. Moira, la hija de Magni, se ha convertido en esposa del emperador de los Hierro Negro, una herida que el rey se toma como algo personal. Forever a\xf1ade el Hall of Thanes bajo Forjaz, lugar de reposo de los monarcas enanos, ahora asaltado por intrusos que se cree que son Hierro Negro, y los enanos pueden seguir el camino del cham\xe1n."]},"race:skyborne-high-order":{title:"Skyborne: High Order",body:["Los Skyborne son el nuevo pueblo jugable de World of Warcraft: Forever, y la High Order es la rama que est\xe1 del lado de la Alianza. Su hogar es Zephras Isle, una isla que flota en Skywall, el Plano Elemental del Aire; la gobierna la Gran Anciana Talaanis Shadowsong y su principal asentamiento es la ciudad de Valanaar. Los elementales de aire que anta\xf1o viv\xedan en la isla con los Skyborne desaparecieron hace siglos, la magia que la sostiene se debilita y se ha perdido el contacto con las islas hermanas de Anvilas y Siroccas mientras los refugiados huyen a Zephras.","Los aventureros de la High Order abandonan la isla en aeronave desde Valanaar hasta Dalaran, en las Monta\xf1as de Alterac. Pueden ser guerreros, cazadores, p\xedcaros, druidas o magos, y son los \xfanicos Skyborne que estudian lo arcano. Sus dones reflejan su hogar: descienden planeando sobre el viento, act\xfaan con celeridad aumentada, golpean con m\xe1s fuerza a los elementales y leen las l\xedneas Ley cercanas para recuperar salud y man\xe1. Para jugar con ellos hace falta el Skyborne Heroic o Epic Pack, opcional."]},"race:skyborne-windshaper":{title:"Skyborne: Windshapers",body:["Los Windshapers son los Skyborne que est\xe1n del lado de la Horda. Al igual que la High Order, proceden de Zephras Isle, en Skywall, el Plano Elemental del Aire, una isla cuyos elementales de aire desaparecieron hace siglos y cuya magia sustentadora se agota poco a poco. A medida que islas como Anvilas y Siroccas enmudecen, los refugiados se hacinan en Zephras, y hasta Zephras ha empezado a desmoronarse.","Los Windshapers dejan Valanaar en aeronave rumbo al Skywatcher Plateau, en Mulgore. Pueden ser guerreros, cazadores, p\xedcaros, druidas o chamanes, y son los \xfanicos Skyborne que siguen el camino del cham\xe1n. Planean sobre el viento, combaten con celeridad aumentada y golpean con m\xe1s fuerza a los elementales, y su propio don, Skysight, acelera sus viajes y dura mucho m\xe1s cerca de una convergencia elemental. Como la High Order, requieren el Skyborne Heroic o Epic Pack, opcional."]},"race:orc":{title:"Orcos",summary:"Antes esclavizados por la sangre demon\xedaca, los orcos fueron liberados por Thrall y ahora reconstruyen su honor en la tierra roja de Durotar.",body:["Los orcos llegaron a Azeroth desde Draenor como la Horda, impulsados por la sangre demon\xedaca y por los brujos de Gul'dan. Derrotados en la Segunda Guerra, languidecieron en campos de internamiento hasta que Thrall, hijo del jefe Lobo G\xe9lido Durotan, los liber\xf3 y restaur\xf3 las costumbres cham\xe1nicas de sus ancestros.","Tras la Tercera Guerra, Thrall condujo a su pueblo a Kalimdor y fund\xf3 Durotar y su capital, Orgrimmar, desde donde el Jefe de Guerra gobierna ahora una Horda compartida con los tauren, los trols Lanza Negra y los Renegados. Los orcos son orgullosos, directos y ferozmente leales, pero su pasado sangriento perdura en los cultistas del Filo Ardiente de Durotar y en el clan Roca Negra, que nunca se uni\xf3 a Thrall. Los nuevos orcos empiezan en el Valle de los Retos. En Forever, los orcos tambi\xe9n pueden ser magos."]},"race:tauren":{title:"Tauren",summary:"Gigantes apacibles de las llanuras que honran a la Madre Tierra, los tauren encontraron un hogar en Mulgore y se unieron a la Horda por gratitud.",body:["Los tauren son n\xf3madas pac\xedficos de gran tama\xf1o que honran a la Madre Tierra y recorren las llanuras de Kalimdor desde hace eras. En los a\xf1os de la Tercera Guerra los acosaban los centauros, hasta que la Horda de Thrall, reci\xe9n llegada, ayud\xf3 al pueblo de Cairne Pezu\xf1a de Sangre a alcanzar la seguridad de Mulgore.","Cairne uni\xf3 a muchas tribus dispersas y fund\xf3 Cima del Trueno sobre grandes mesetas que dominan las praderas de Mulgore, y los tauren se unieron a la Horda por gratitud y respeto. Sus druidas aprendieron del propio Malfurion Tempestira, y sus chamanes y cazadores mantienen vivas antiguas tradiciones. Tribus rivales como los T\xf3tem Siniestro, que ven con malos ojos el v\xednculo con los orcos, siguen siendo una preocupaci\xf3n constante. Los j\xf3venes tauren empiezan en el Campamento Narache, en Mulgore."]},"race:troll":{title:"Trols",summary:"Herederos de imperios ca\xeddos, la mayor\xeda de los trols a\xfan odian a las dem\xe1s razas; la tribu Lanza Negra, en cambio, jur\xf3 lealtad a Thrall y a la Horda.",body:["Los trols gobernaron en otro tiempo vastos imperios: los Gurubashi en las selvas del sur, los Amani en los bosques del norte y los Zandalari, que se consideran los primeros de todos los trols. Las guerras contra los elfos de la noche, los altos elfos y los humanos quebraron esos imperios, y la mayor\xeda de las tribus a\xfan alimentan viejos odios y rezan a los loa, los dioses espirituales de sus ancestros.","La tribu Lanza Negra es distinta. Expulsados de la Vega de Tuercespina por tribus rivales, los Lanza Negra luchaban por su isla natal cuando lleg\xf3 la flota de Thrall, zarandeada por la tormenta; su jefe Sen'jin muri\xf3 all\xed y su hijo Vol'jin jur\xf3 lealtad a la Horda en nombre de la tribu. Se asentaron en las Islas del Eco, frente a Durotar, aunque la magia oscura del m\xe9dico brujo Zalazane los ha empujado al Poblado Sen'jin, en tierra firme. En Forever, los Darkspear Raiders tambi\xe9n se disputan las Darkspear Islands, frente al Marjal Revolcafango, y los trols pueden ser brujos."]},"race:undead":{title:"No-muertos",summary:"V\xedctimas de la peste alzadas de entre los muertos que se liberaron del Rey Ex\xe1nime, los Renegados gobiernan Entra\xf1as bajo las ruinas de Lordaeron y no conf\xedan en nadie.",body:["Los Renegados fueron anta\xf1o ciudadanos de Lordaeron, muertos por la peste y alzados por la Plaga, que recuperaron su libre albedr\xedo cuando el poder del Rey Ex\xe1nime flaque\xf3. Liderados por la reina alma en pena Sylvanas Brisaveloz, reclamaron las ruinas de la capital de Lordaeron e hicieron de Entra\xf1as, bajo ellas, su hogar. Sus tierras, los Claros de Tirisfal y el Bosque de Arg\xe9nteos, se las disputan la Plaga y la Cruzada Escarlata.","Los Renegados se unieron a la Horda como aliados por necesidad; pocos de los vivos conf\xedan en ellos, y el trabajo secreto de la Real Sociedad de Boticarios en una nueva peste da a sus socios buenos motivos. Los nuevos Renegados se alzan en Camposanto, en los Claros de Tirisfal. Forever a\xf1ade la mazmorra Ruins of Lordaeron, donde los Renegados intentan recuperar la ciudad destrozada que se alza sobre Entra\xf1as, y permite paladines Renegados, una combinaci\xf3n que las fuentes usadas aqu\xed a\xfan no explican."],unknowns:["Las fuentes que usa esta gu\xeda no explican c\xf3mo surgieron los paladines Renegados en Forever."]}}},987,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"zones1",{enumerable:!0,get:function(){return o}});const o={"zone:dun-morogh":{title:"Dun Morogh",summary:"Valles nevados alrededor de Forjaz, hogar de los enanos y de los gnomos que perdieron su ciudad.",body:["Rodeado por los picos de Khaz Modan, Dun Morogh es una tierra de campos nevados, lagos helados y atalayas enanas. Su coraz\xf3n es Forjaz, la ciudad de monta\xf1a del clan Barbabronce bajo el rey Magni, mientras los j\xf3venes enanos y gnomos empu\xf1an las armas por primera vez en el resguardado Valle de Crestanevada y alrededor de la aldea cervecera de Kharanos. Los trols Peloescarcha y los troggs excavadores acosan los valles.","Al oeste se encuentra Gnomeregan, la maravilla de la ingenier\xeda gnoma, perdida cuando los troggs brotaron de las profundidades y la desesperada inundaci\xf3n de radiaci\xf3n de sus defensores envenen\xf3 la ciudad. Sus supervivientes viven ahora como invitados en Forjaz. En Forever, alguien ha asaltado las tumbas reales del Hall of Thanes bajo la ciudad, y se sospecha de intrusos Hierro Negro."]},"zone:durotar":{title:"Durotar",summary:"La dura costa roja que Thrall bautiz\xf3 en honor a su padre y donde los orcos construyeron Orgrimmar.",body:["Cuando Thrall llev\xf3 a la Horda a Kalimdor, reclam\xf3 esta franja de costa oriental agrietada por el sol y la llam\xf3 Durotar en honor a su padre, Durotan. Su tierra roja y sus ca\xf1ones pedregosos recordaban a los orcos a Draenor. Expulsaron a los jabaespines de la regi\xf3n y alzaron Orgrimmar, llamada as\xed por Orgrim Martillo Maldito, en una hondonada de monta\xf1a al norte.","Los j\xf3venes orcos y trols se ponen a prueba en el Valle de los Retos antes de seguir hacia Cerrotajo. En la costa, los trols Lanza Negra ocupan el Poblado Sen'jin desde que el m\xe9dico brujo Zalazane esclaviz\xf3 a los suyos en las Islas del Eco, y soldados kultirenses resisten en el Fuerte de Tiragarde. Los cultistas del Filo Ardiente acechan en las colinas, y su culto hermano, el Filo Abrasador, se esconde en la Sima \xcdgnea, bajo la capital."]},"zone:elwynn-forest":{title:"Bosque de Elwynn",summary:"El verde coraz\xf3n del reino de Ventormenta, donde muchos h\xe9roes humanos dan sus primeros pasos.",body:["El Bosque de Elwynn es el apacible coraz\xf3n del reino de Ventormenta: robledales, granjas y lagos alrededor de las murallas blancas de la ciudad de Ventormenta, reconstruida despu\xe9s de que la Horda la arrasara en la Primera Guerra. Los novicios se forman en la Abad\xeda de Villanorte, y los viajeros descansan en la Posada Orgullo de Le\xf3n, en Villadorada.","La paz es m\xe1s fr\xe1gil de lo que parece. Los k\xf3bolds se han hecho con las minas, los gnolls Zarparr\xedo saquean las granjas del oeste, los m\xfarlocs abarrotan los lagos y los bandidos Defias se extienden desde los vecinos P\xe1ramos de Poniente. Dentro de la capital, Las Mazmorras han ca\xeddo en manos de un mot\xedn de reclusos Defias."]},"zone:mulgore":{title:"Mulgore",summary:"Las llanuras azotadas por el viento de los tauren, coronadas por las mesetas de Cima del Trueno.",body:["Mulgore es la pradera ancestral de los tauren, una cuenca verde de llanuras y mesetas cercada por monta\xf1as, con un \xfanico paso hacia el este, hacia Los Bald\xedos. Durante generaciones, los tauren n\xf3madas sufrieron el acoso de los centauros, hasta que la Horda de Thrall ayud\xf3 al Gran Jefe Cairne Pezu\xf1a de Sangre a llevar a su pueblo a casa. Aqu\xed levantaron sus primeros asentamientos duraderos: el Poblado Pezu\xf1a de Sangre y la capital, Cima del Trueno, construida sobre alt\xedsimas mesetas unidas por puentes de cuerda.","Los j\xf3venes tauren se entrenan en el Campamento Narache, en la Mesa de la Nube Roja, mientras gnolls, jabaespines y prospectores de Ventura y C\xeda. causan problemas en las llanuras. En Forever, los Skyborne de la Horda llegan en aeronave desde Zephras Isle al Skywatcher Plateau."]},"zone:teldrassil":{title:"Teldrassil",summary:"El nuevo \xc1rbol del Mundo de los elfos de la noche frente a la costa norte de Kalimdor, con Darnassus entre sus ramas.",body:["Despu\xe9s de que la Tercera Guerra les costara su inmortalidad, los druidas elfos de la noche hicieron crecer un nuevo \xc1rbol del Mundo frente a la costa norte de Kalimdor. Lo llamaron Teldrassil, \xabcorona de la tierra\xbb, y construyeron Darnassus entre sus ramas, una ciudad de templos ba\xf1ados por la luna donde la Suma Sacerdotisa Tyrande Susurravientos gu\xeda a su pueblo.","El \xe1rbol se plant\xf3 sin la bendici\xf3n de los Aspectos drag\xf3n, y su crecimiento no ha sido limpio. La corrupci\xf3n se ha infiltrado en su fauna y ha vuelto salvajes a los f\xfarbolgs Gnarlpine. Los novicios elfos de la noche empiezan en la Ca\xf1ada Umbr\xeda, y los barcos de la Aldea Rut'theran, junto a las ra\xedces, unen la isla con Costa Oscura."]},"zone:tirisfal-glades":{title:"Claros de Tirisfal",summary:"L\xfagubres claros alrededor de las ruinas de la capital de Lordaeron, hoy el coraz\xf3n de los Renegados.",body:["En los Claros de Tirisfal se alzaba anta\xf1o la capital de Lordaeron, y el Consejo de Tirisfal, la orden que eleg\xeda a los Guardianes, tom\xf3 su nombre de sus reuniones secretas en estas colinas tranquilas. La peste y la ca\xedda del reino dejaron la tierra bajo un cielo verde y enfermizo. Bajo el palacio en ruinas, los Renegados de Sylvanas Brisaveloz han hecho de Entra\xf1as su hogar; sus muertos reci\xe9n alzados despiertan en Camposanto y se re\xfanen en el pueblo de R\xe9mol.","Los enemigos acechan por todos lados: restos de la Plaga rondan las granjas, y los fan\xe1ticos de la Cruzada Escarlata ocupan el Monasterio Escarlata, al noreste. En Forever, los Renegados intentan recuperar la ciudad destrozada que tienen encima, donde se dice que un nigromante re\xfane poder en las Ruins of Lordaeron."]},"zone:zephras-isle":{title:"Zephras Isle",summary:"Una isla voladora de Skywall, el Plano Elemental del Aire, y la zona inicial de los Skyborne de Forever.",body:["Zephras Isle es la zona inicial de los Skyborne, la raza jugable nueva de World of Warcraft: Forever, que se desbloquea con el Skyborne Heroic o Epic Pack opcional. La isla flota en Skywall, el Plano Elemental del Aire, donde los Skyborne la compart\xedan anta\xf1o con elementales de aire. Esos elementales desaparecieron hace varios siglos, y la magia que mantiene la isla en el aire se ha ido debilitando desde entonces. Con ellos se perdi\xf3 el contacto con las dem\xe1s islas Skyborne, Anvilas y Siroccas.","Ahora esas islas se derrumban, los refugiados huyen a Zephras y la propia Zephras ha empezado a resquebrajarse. La Gran Anciana Talaanis Shadowsong gobierna desde la ciudad de Valanaar, cuyos muelles a\xe9reos env\xedan aeronaves a Dalaran, en las Monta\xf1as de Alterac, para la Alianza, y al Skywatcher Plateau, en Mulgore, para la Horda."],unknowns:["Las fuentes que usa esta gu\xeda no explican por qu\xe9 desaparecieron los elementales de aire.","Las fuentes de esta gu\xeda a\xfan no tratan el origen profundo de los Skyborne ni el de sus \xf3rdenes.","Los antiguos gobernantes de la isla, los Shal\u2019nan, solo se nombran, no se describen."]},"zone:darkshore":{title:"Costa Oscura",summary:"Una costa brumosa sembrada de ruinas que los elfos de la noche vigilan desde el puerto de Auberdine.",body:["Costa Oscura es una larga franja de la costa noroeste de Kalimdor, oscurecida por la lluvia y salpicada de las ruinas desmoronadas de ciudades kaldorei de antes de la Gran Escisi\xf3n. Los elfos de la noche la reclaman como parte de su nuevo reino, y las Centinelas patrullan el camino que va hacia el sur desde el puerto de Auberdine hasta Vallefresno.","El peligro acecha fuera del camino: los fantasmas recorren las viejas ruinas, los naga y los m\xfarlocs acechan en las playas, los f\xfarbolgs se vuelven salvajes en los bosques, y los cultistas del Martillo Crepuscular y del Dark Strand se ocultan en las colinas. Los barcos de Auberdine navegan a Teldrassil, al Puerto de Menethil y, en Forever, a Ventormenta; adem\xe1s, una nueva ruta de Forever llega desde Costasur."]},"zone:loch-modan":{title:"Loch Modan",summary:"Un valle de las tierras altas enanas cuyo gran lago est\xe1 contenido por el Stonewrought Dam.",body:["Al este de Dun Morogh se encuentra Loch Modan, un fresco valle de monta\xf1a de pinos y abedules alrededor de un gran lago contenido por el Stonewrought Dam, una de las maravillas de la ingenier\xeda enana. Pocos recuerdan que lo dise\xf1\xf3 un arquitecto Hierro Negro. El pueblo de Thelsamar vigila el camino, y la Estaci\xf3n de Algaz guarda el paso que lleva al norte, a Los Humedales.","El valle recuerda la Segunda Guerra, cuando la Horda lo arras\xf3 antes de que los enanos de Forjaz la hicieran retroceder. Hoy el peligro sube desde abajo: excavaciones como la de Ironband despertaron a los troggs de las profundidades, los ogros Mo'grosh dominan las colinas y los enanos Hierro Negro atacan la propia presa."]},"zone:silverpine-forest":{title:"Bosque de Arg\xe9nteos",summary:"Un bosque de pinos embrujado en la costa oeste de Lordaeron, disputado por los Renegados, los huargen y los \xfaltimos humanos de la regi\xf3n.",body:["El Bosque de Arg\xe9nteos se extiende a lo largo de la escarpada costa oeste de Lordaeron; sus pinos de corteza plateada est\xe1n hoy enfermos y envueltos en niebla. Los Renegados dominan el norte desde El Sepulcro, mientras supervivientes humanos y magos enviados desde Dalaran se aferran a Molino \xc1mbar y al sur. M\xe1s all\xe1, Gilneas se ha encerrado tras la Muralla de Cringris.","La sombra m\xe1s profunda del bosque es el Castillo de Colmillo Oscuro, antiguo castillo del bar\xf3n Silverlaine. Durante la Tercera Guerra, el archimago de Dalaran Arugal invoc\xf3 huargen para luchar contra la Plaga, perdi\xf3 el control sobre ellos y enloqueci\xf3; ahora llama a las bestias sus hijos. Su maldici\xf3n ha alcanzado la cercana aldea de Pyrewood, cuyos habitantes se convierten en huargen al caer la noche."]},"zone:westfall":{title:"P\xe1ramos de Poniente",summary:"El granero abandonado de Ventormenta, convertido en territorio de la Hermandad Defias.",body:["Los P\xe1ramos de Poniente fueron anta\xf1o el granero de Ventormenta, una costa de campos dorados y molinos de viento. Desde la Segunda Guerra, gran parte de la tierra est\xe1 en barbecho, y el reino no ha tenido ni dinero ni soldados que dedicarle. En ese vac\xedo se meti\xf3 la Hermandad Defias: los canteros que reconstruyeron Ventormenta y se convirtieron en forajidos cuando los nobles se negaron a pagarles, liderados por Edwin VanCleef.","Los Defias gobiernan el pueblo en ruinas de Arroyo de la Luna y esconden un astillero en las Minas de la Muerte, bajo \xe9l, mientras los gnolls y los g\xf3lems de cosecha descontrolados atacan las granjas que quedan. Solo la Milicia del Pueblo, reunida por Gryan Stoutmantle en la Colina del Centinela, sigue plant\xe1ndoles cara."]},"zone:barrens":{title:"Los Bald\xedos",summary:"Una inmensa sabana en el coraz\xf3n de Kalimdor, atravesada por el Camino del Oro y dominada sobre todo por la Horda.",body:["Los Bald\xedos son una vasta sabana de \xe1rboles espinosos, oasis y cauces secos en el coraz\xf3n de Kalimdor. Antes de la Gran Escisi\xf3n se alzaban aqu\xed ciudades de los elfos de la noche; hoy la Horda domina la tierra desde El Cruce y el Campamento Taurajo, los goblins de Trinquete comercian por mar con Bah\xeda del Bot\xedn y los soldados de la Alianza vigilan desde Northwatch Hold. En Forever, Durotar Supply and Logistics comercia desde un campamento al oeste de El Cruce.","Los centauros Kolkar, los jabaespines y las arp\xedas asaltan a los viajeros a lo largo del Camino del Oro. Bajo tierra hay tres viejas heridas: las Cuevas de los Lamentos, donde el sue\xf1o de un druida se convirti\xf3 en pesadilla, y las espinosas madrigueras del Horado Rajacieno y la Zah\xfarda Rajacieno, sagradas para los jabaespines."]},"zone:redridge-mountains":{title:"Monta\xf1as Crestagrana",summary:"Colinas rojas y un lago tranquilo al este de Elwynn, donde Villa del Lago resiste frente a los gnolls y los orcos Roca Negra.",body:["Al este de Elwynn se alzan las Monta\xf1as Crestagrana, una regi\xf3n de piedra roja, olmos altos y r\xedos impetuosos que abastece a Ventormenta de madera, pescado y grano. Su pueblo principal, Villa del Lago, est\xe1 a orillas del Lake Everstill, y el cruce de Three Corners lo une con Elwynn y el Bosque del Ocaso.","Aqu\xed la paz es fr\xe1gil. Los gnolls de Crestagrana saquean las granjas, y los orcos Roca Negra llegados de Las Estepas Ardientes han tomado Stonewatch Keep y acampan en Render's Valley. Hace mucho, los enanos Hierro Negro construyeron un reino en estas monta\xf1as, hasta que la invocaci\xf3n de Ragnaros por parte de Thaurissan abras\xf3 las tierras del norte. En Forever, la Azeroth Commerce Authority comercia en Three Corners, y varios pasos llevan al este, hacia las Riverglades."]},"zone:stonetalon-mountains":{title:"Sierra Espol\xf3n",summary:"Picos escarpados al oeste de Los Bald\xedos, sagrados para elfos de la noche y tauren y marcados por la tala de los goblins.",body:["La Sierra Espol\xf3n se alza al oeste de Los Bald\xedos; es el hogar ancestral de las arp\xedas, aunque sus bandadas se han extendido desde entonces mucho m\xe1s all\xe1. La cumbre m\xe1s alta, el Pico Espol\xf3n, es sagrada tanto para los elfos de la noche como para los tauren; los elfos de la noche mantienen un t\xfamulo y un claro cerca de la cima, los tauren ocupan el Refugio Roca del Sol en las alturas centrales y los trols Lanza Negra acampan en Malaka'jin.","Ventura y C\xeda. es quien m\xe1s da\xf1o ha hecho a la tierra: sus goblins han despojado al Windshear Crag de casi todos sus \xe1rboles, asfixiando el aire con holl\xedn y contaminando el agua con petr\xf3leo. Los tauren T\xf3tem Siniestro, los k\xf3bolds y las peligrosas bestias del Charred Vale no hacen m\xe1s seguros los caminos."]},"zone:ashenvale":{title:"Vallefresno",summary:"El bosque ancestral de los elfos de la noche, donde empez\xf3 la guerra con la Horda por su madera.",body:["Vallefresno es el bosque ancestral de los elfos de la noche, una espesura de sombras violetas y \xe1rboles antiqu\xedsimos que se extiende desde la Playa de Zoram hasta los l\xedmites de Los Bald\xedos. Los kaldorei ocupan Astranaar y una serie de puestos avanzados, y las Centinelas protegen sus arboledas con fiereza.","Durante la Tercera Guerra, los orcos Grito de Guerra de Grom Grito Infernal se adentraron en estos bosques, volvieron a beber sangre demon\xedaca y mataron al semidi\xf3s Cenarius; Grom muri\xf3 despu\xe9s al acabar con el se\xf1or del foso Mannoroth en el lugar que hoy se llama Ca\xf1\xf3n del Demonio Ca\xeddo. Los orcos siguen talando el este desde el Puesto del Hachazo y los campamentos Grito de Guerra, y la vieja disputa sigue latente. Los s\xe1tiros rondan las ruinas, y en la costa se encuentran las Cavernas de Brazanegra, un templo de Elune sumergido."]},"zone:duskwood":{title:"Bosque del Ocaso",summary:"Un rinc\xf3n antes luminoso de Elwynn engullido por una noche sin fin, defendido por la tozuda gente de Villa Oscura.",body:["El Bosque del Ocaso era anta\xf1o la parte sur del Bosque de Elwynn, hogar de los pueblos que hoy se llaman Villa Oscura y Cerro del Cuervo. Entonces cay\xf3 una sombra que nunca se ha levantado, ligada al destino de la Guada\xf1a de Elune de los elfos de la noche. Bajo su crep\xfasculo eterno los \xe1rboles se retorcieron, y huargen, no-muertos y ogros del Paso de la Muerte empezaron a merodear.","Ventormenta ha dejado la regi\xf3n en gran medida a su suerte. La Guardia Nocturna de Villa Oscura vigila el camino principal, el cementerio del Cerro del Cuervo se llena de muertos sin descanso y, en lo m\xe1s hondo del bosque, la Arboleda del Crep\xfasculo cobija un gran \xe1rbol y un portal al Sue\xf1o Esmeralda."]},"zone:wetlands":{title:"Los Humedales",summary:"Marismas grises empapadas de lluvia que vigilan el camino entre Khaz Modan y Lordaeron.",body:["Los Humedales son una marisma fr\xeda y envuelta en niebla entre las monta\xf1as de Khaz Modan y el mar. Anta\xf1o la regi\xf3n estaba llena de fortalezas enanas; la guerra ha destruido la mayor\xeda. El Puerto de Menethil es aqu\xed el ancla de la Alianza, un puerto cuyos barcos navegan a Theramore y, en Forever, hasta Costasur. Los viajeros llegan por la asediada Dun Algaz o por el da\xf1ado Puente Thandol.","Al este se alza Grim Batol, la ciudad maldita de los Martillo Salvaje donde el clan Faucedraco mantuvo cautivos a los dragones rojos durante la Segunda Guerra; renegados Faucedraco a\xfan recorren la marisma, y los enanos Hierro Negro ocupan Dun Modr. En Forever, una extra\xf1a niebla y destellos de luz sobre el Whelgar's Excavation Site conducen a una mazmorra de ensamblajes de los titanes."]},"zone:hillsbrad-foothills":{title:"Laderas de Trabalomas",summary:"Verdes colinas donde Costasur y Molino Tarren se vigilan mutuamente cerca de las ruinas de Durnholde.",body:["Las verdes y f\xe9rtiles colinas de Trabalomas se extienden justo al sur del antiguo reino de Alterac. Aqu\xed se enfrentan dos pueblos: Costasur, de la Alianza, en la costa, y el puesto de los Renegados en Molino Tarren, en las colinas, y su enemistad mantiene los campos ensangrentados. Los m\xfarlocs y el Sindicato agravan los problemas.","En una loma al este se alza el Castillo de Durnholde, antiguo cuartel general de los campos de internamiento orcos, donde lord Aedelas Blackmoore cri\xf3 al joven Thrall como gladiador antes de que este escapara para liberar a su pueblo; hoy el Sindicato ocupa sus ruinas. En Forever, las misiones que abren el camino a la City of Dalaran empiezan en ambos pueblos, y los barcos hacen escala en Costasur."]},"zone:thousand-needles":{title:"Las Mil Agujas",summary:"Un ca\xf1\xf3n de agujas de piedra y llanuras de sal donde tauren, centauros y goblins aficionados a las carreras comparten un terreno inestable.",body:["Las Mil Agujas son un enorme ca\xf1\xf3n seco de alt\xedsimas mesetas de piedra en el sur de Kalimdor, al que se llega desde Los Bald\xedos por el Gran Elevador. Los tauren del Poblado Viento Libre viven en lo alto de las mesetas, mientras que los T\xf3tem Siniestro, un clan tauren hostil a Cairne Pezu\xf1a de Sangre, ocupan el Darkcloud Pinnacle. Los centauros Galak recorren el fondo del ca\xf1\xf3n y las arp\xedas anidan entre las agujas.","Al este, el ca\xf1\xf3n se abre a los Shimmering Flats, una cegadora salina donde ingenieros goblins y gnomos hacen correr sus m\xe1quinas en la Mirage Raceway."]},"zone:alterac-mountains":{title:"Monta\xf1as de Alterac",summary:"El reino roto de Alterac y las ruinas protegidas de Dalaran, disputados por los ogros y el Sindicato.",body:["Las Monta\xf1as de Alterac fueron anta\xf1o el reino de Alterac, cuyo se\xf1or, Aiden Perenolde, traicion\xf3 a la Alianza en favor de la Horda durante la Segunda Guerra. El reino fue disuelto; hoy, los ogros Crushridge se instalan en las ruinas de la ciudad de Alterac, y el Sindicato de Aliden Perenolde, heredero de la casa ca\xedda en desgracia, gobierna Strahnbrad. Los p\xedcaros de Ravenholdt guardan sus propios secretos en las colinas.","Junto al Lago Lordamere yacen los restos de Dalaran, la ciudad de los magos que Archimonde destruy\xf3 en la Tercera Guerra. El Kirin Tor la ha estado reconstruyendo tras una barrera m\xe1gica. En Forever esa barrera ha ca\xeddo y la ciudad rebosa de caos arcano; tambi\xe9n es all\xed adonde llegan en aeronave desde Zephras Isle los Skyborne de la Alianza."]},"zone:arathi-highlands":{title:"Tierras Altas de Arathi",summary:"El antiguo coraz\xf3n de Arathor, donde Stromgarde yace en ruinas y tres bandos se disputan los restos.",body:["Las Tierras Altas de Arathi fueron el coraz\xf3n de Arathor, el primer imperio humano, fundado por el rey Thoradin con su capital en Strom. Su sucesora, Stromgarde, yace hoy en gran parte en ruinas en el suroeste, donde los defensores del pr\xedncipe Galen Aterratrols libran una guerra de guerrillas a tres bandas contra el Sindicato y los ogros Boulderfist. La Muralla de Thoradin a\xfan marca la antigua frontera al oeste.","La Alianza se re\xfane en el Refugio de la Zaga. La Horda ocupa Sentencia, un antiguo campo de internamiento llamado as\xed en honor al Jefe de Guerra Orgrim Martillo Maldito, que cay\xf3 liberando a su pueblo. Los trols Witherbark rondan las colinas, y el Puente Thandol une las tierras altas con Los Humedales."]},"zone:desolace":{title:"Desolace",summary:"Un yermo gris cubierto de ceniza, lleno de huesos de kodo y de tribus centauro en guerra.",body:["Desolace es un p\xe1ramo desolado de ceniza gris, \xe1rboles muertos y cr\xe1neos de kodos antiguos, que acuden al Cementerio de Kodos para morir. Las ruinas de ciudades Altonato, arrasadas por la Gran Escisi\xf3n, se desmoronan por sus colinas, y los demonios y s\xe1tiros a\xfan se re\xfanen donde perdura la vieja magia.","Es la patria de los centauros, nacidos en las cavernas de Maraudon de la uni\xf3n de Zaetar, hijo de Cenarius, y la princesa de la tierra Theradras. Sus cuatro tribus, los Kolkar, los Gelkis, los Magram y los Maraudine, se combaten entre s\xed con tanta sa\xf1a como a los forasteros. La Alianza ocupa la Punta de Nijel y la Horda la Aldea Cazasombras."]}}},988,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"zones2",{enumerable:!0,get:function(){return o}});const o={"zone:stranglethorn-vale":{title:"Vega de Tuercespina",summary:"Una selva sofocante de ciudades trols ca\xeddas, cazadores, piratas y el puerto goblin de Bah\xeda del Bot\xedn.",body:["La Vega de Tuercespina fue el coraz\xf3n de los trols Gurubashi, cuyo imperio domin\xf3 anta\xf1o la selva desde Zul'Gurub. Sus ciudades de piedra se desmoronan hoy bajo las enredaderas, todav\xeda rondadas por trols de la jungla, mientras los ogros, los naga y las temibles zarzas estranguladoras de la vega hacen peligroso cada sendero. Los cazadores acuden en masa a la Expedici\xf3n de Nesingwary, la Horda ocupa el Campamento Grom'gol y los rebeldes de la Alianza acampan en el norte.","En el extremo sur, los goblins de Bah\xeda del Bot\xedn dirigen un puerto sin ley junto a los piratas de los Blackwater Raiders, y luchadores de todas las razas se citan en la vieja Arena Gurubashi. En Forever, antiguas ruinas trols han surgido del mar al oeste de Grom'gol: la Drowned City, que ahora recorren trols y naga."]},"zone:badlands":{title:"Tierras Inh\xf3spitas",summary:"Un desierto agrietado de ca\xf1ones donde los enanos buscan secretos de los titanes y la Horda vigila desde Kargath.",body:["Las Tierras Inh\xf3spitas son un desierto agrietado y abrasado por el sol, lleno de pe\xf1ascos y ca\xf1ones sinuosos, en el sur de Khaz Modan. Los prospectores de Forjaz lo rastrean en busca de reliquias de los titanes, atra\xeddos por Uldaman, una enorme c\xe1mara enterrada que revel\xf3 las primeras pistas sobre el origen de los enanos como seres de piedra viva. Unos troggs liberados de un largo letargo masacraron a la primera expedici\xf3n y ahora defienden sus salas.","Los enanos Hierro Negro ocupan la Fortaleza de Angor, los ogros Dustbelcher acampan por todo el yermo y los drac\xf3nidos negros anidan en el Barranco Lethlor. La Horda vigila desde el puesto de Kargath, cerca del camino a La Garganta de Fuego."]},"zone:dustwallow-marsh":{title:"Marjal Revolcafango",summary:"Un pantano humeante que oculta Theramore, la guarida de Onyxia y la prisi\xf3n largo tiempo sellada de la isla de Alcaz.",body:["El Marjal Revolcafango es un pantano antiguo y siempre h\xfamedo en la costa oriental de Kalimdor, plagado de crocoliscos, raptores y m\xfarlocs. Frente a su costa se alza la Isla de Theramore, la ciudad fortaleza que Jaina Valiente fund\xf3 para los supervivientes que la siguieron hacia el oeste; la Horda responde desde el poblado de Brackenwall, en el borde del marjal. En el sur, los dragones negros infestan el Wyrmbog alrededor de la guarida de Onyxia.","Desde hace mucho circulan rumores sobre la isla de Alcaz, cuya prisi\xf3n habr\xeda retenido a prisioneros de alto rango, incluso al rey Varian Wrynn. En Forever sus puertas por fin se abren y revelan a la Hermandad Defias y a los naga en guerra en su interior."]},"zone:riverglades":{title:"Riverglades",summary:"Una regi\xf3n fluvial disputada en el sureste de Khaz Modan, nueva en Forever, donde los caballeros de Farholde a\xfan libran una guerra que Ventormenta dej\xf3 atr\xe1s.",body:["Las Riverglades se extienden al este de las Tierras Inh\xf3spitas y de Las Estepas Ardientes, y pertenecieron en otro tiempo al reino de Ventormenta. En la Primera Guerra, la Horda saque\xf3 el pueblo de Sunnyglade y esclaviz\xf3 a sus habitantes. Unas pocas familias huyeron para fundar Windstead, mientras que los caballeros que liberaron a los cautivos fundaron Meadowsbrook y despu\xe9s fortificaron una isla costera con el nombre de Farholde. Creyendo perdida la regi\xf3n, Ventormenta se ocup\xf3 de otros asuntos.","Hacia el final de la Segunda Guerra, ogros del Martillo Crepuscular y orcos Stormreaver que hu\xedan de la Tumba de Sargeras se refugiaron aqu\xed, y a\xf1os de incursiones terminaron con el asedio de Farholde. En el a\xf1o 25, la Brotherhood of the Horse del comandante caballero Demar Brant sigue luchando, el Martillo Crepuscular ocupa las ruinas de Sunnyglade y los ogros Bolder'ok se han unido a la Horda."],unknowns:["Las fuentes no nombran a qui\xe9n dirige las fuerzas de la Horda en Rog'mar y Bolder'ok.","Que Cho\u2019gall llegara a la regi\xf3n despu\xe9s de la Segunda Guerra no es m\xe1s que un rumor.","Qu\xe9 significan los c\xe1nticos que se oyen en la Krol\u2019dok Stronghold al caer la noche sigue sin aclararse."]},"zone:swamp-of-sorrows":{title:"Pantano de las Penas",summary:"Una ci\xe9naga salobre donde los dragones verdes custodian el templo hundido de Atal'Hakkar y la Horda ocupa Rocal.",body:["El Pantano de las Penas es una ci\xe9naga estancada de \xe1rboles llorones y aguas salobres en el sur de los Reinos del Este, cerca de donde se abri\xf3 por primera vez el Portal Oscuro. La Horda ha sabido aprovechar su distancia de Ventormenta: el pueblo orco de Rocal es aqu\xed su basti\xf3n. Crocoliscos, bestias del pantano y un grupo de draenei exiliados comparten las aguas turbias.","En el coraz\xf3n del pantano se encuentra el Templo de Atal'Hakkar, el santuario hundido donde los sacerdotes Atal'ai intentaron en su d\xeda invocar a su dios de la sangre, Hakkar. Ahora lo custodian los dragones verdes del Aspecto Ysera, que advierten de que un terror a\xfan se agita en su interior."]},"zone:feralas":{title:"Feralas",summary:"Un bosque exuberante alimentado por la lluvia, de \xe1rboles gigantes, ruinas tomadas por los ogros y la antigua ciudad Altonato de Eldre'Thalas.",body:["Feralas es un bosque exuberante y empapado por la lluvia, de \xe1rboles gigantes, en la costa suroeste de Kalimdor, que form\xf3 parte del antiguo reino de los elfos de la noche. Su mayor ruina es Eldre'Thalas, hoy llamada La Masacre, donde los Shen'dralar, Altonato que sobrevivieron a la Gran Escisi\xf3n, vivieron aislados durante diez mil a\xf1os. Los ogros Gordunni han invadido las viejas ruinas \xe9lficas y extendido su corrupci\xf3n por la tierra.","Las Centinelas del Basti\xf3n Plumaluna vigilan la costa desde la Isla de Sardor, mientras los tauren del Campamento Mojache persiguen a los renegados T\xf3tem Siniestro para la Horda. Los naga dominan las islas del oeste, han aparecido colmenas de sil\xedtidos y los dragones verdes custodian el Dream Bough, una puerta al Sue\xf1o Esmeralda."]},"zone:hinterlands":{title:"Tierras del Interior",summary:"Salvajes colinas del norte de jinetes de grifo y trols del bosque, hogar de los enanos Martillo Salvaje en el Pico Nidal.",body:["Las Tierras del Interior son unas tierras altas escarpadas y boscosas en el norte de Lordaeron. Tras la Guerra de los Tres Martillos, los enanos Martillo Salvaje abandonaron la maldita Grim Batol y se establecieron aqu\xed, en el Pico Nidal, donde doman los grifos salvajes de la regi\xf3n y siguen siendo firmes aliados de la Alianza. Unos pocos altos elfos a\xfan mantienen la Quel'Danil Lodge.","Las colinas pertenecen igualmente a los trols del bosque. La tribu Revantusk se ha puesto del lado de la Horda de Thrall, mientras los Vilebranch gobiernan la gran ciudad templo de Jintha'Alor y los Witherbark acechan alrededor de Shadra'Alor. En el norte, el \xe1rbol ancestral Seradane alberga un portal al Sue\xf1o Esmeralda, vigilado por dragones verdes."]},"zone:tanaris":{title:"Tanaris",summary:"Un mar de dunas gobernado desde Gadgetzan que oculta las Cavernas del Tiempo y la ciudad trol de Zul'Farrak.",body:["Tanaris es un desierto interminable de dunas y tormentas de arena en el sureste de Kalimdor. Los goblins del C\xe1rtel Bonvapor lo dirigen desde Gadgetzan y el Puerto Bonvapor y mantienen una fr\xe1gil neutralidad mientras los bandidos Wastewander, los piratas de los Mares del Sur y los ogros Dunemaul asaltan a los viajeros.","El desierto oculta poderes m\xe1s antiguos. En las Cavernas del Tiempo, el Vuelo Bronce de Nozdormu vela por el curso de la historia; muy al sur se encuentran las ruinas tit\xe1nicas de Uldum, y los trols de arena de Zul'Farrak defienden su ciudad amurallada en el noroeste. En Forever, un barco desde el Puerto Bonvapor une el desierto con Powderfuse Port, en las Riverglades."]},"zone:searing-gorge":{title:"La Garganta de Fuego",summary:"Un hoyo calcinado de minas Hierro Negro y trabajo esclavo, ennegrecido por la invocaci\xf3n de Ragnaros.",body:["La Garganta de Fuego es una tierra ennegrecida de ceniza y roca fundida en el sur de Khaz Modan. Debe sus cicatrices a la misma cat\xe1strofe que abras\xf3 Las Estepas Ardientes: la invocaci\xf3n de Ragnaros por parte del thane hechicero Thaurissan, que puso fin a la Guerra de los Tres Martillos. Hoy la dominan los enanos Hierro Negro, que obligan a los esclavos a extraer mineral en la gran grieta de El Caldero.","No todos los Hierro Negro sirven al Se\xf1or del Fuego. La Hermandad del Torio, maestros herreros que rompieron con su clan, comercia con los forasteros desde el Puesto del Torio. Al sur se alza la Monta\xf1a Roca Negra, con el imperio Hierro Negro en sus profundidades y la cumbre, m\xe1s arriba, en manos de orcos y dragones negros."]},"zone:azshara":{title:"Azshara",summary:"Una costa de oto\xf1o eterno sobre las ruinas sumergidas de la capital de la reina Azshara.",body:["Azshara es una costa destrozada de oto\xf1o eterno en el noreste de Kalimdor, con \xe1rboles que arden en rojo y oro. Aqu\xed se alzaba Zin-Azshari, la mayor ciudad de los antiguos elfos de la noche, hasta que la Gran Escisi\xf3n arroj\xf3 la mayor parte de ella al mar. Terrazas en ruinas siguen aferradas a los acantilados, rondadas por esp\xedritus Altonato sin descanso; los naga y los s\xe1tiros merodean por la orilla, y la Alianza en la Punta Talrendis y la Horda en Valormok mantienen peque\xf1os campamentos.","En Forever, una puerta de Azshara sellada desde hace mucho se abre a Blackmaw Hold, una gran ciudad f\xfarbolg cuyo clan lucha contra una corrupci\xf3n que se extiende por sus arboledas y t\xfaneles. Sus profundidades conectan con las Barrow Deeps y llevan a\xfan m\xe1s abajo."]},"zone:blasted-lands":{title:"Las Tierras Devastadas",summary:"Un desierto rojo y arruinado alrededor del silencioso Portal Oscuro, vigilado por los magos y paladines del Castillo de Nethergarde.",body:["Las Tierras Devastadas formaron parte en otro tiempo de La Ci\xe9naga Negra, hasta que la magia que abri\xf3 el Portal Oscuro las deform\xf3 hasta convertirlas en un desierto rojo de arcilla agrietada. El gran portal por el que la Horda invadi\xf3 por primera vez sigue en pie aqu\xed, con su marco de piedra oscuro y silencioso desde su destrucci\xf3n. El Castillo de Nethergarde, una fortaleza de Ventormenta con magos y paladines, lo vigila.","Poco m\xe1s vive en este yermo abrasado aparte de escorpiones, basiliscos, ogros Dreadmaul y unos pocos draenei exiliados. Tambi\xe9n permanecen los demonios: el se\xf1or maldito Kazzak re\xfane lo que queda de la Legi\xf3n Ardiente en la Tainted Scar."]},"zone:felwood":{title:"Frondavil",summary:"Un bosque antes hermoso envenenado por los demonios, donde los f\xfarbolgs Fauces de Madera y los druidas combaten la podredumbre.",body:["Frondavil fue anta\xf1o un para\xedso de arroyos y praderas cuidado por los elfos de la noche. En la Tercera Guerra, la Legi\xf3n Ardiente lo corrompi\xf3 con el poder del Cr\xe1neo de Gul'dan, y la tierra nunca se recuper\xf3: sus r\xedos corren verdes de veneno, sus ancestros y ant\xe1rboles se pudren donde est\xe1n, y los s\xe1tiros, los infernales y el Consejo de la Sombra de Jaedenar, adorador de demonios, rondan sus claros.","Los elfos de la noche de la Talonbranch Glade, la Horda en el Bloodvenom Post y los druidas del Santuario Esmeralda intentan hacer retroceder la corrupci\xf3n. En el norte, los Fauces de Madera, una de las \xfaltimas tribus f\xfarbolg sin corromper, custodian los t\xfaneles que llevan al Claro de la Luna y a Cuna del Invierno."]},"zone:un-goro-crater":{title:"Cr\xe1ter de Un'Goro",summary:"Un cr\xe1ter de selva primigenia lleno de dinosaurios, elementos vivientes y silenciosos pilones de los titanes.",body:["El Cr\xe1ter de Un'Goro es una selva primigenia y humeante hundida entre los desiertos del sur de Kalimdor, un mundo aparte donde cazan los demosaurios, los elementales surgen de las fuentes termales y el Fire Plume Ridge humea en su centro. Los exploradores se re\xfanen en el Refugio de Marshal para estudiar sus cristales rojos, azules, verdes y amarillos y los misteriosos pilones de las crestas del cr\xe1ter, que parecen obra de los titanes.","En el sur han aparecido sil\xedtidos, que se extienden desde el vecino Silithus. En Forever, una antigua instalaci\xf3n de los titanes en lo alto del cr\xe1ter, Shaper's Terrace, se abre a los aventureros que traen cristales de poder reunidos por todo Un'Goro."]},"zone:burning-steppes":{title:"Las Estepas Ardientes",summary:"Tierras altas asfixiadas por la ceniza bajo la Monta\xf1a Roca Negra, en manos de orcos Roca Negra, ogros Fire-Gut y dragones negros.",body:["Las Estepas Ardientes son unas tierras altas arruinadas de ceniza, lava y piedra humeante, abrasadas cuando la invocaci\xf3n de Ragnaros por parte de Thaurissan puso fin a la Guerra de los Tres Martillos; las ruinas de la antigua ciudad Hierro Negro de Thaurissan a\xfan siguen en pie. Las estepas son la \xfanica ruta terrestre entre Ventormenta y Khaz Modan, pero el reino las ha abandonado casi por completo.","Sobre ellas se cierne la Monta\xf1a Roca Negra. La Cumbre de Roca Negra, la gran fortaleza de la Horda en la Segunda Guerra, est\xe1 en manos de los orcos Roca Negra y los dragones negros bajo el mando de Nefarian, mientras que los enanos Hierro Negro gobiernan las profundidades. Los ogros Fire-Gut recorren las llanuras, y solo resisten el puesto de la Alianza de la Vigilia de Morgan y el campamento de la Horda de Flame Crest."]},"zone:western-plaguelands":{title:"Tierras de la Peste del Oeste",summary:"Las tierras de cultivo devastadas de Lordaeron, donde la Plaga ocupa Andorhal y la tumba de Uther es el \xfaltimo suelo sagrado.",body:["Las Tierras de la Peste del Oeste fueron en otro tiempo de las tierras de cultivo m\xe1s ricas de Lordaeron; hoy una niebla gris cubre campos enfermos y los no-muertos vagan por granjas abandonadas. El pueblo en ruinas de Andorhal, donde el culto de Kel'Thuzad reparti\xf3 su grano apestado, es aqu\xed el mayor basti\xf3n de la Plaga, y los calderos de peste envenenan los campos de alrededor. En una isla del Lago Darrowmere, Caer Darrow, la fortaleza de la familia Barov, oculta Scholomance, una escuela de nigromancia.","La Cruzada Escarlata combate desde Vega del Amparo, en el norte, la Alianza desde el Campamento del Orvallo y los Renegados ocupan El Baluarte, en la frontera con Tirisfal. La Tumba de Uther, lugar de descanso del Iluminado, es el \xfanico lugar consagrado donde reina la paz."]},"zone:eastern-plaguelands":{title:"Tierras de la Peste del Este",summary:"El rinc\xf3n m\xe1s devastado del ca\xeddo Lordaeron, gobernado por la Plaga desde la ciudad quemada de Stratholme.",body:["Las Tierras de la Peste del Este son el resto m\xe1s devastado del reino de Lordaeron: tierra parda y enferma, \xe1rboles hinchados hasta volverse hongos gigantes y un aire cargado de niebla anaranjada. En su centro se encuentra Stratholme, la ciudad cuyos habitantes pas\xf3 a cuchillo el pr\xedncipe Arthas en la Tercera Guerra, hoy dividida entre la Plaga y la Cruzada Escarlata.","El ej\xe9rcito principal de la Cruzada ocupa la Mano de Tyr y combate a los no-muertos con mucho celo pero poco \xe9xito, mientras el Alba Argenta acoge en la Capilla de la Esperanza de la Luz a cualquiera dispuesto a ayudar. Pueblos fantasma como Darrowshire y el Cruce de Corin recuerdan batallas perdidas, y los trols Amani atacan desde Zul'Mashar, en el norte, para recuperar sus tierras ancestrales."]},"zone:winterspring":{title:"Cuna del Invierno",summary:"Un valle nevado en las laderas de Hyjal que comparten comerciantes goblins, sables de hielo, dragones azules y demonios.",body:["Cuna del Invierno es un valle de nieves casi perpetuas en las laderas del monte Hyjal, donde los elfos de la noche empezaron a reconstruir tras la Gran Escisi\xf3n. La ciudad goblin de Vista Eterna comercia con todo el mundo, los elfos de la noche a\xfan mantienen la aldea de Starfall y los adiestradores de la Frostsaber Rock cr\xedan a los felinos blancos del valle. Los dragones azules tienen su guarida en las cuevas de Mazthoril.","El sur del valle ha ca\xeddo ante los demonios en la Darkwhisper Gorge, y los f\xfarbolgs Winterfall se han vuelto salvajes. En Forever, una de las entradas a la banda de las Barrow Deeps se alcanza a trav\xe9s de Cuna del Invierno."]},"zone:deadwind-pass":{title:"Paso de la Muerte",summary:"Un paso muerto y azotado por el viento, dominado por Karazhan, la torre del \xfaltimo Guardi\xe1n, Medivh.",body:["El Paso de la Muerte es un ca\xf1\xf3n escarpado de \xe1rboles petrificados y sin hojas entre el Bosque del Ocaso y el Pantano de las Penas, por el que nunca deja de soplar un viento que gime. En su centro se alza Karazhan, la torre de marfil de Medivh, el \xfaltimo Guardi\xe1n de Tirisfal, cuya posesi\xf3n por Sargeras abri\xf3 el camino a la Horda. Aunque Medivh muri\xf3 hace mucho, su torre a\xfan filtra magia oscura en la tierra.","Ogros del Paso de la Muerte, demonios y esp\xedritus sin descanso recorren el paso, las tumbas de Morgan's Plot no encuentran reposo y los viajeros susurran que un nuevo poder ha reclamado la torre. La mayor\xeda lo cruza a toda prisa."]},"zone:moonglade":{title:"Claro de la Luna",summary:"Un apacible santuario druida en el norte de Kalimdor, hogar del C\xedrculo Cenarion.",body:["El Claro de la Luna es un valle oculto en el norte de Kalimdor, sagrado para los druidas desde hace miles de a\xf1os. Malfurion Tempestira reuni\xf3 aqu\xed a los druidas para fundar el C\xedrculo Cenarion, y el reflejo del valle en el Sue\xf1o Esmeralda es el lugar m\xe1s sagrado de ese reino. En la ciudad de Amparo de la Noche, el guardi\xe1n Remulos, hijo de Cenarius, vela por la orden.","Desde la Tercera Guerra, el C\xedrculo ha abierto el Claro de la Luna a todos los que siguen la senda dru\xeddica, y tauren y elfos de la noche comparten ahora sus orillas en paz. Los guardianes del Claro de la Luna no toleran la violencia en el santuario, y cada a\xf1o Amparo de la Noche celebra el Festival Lunar."]},"zone:silithus":{title:"Silithus",summary:"Un desierto abrasado por el sol, lleno de colmenas de insectos, en el suroeste de Kalimdor, donde el C\xedrculo Cenarion vigila las puertas selladas de Ahn'Qiraj.",body:["Silithus es un desierto abrasador en el extremo suroeste de Kalimdor, interrumpido solo por las alt\xedsimas colmenas de los sil\xedtidos. Desde la Guerra de las Arenas Movedizas, los qiraji insectoides est\xe1n encerrados tras el Muro del Escarabajo que alzaron los vuelos de dragones, pero sus enjambres de sil\xedtidos no han dejado de multiplicarse.","El C\xedrculo Cenarion vigila la amenaza desde el Fuerte Cenarion, mientras los cultistas del Martillo Crepuscular se re\xfanen en campamentos por las dunas con fines propios. Tras el muro, aguarda el templo fortaleza de Ahn'Qiraj."]}}},989,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"instances1",{enumerable:!0,get:function(){return o}});const o={"instance:hall-of-thanes":{title:"Hall of Thanes",summary:"La cripta real de Forjaz, profanada por intrusos que los enanos sospechan que son Hierro Negro.",body:["Bajo Forjaz se encuentra el Hall of Thanes, donde los enanos dan sepultura a sus monarcas y cuidan las tumbas con esmero. Su entrada aguarda en el umbral del High Seat, en el coraz\xf3n de la ciudad: un paseo para la Alianza y una osada intrusi\xf3n para cualquier grupo de la Horda. Ahora unos intrusos se han abierto paso a la fuerza hasta las tumbas sagradas. Los enanos sospechan del clan Hierro Negro, y la vieja piedra est\xe1 llena de susurros fantasmales.","La mayor\xeda de sus misiones son para la Alianza y comienzan en Kharanos o en los alrededores de Forjaz, aunque una de las misiones del interior la ofrece un fantasma neutral. Cuatro enemigos cierran el paso: Faldrim Anvilmar, Magmatus, Plunder y Durgen Dirgehammer."],unknowns:["Qui\xe9nes son en realidad los intrusos; el texto oficial solo dice que los enanos sospechan del clan Hierro Negro.","Qu\xe9 se ha agitado dentro de las salas y la historia que hay detr\xe1s de cada uno de los cuatro enemigos."]},"instance:ragefire-chasm":{title:"Sima \xcdgnea",summary:"Cuevas volc\xe1nicas bajo Orgrimmar donde los trogg y un culto al servicio de los demonios amenazan la nueva capital de la Horda.",body:["Bajo Orgrimmar se extiende un laberinto de cavernas iluminadas por la lava, y la Horda ha descubierto que su nueva capital no descansa tranquila. Unos trogg conocidos como los \xcdgneos han subido desde los t\xfaneles profundos, y cuando la anciana tauren Magatha T\xf3tem Siniestro intent\xf3 hacer las paces con ellos, solo encontr\xf3 violencia.","Peor a\xfan, una secta llamada el Filo Abrasador, leal al demon\xedaco Consejo de la Sombra, se ha ocultado en la sima para conspirar contra todo lo que ha construido el pueblo de Thrall. La dirige Taragaman el Hambriento, un guardia vil, con el brujo Jergosh el Invocador y el s\xe1tiro Bazzalan a su lado. Para muchos j\xf3venes h\xe9roes de la Horda, estas cuevas son su primera mazmorra."]},"instance:ruins-of-lordaeron":{title:"Ruins of Lordaeron",summary:"La capital en ruinas sobre Entra\xf1as, donde los Renegados recuperan su pasado mientras un nigromante re\xfane poder.",body:["Los Renegados intentan recuperar la capital en ruinas que se alza sobre su ciudad de Entra\xf1as. Sus escombros a\xfan guardan reliquias familiares y recuerdos queridos, pero la Plaga ronda las calles destrozadas y se dice que un nigromante re\xfane poder dentro de sus murallas. Se llama a los aventureros para ayudar a que la ciudad vuelva a ser segura.","Los grupos de la Horda llegan f\xe1cilmente a la entrada desde Entra\xf1as, mientras que los de la Alianza deben adentrarse en tierras de la Horda. Ambas facciones encuentran misiones: las de la Horda empiezan en Entra\xf1as, el Bosque de Arg\xe9nteos y Tirisfal, y las de la Alianza dentro de las propias ruinas. El camino pasa por Witherfang, The Baron, Viktor the Vile, The Abandoned y Bjork hasta el \xfaltimo enemigo, Rath'mael."],unknowns:["Qui\xe9n es el nigromante y para qu\xe9 es el poder que re\xfane.","Cu\xe1nto de la antigua capital pretenden reconstruir los Renegados."]},"instance:deadmines":{title:"Las Minas de la Muerte",summary:"La mina de oro abandonada de los P\xe1ramos de Poniente, donde la Hermandad Defias de Edwin VanCleef construye en secreto un buque de guerra.",body:["Antes de la Primera Guerra, estos t\xfaneles eran las minas de oro m\xe1s ricas de las tierras humanas; el saqueo de Ventormenta por los orcos las dej\xf3 vac\xedas. Ahora la Hermandad Defias las ha convertido en su fortaleza oculta. Su l\xedder, Edwin VanCleef, era un maestro cantero que ayud\xf3 a reconstruir Ventormenta tras la guerra, hasta que los nobles de la ciudad se negaron a pagar a su gremio. Traicionados, sus trabajadores se volvieron forajidos y se extendieron por los P\xe1ramos de Poniente.","El camino de entrada empieza en la aldea en ruinas de Arroyo de la Luna. Muy abajo, goblins como Sneed y Gilnid ayudan a los Defias a terminar un gran barco en una cala oculta, custodiada por Mr. Smite y el capit\xe1n Verdepellejo."]},"instance:wailing-caverns":{title:"Cuevas de los Lamentos",summary:"Cuevas bajo Los Bald\xedos donde el sue\xf1o de renovaci\xf3n del druida Naralex se convirti\xf3 en pesadilla.",body:["Las Cuevas de los Lamentos deben su nombre al gemido del viento y el vapor que se cuelan por las grietas de la roca. El druida elfo de la noche Naralex las descubri\xf3 y esperaba unir sus manantiales subterr\xe1neos al Sue\xf1o Esmeralda, para que la vida verde volviera a extenderse por los secos Bald\xedos. Pero mientras meditaba, fue la Pesadilla Esmeralda la que lo domin\xf3.","Atrapado en el sue\xf1o, Naralex vierte ahora esa corrupci\xf3n en las cuevas. Sus criaturas se han deformado hasta convertirse en bestias descarriadas, y la mayor\xeda de sus disc\xedpulos enloquecieron y se convirtieron en los Druidas del Colmillo, entre ellos lady Anacondra y los se\xf1ores Cobrahn, Pythas y Serpentis. Despertar a Naralex supone enfrentarse a Mutanus el Devorador."]},"instance:shadowfang-keep":{title:"Castillo de Colmillo Oscuro",summary:"Un castillo encantado del Bosque de Arg\xe9nteos donde el archimago loco Arugal da cobijo a los huargen que \xe9l mismo liber\xf3.",body:["El Kirin Tor estaba perdiendo la lucha de la Tercera Guerra contra la Plaga, y cada mago que ca\xeda pronto volv\xeda a levantarse en el bando enemigo. El archimago Arugal desoy\xf3 las advertencias de sus colegas y busc\xf3 ayuda m\xe1s all\xe1 del mundo, invocando a los salvajes huargen. Estos despedazaron a los no-muertos, luego a las propias filas de Dalaran, e invadieron el castillo del bar\xf3n Silverlaine en la colina sobre Pyrewood.","La culpa quebr\xf3 la mente de Arugal. Ahora llama a los hombres lobo sus hijos y se oculta con ellos en el castillo, rebautizado como Colmillo Oscuro y custodiado por el gran lobo Fenrus. El fantasma del bar\xf3n nunca se ha marchado, y los Renegados del Bosque de Arg\xe9nteos quieren ver muerto al archimago."]},"instance:excavation-site-wetlands":{title:"Excavation Site: Wetlands",summary:"Una excavaci\xf3n sobre el Whelgar's Excavation Site ha abierto un lugar que el tiempo no ha tocado, custodiado por ensamblajes de los titanes extraviados.",body:["Algo ha despertado en las colinas de Los Humedales, cerca de Thelgen Rock y Dun Algaz. La niebla desciende por las laderas sobre el Whelgar's Excavation Site y una luz parpadea en el horizonte. M\xe1s all\xe1 de la excavaci\xf3n, la tierra parece intacta al paso de las eras; m\xe1quinas de los titanes extraviadas y una fauna feroz custodian secretos que la Liga de Expedicionarios est\xe1 deseando desvelar.","Las misiones de la Alianza empiezan en el Puerto de Menethil, Greenwarden's Grove y Villa del Lago, y las de la Horda en Orgrimmar y Sentencia. Saltspine y Shadetooth cierran el paso al Relic Guardian, cuya derrota entrega una reliquia de los titanes que inicia una misi\xf3n para ambas facciones."],unknowns:["Qu\xe9 ha despertado m\xe1s all\xe1 de la excavaci\xf3n y qu\xe9 causa la niebla y las luces.","Qui\xe9n construy\xf3 el lugar y para qu\xe9 sirve la reliquia de los titanes."]},"instance:stormwind-stockade":{title:"Las Mazmorras",summary:"La prisi\xf3n de Ventormenta, tomada por sus propios reclusos en un mot\xedn dirigido por los Defias.",body:["Las Mazmorras se encuentran en el coraz\xf3n de la Ciudad de Ventormenta y retienen a ladrones, asesinos y presos pol\xedticos. Hace poco, los reclusos se sublevaron, revelaron su lealtad a la Hermandad Defias y expulsaron a los guardias; ahora son ellos quienes controlan los bloques de celdas.","Su cabecilla es Bazil Thredd, un agente de los Defias. Entre los presos est\xe1n el orco Roca Negra Targorr el Terrible, el enano Hierro Negro Kam Furiahonda y el profanador de tumbas Dextren Ward. Varios fueron condenados a muerte, pero el papeleo de la nobleza no dejaba de retrasar las sentencias, as\xed que Villa del Lago, Villa Oscura e incluso Forjaz env\xedan discretamente aventureros para zanjar el asunto."]},"instance:city-of-dalaran":{title:"City of Dalaran",summary:"La ciudad del Kirin Tor en las Monta\xf1as de Alterac, donde ha ca\xeddo la barrera que ocultaba su restauraci\xf3n y la magia se ha desbocado.",body:["Durante un tiempo, una barrera m\xe1gica ocult\xf3 los trabajos de restauraci\xf3n de Dalaran. Ahora ese escudo ha ca\xeddo y la ciudad ha quedado al descubierto, sumida en el caos arcano: los hechizos fallan, los ensamblajes andan sueltos y la magia en bruto se derrama por las calles. El Kirin Tor necesita ayuda, pero solo de gente en quien conf\xede.","Los h\xe9roes de la Alianza se ganan esa confianza empezando con Emissary Jacques en Costasur; los de la Horda empiezan con Magus Wordeen Voidglare en Molino Tarren. Ambos caminos llevan hasta una imagen de la archimaga Modera en la orilla sur del Lago Lordamere, que entrega la Dalaran Sewer Key. Desde las cloacas, los grupos eligen su propia ruta por la ciudad hacia el origen del problema; el \xfaltimo enemigo es el Shade of the Archmage."],unknowns:["Qu\xe9 provoc\xf3 el desorden y de qui\xe9n es la sombra que es el \xfaltimo enemigo.","Cu\xe1nto ha avanzado la restauraci\xf3n de Dalaran."]},"instance:blackfathom-deeps":{title:"Cavernas de Brazanegra",summary:"Un templo sumergido de Elune en la costa de Vallefresno, convertido hoy en un santuario donde unos cultistas cuidan de una bestia de los Dioses Antiguos.",body:["Un pozo rodeado de escaleras en la Playa de Zoram, en Vallefresno, desciende hasta unas salas inundadas que anta\xf1o formaban un templo de Elune, la diosa lunar de los elfos de la noche. La Gran Escisi\xf3n rompi\xf3 el santuario y lo arrastr\xf3 bajo el mar, donde durmi\xf3 durante eras hasta que nagas y s\xe1tiros, \xe1vidos del poder que a\xfan perdura all\xed, llegaron a explorarlo.","Hoy el culto del Martillo Crepuscular adora en los estanques m\xe1s profundos bajo el mando del Se\xf1or Crepuscular Kelris y cuida de Aku'mai, una bestia monstruosa apreciada por los Dioses Antiguos. Chamanes del Anillo de la Tierra han venido a detenerlos, sabiendo que cualquier llamada a los Dioses Antiguos pone en peligro el mundo entero."]},"instance:razorfen-kraul":{title:"Horado Rajacieno",summary:"La madriguera ancestral de los jabaespines, nacida de las espinas que brotaron de la sangre de un semidi\xf3s ca\xeddo.",body:["Los jabaespines adoran a Agamaggan, el gran semidi\xf3s jabal\xed que muri\xf3 en la Guerra de los Ancestros. All\xed donde cay\xf3 su sangre, enormes enredaderas espinosas brotaron de la tierra, y la mara\xf1a m\xe1s grande, en el extremo sur de Los Bald\xedos, es Rajacieno, el lugar que los jabaespines honran como su tumba.","El Horado Rajacieno es su hogar ancestral, un laberinto de guaridas y t\xfaneles techados de zarzas que gobierna Charlga Filonavaja, la Vieja. Sacerdotes de la tribu Death's Head ya recorren sus pasadizos, y los exploradores informan de que en la regi\xf3n se re\xfanen no-muertos, lo que hace temer que la Plaga haya puesto sus miras en Kalimdor."]},"instance:gnomeregan":{title:"Gnomeregan",summary:"La capital perdida de los gnomos en Dun Morogh, envenenada por una purga radiactiva tras una invasi\xf3n trogg y el consejo de un traidor.",body:["Construida en lo m\xe1s profundo de las monta\xf1as de Dun Morogh, Gnomeregan era la mayor maravilla de ingenier\xeda de los gnomos. Entonces los trogg surgieron de las profundidades y la invadieron. El Manitas Mayor Mekkatorque sigui\xf3 el consejo de su consejero, Sicco Thermaplugg, e inund\xf3 la ciudad de radiaci\xf3n para matar a los invasores, pero la purga mat\xf3 tambi\xe9n a la mayor\xeda de los gnomos. Los supervivientes huyeron a Forjaz.","Fue una traici\xf3n. Thermaplugg se qued\xf3 atr\xe1s, se coron\xf3 se\xf1or de las ruinas y ahora dirige a gnomos leprosos, trogg y m\xe1quinas enloquecidas como el Electrocutor 6000 y el Golpeamasas 9-60. Los exiliados han jurado recuperar su hogar."]},"instance:scarlet-monastery-graveyard":{title:"Monasterio Escarlata: Cementerio",summary:"Las criptas del monasterio de la Cruzada Escarlata, donde trabaja su interrogador y los muertos se niegan a descansar.",body:["El monasterio del norte de los Claros de Tirisfal se construy\xf3 como casa de estudio para los sacerdotes de Lordaeron. Despu\xe9s de que la Plaga arrasara el reino en la Tercera Guerra, los fan\xe1ticos de la Cruzada Escarlata se apoderaron de \xe9l y lo convirtieron en su basti\xf3n. Sospechan que todo el que no es humano porta la peste y reciben a los extra\xf1os con espadas en lugar de preguntas.","El Cementerio es la primera ala que visitan la mayor\xeda de los grupos. Sus celdas pertenecen al Interrogador Vishas, el Mago de sangre Thalnos acecha entre las tumbas y muertos inquietos como Azshir el Insomne, Espinahierro y el Campe\xf3n ca\xeddo rondan las criptas."]},"instance:scarlet-monastery-library":{title:"Monasterio Escarlata: Biblioteca",summary:"El archivo de la Cruzada Escarlata, donde un maestro de canes y un arcanista custodian los libros de la orden.",body:["Anta\xf1o los sacerdotes de Lordaeron acud\xedan a estudiar a este monasterio de Tirisfal. La Cruzada Escarlata, que se apoder\xf3 de \xe9l tras la Tercera Guerra, conserv\xf3 los libros pero perdi\xf3 la bondad: sus fan\xe1ticos creen que cualquiera que no sea humano podr\xeda estar propagando la peste, y custodian su archivo con tanta fiereza como sus murallas.","El Maestro de canes Loksey y sus perros dan caza a los intrusos en las salas exteriores, y el Arcanista Doan vigila las estanter\xedas interiores. Muchos vienen por los propios libros: los eruditos de Forjaz quieren un volumen sobre la mitolog\xeda de los titanes, mientras que los Renegados buscan la cr\xf3nica de los ca\xeddos que lleva la propia Cruzada."]},"instance:drowned-city":{title:"Drowned City",summary:"Antiguas ruinas trol que han emergido del mar frente a la Vega de Tuercespina, recorridas ahora por trols y nagas.",body:["Frente a la Vega de Tuercespina, al oeste de Grom'gol, ha vuelto a emerger una ciudad trol que el mar se hab\xeda tragado. Calles que nadie hab\xeda pisado en eras quedan ahora al aire libre, trols y nagas ya se han instalado en ellas, y un barco pirata cercano parece haber tenido un final muy malo.","Para entrar, los grupos bucean y buscan el camino por debajo de la l\xednea del agua. Una vez dentro, combaten a cielo abierto mientras el tiempo empeora: la niebla se convierte en lluvia y la lluvia en una aut\xe9ntica tormenta para la batalla final."],unknowns:["Por qu\xe9 la ciudad ha emergido ahora y qu\xe9 pueblo trol la construy\xf3.","Qui\xe9n dirige a los trols y nagas del interior; los datos de esta gu\xeda a\xfan no recogen jefes.","Qu\xe9 le ocurri\xf3 al barco pirata."]},"instance:scarlet-monastery-armory":{title:"Monasterio Escarlata: Armer\xeda",summary:"El campo de entrenamiento y arsenal de la Cruzada Escarlata, gobernado por su campe\xf3n Herod.",body:["Tras los muros del monasterio de los Claros de Tirisfal, la Cruzada Escarlata adiestra a sus soldados. La orden naci\xf3 de la ruina de Lordaeron en la Tercera Guerra y cree que cualquiera que no sea humano puede portar la peste, as\xed que a sus reclutas se les ense\xf1a a golpear primero.","La Armer\xeda alberga los patios de entrenamiento, los barracones y los dep\xf3sitos de armas, y su se\xf1or es Herod, el campe\xf3n escarlata, un bruto descomunal que blande un hacha enorme y gira como un torbellino entre sus atacantes. Vencerlo demuestra que un grupo est\xe1 preparado para la catedral que hay en el coraz\xf3n del monasterio."]},"instance:razorfen-downs":{title:"Zah\xfarda Rajacieno",summary:"Los antiguos cementerios de los jabaespines, tomados por la Plaga a las \xf3rdenes del ex\xe1nime Amnennar el G\xe9lido.",body:["La Zah\xfarda Rajacieno crece de las mismas espinas gigantes que el Horado y es donde los jabaespines entierran a sus muertos. Sus sumos sacerdotes, los Death's Head, manten\xedan anta\xf1o la santidad de estas tierras. Todo cambi\xf3 cuando la Plaga lleg\xf3 a Kalimdor: el ex\xe1nime Amnennar el G\xe9lido tom\xf3 a su servicio a los sacerdotes de la tribu y llen\xf3 los zarzales de muertos alzados.","Los jabaespines libres luchan ahora por recuperar su ciudad funeraria antes de que el poder del ex\xe1nime se extienda por el resto de Los Bald\xedos. Un grupo debe abrirse paso m\xe1s all\xe1 de Tuten'kash, Mordresh Ojo de Fuego, Glot\xf3n y Fauceplaga el Podrido para llegar hasta el propio Amnennar."]},"instance:scarlet-monastery-cathedral":{title:"Monasterio Escarlata: Catedral",summary:"El coraz\xf3n del Monasterio Escarlata, donde el comandante Mograine dirige a los fieles y la Alta Inquisidora Melenablanca alza a los ca\xeddos.",body:["La catedral es el coraz\xf3n del monasterio de la Cruzada Escarlata en los Claros de Tirisfal y la sede de sus l\xedderes all\xed. El Comandante Escarlata Mograine dirige la fan\xe1tica guarnici\xf3n, pero la verdadera autoridad pertenece a la Alta Inquisidora Melenablanca, una sacerdotisa capaz de devolver a su campe\xf3n ca\xeddo para que vuelva a luchar.","La Cruzada naci\xf3 de la ca\xedda de Lordaeron y a\xfan ve la peste en cada forastero. Aqu\xed es donde su convicci\xf3n arde con m\xe1s fuerza: el comandante lucha hasta el final y, cuando cae, Melenablanca sale del presbiterio para seguir luchando y alzarlo de nuevo."]}}},990,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"instances2",{enumerable:!0,get:function(){return o}});const o={"instance:kroldok-stronghold":{title:"Krol'dok Stronghold",summary:"Una fortaleza ogra de los Riverglades cuyos asaltantes secuestran viajeros y de la que se elevan c\xe1nticos al caer la noche.",body:["Krol'dok es la fortaleza ogra de los Riverglades, y su historia se remonta a los a\xf1os posteriores a la Segunda Guerra. Cuando las fuerzas de la antigua Horda en la regi\xf3n asediaron Farholde Keep, Fern Crimsonleaf se col\xf3 en su campamento y mat\xf3 a sus l\xedderes. Sin mando, el ej\xe9rcito, m\xe1s numeroso, perdi\xf3 una costosa batalla contra la Brotherhood of the Horse y huy\xf3 de vuelta a Krol'dok.","Ahora sus batidores ogros atacan por todos los Riverglades, secuestran viajeros y saquean asentamientos. Su rastro termina en una extensa fortaleza de talleres, campamentos y pasadizos muy vigilados. Los grupos entran para acabar con las incursiones y averiguar el significado de los extra\xf1os c\xe1nticos que se elevan de la fortaleza al caer la noche."],unknowns:["Qui\xe9n est\xe1 ahora al mando de la fortaleza; los datos de esta gu\xeda a\xfan no recogen jefes.","Qu\xe9 son los c\xe1nticos y qui\xe9n los dirige.","Qu\xe9 relaci\xf3n tienen estos ogros con el Martillo Crepuscular y con los ogros Bolder'ok de otras partes de los Riverglades."]},"instance:uldaman":{title:"Uldaman",summary:"Una c\xe1mara de los titanes en las Tierras Inh\xf3spitas donde excavadores enanos despertaron a los trogg y hallaron pistas sobre sus propios or\xedgenes.",body:["Uldaman es una c\xe1mara que los guardianes de los titanes sellaron en lo m\xe1s profundo de las monta\xf1as de Khaz Modan, en lo que hoy son las Tierras Inh\xf3spitas. Deb\xeda contener a los trogg, una creaci\xf3n temprana que los titanes consideraron un fracaso. Antes de la Tercera Guerra, excavadores de Forjaz entraron en ella, y los trogg que despertaron masacraron a la mayor parte de la expedici\xf3n.","Ahora la Liga de Expedicionarios, los asaltantes Hierro Negro y las tribus trogg se disputan sus salas. En lo m\xe1s profundo est\xe1n los Discos de Norgannon, registros de los titanes que revelan que los enanos descienden de los terr\xe1neos de piel de piedra, custodiados por Archaedas, forjado por los titanes, que a\xfan se alza contra cualquiera que perturbe su c\xe1mara."]},"instance:zulfarrak":{title:"Zul'Farrak",summary:"La ciudad abrasada por el sol de los trols Furiarena en Tanaris, donde un dios hidra duerme en un estanque sagrado.",body:["Tanaris fue anta\xf1o una jungla que formaba parte de las tierras de los trols Gurubashi, y Zul'Farrak era una de sus ciudades. Cuando la Gran Escisi\xf3n convirti\xf3 la regi\xf3n en un desierto, los trols Farraki que se quedaron all\xed se adaptaron y se convirtieron en trols de arena. Hoy la ciudad pertenece a la tribu Furiarena, temida por su crueldad y su magia oscura.","Los aventureros acuden por muchas razones. Los rumores sit\xfaan entre sus muros las dos mitades de la espada trol rota Sul'thraze el Azotador, una banda de mercenarios que hu\xeda de Gadgetzan entr\xf3 all\xed por error y fue capturada, y en un estanque sagrado en el coraz\xf3n de la ciudad duerme Gahz'rilla, una hidra que los Furiarena veneran como semidi\xf3s y solo despiertan cuando tienen sacrificios que ofrecer."]},"instance:alcaz-prison":{title:"Alcaz Prison",summary:"Una prisi\xf3n largo tiempo rodeada de rumores en la isla de Alcaz, en el Marjal Revolcafango, por fin abierta, donde Defias y nagas est\xe1n en guerra.",body:["En el Marjal Revolcafango se habla desde hace mucho de la isla de Alcaz y de los prisioneros de alto rango que supuestamente se encuentran all\xed; algunos rumores llegan a mencionar al rey Varian Wrynn de Ventormenta. Nadie pod\xeda llegar a la prisi\xf3n para averiguar la verdad. Ahora sus puertas est\xe1n abiertas.","Dentro, la Hermandad Defias y los nagas luchan entre s\xed. Los grupos aprovechan el caos para registrar las celdas, enfrentarse a quienes las controlan y reunir nuevas pistas sobre un misterio que los reinos ya conocen bien."],unknowns:["Si el rey Varian Wrynn est\xe1 o estuvo preso aqu\xed; el texto oficial solo recoge rumores.","Qui\xe9n dirige la prisi\xf3n y por qu\xe9 luchan los Defias y los nagas.","Qu\xe9 jefes aguardan dentro; los datos de esta gu\xeda a\xfan no recogen ninguno."]},"instance:maraudon":{title:"Maraudon",summary:"Las cuevas sagradas de los centauros en Desolace, envenenadas por el dolor de la princesa de la tierra Theradras.",body:["La leyenda cuenta una historia sombr\xeda sobre el nacimiento de los centauros. Su padre era Zaetar, un hijo del semidi\xf3s Cenarius; su madre, la princesa Theradras, hija del se\xf1or elemental de la tierra. Los primeros centauros se volvieron contra Zaetar y lo mataron, y se dice que Theradras, afligida, at\xf3 su esp\xedritu dentro de Maraudon, un acto cuya corrupci\xf3n a\xfan envenena las cuevas.","Los clanes centauros consideran Maraudon un cementerio sagrado, pero fantasmas de centauros inquietos, elementales retorcidos y criaturas vegetales venenosas llenan ahora la Wicked Grotto, la Foulspore Cavern y las Earth Song Falls. Celebras, sobrino de Zaetar, lleg\xf3 para liberar el esp\xedritu de su t\xedo y sucumbi\xf3 \xe9l mismo a la corrupci\xf3n. En lo m\xe1s hondo aguarda Theradras."]},"instance:temple-of-atalhakkar":{title:"Templo de Atal'Hakkar",summary:"El Templo Sumergido del Pantano de las Penas, donde los sacerdotes Atal'ai a\xfan intentan invocar a su dios de la sangre, Hakkar.",body:["Los Atal'ai eran sacerdotes trol que quer\xedan traer al mundo a Hakkar el Desollador de Almas, el dios de la sangre, y la lucha por detenerlos desgarr\xf3 el Imperio Gurubashi hace m\xe1s de mil a\xf1os. Derrotados y expulsados, construyeron un templo en el Pantano de las Penas para preparar su regreso, hasta que el Aspecto Ysera descubri\xf3 el plan y lo hundi\xf3 en el cieno.","Desde entonces, los dragones verdes vigilan las ruinas sumergidas, pero los Atal'ai resistieron y a\xfan rezan a Hakkar bajo el mando de Jammal'an el Profeta. M\xe1s abajo perdura la Sombra de Eranikus, consorte de Ysera, con la mente oscurecida por la Pesadilla Esmeralda."]},"instance:blackrock-depths":{title:"Profundidades de Roca Negra",summary:"La Ciudad Forjatiniebla, capital de los enanos Hierro Negro en las entra\xf1as de la Monta\xf1a Roca Negra, gobernada por el emperador Dagran Thaurissan a la sombra de Ragnaros.",body:["Hace m\xe1s de dos siglos, el se\xf1or hechicero Hierro Negro Thaurissan intent\xf3 ganar una guerra perdida con una invocaci\xf3n desesperada y, en su lugar, trajo a Ragnaros, el Se\xf1or del Fuego. La explosi\xf3n levant\xf3 la Monta\xf1a Roca Negra y at\xf3 a su clan a la voluntad del Se\xf1or del Fuego. Sus descendientes a\xfan trabajan para Ragnaros en los t\xfaneles ardientes bajo la monta\xf1a.","Las Profundidades de Roca Negra son su reino: una prisi\xf3n, la arena llamada C\xedrculo de la Ley, la taberna Grim Guzzler, la Forja Negra y la propia Ciudad Forjatiniebla. All\xed se sienta en su trono el emperador Dagran Thaurissan junto a la princesa Moira Barbabronce, cuyo padre, el rey Magni de Forjaz, cree que la retienen all\xed con un hechizo."]},"instance:warpwood-quarter":{title:"Warpwood Quarter",summary:"El distrito oriental de la arruinada Eldre'Thalas, invadido por plantas corrompidas bajo el s\xe1tiro Alzzin the Wildshaper.",body:["La Masacre, en Feralas, fue anta\xf1o Eldre'Thalas, una ciudad donde los arcanistas m\xe1s reservados de la reina Azshara guardaban su preciado saber. La Gran Escisi\xf3n la dej\xf3 en ruinas, y con el paso de las eras ogros, s\xe1tiros y cosas a\xfan m\xe1s extra\xf1as se instalaron en sus distritos.","El Warpwood Quarter, al este, ha ca\xeddo en manos de Alzzin the Wildshaper, un s\xe1tiro que corrompi\xf3 el Fruto de la Fertilidad, que ahora solo da vides viles. Ancestros retorcidos, azotadores, demonios y s\xe1tiros le obedecen, y todo el distrito se ha vuelto salvaje. Hasta el travieso diablillo Pusillin arrastra a los intrusos a una alegre persecuci\xf3n por sus salas."]},"instance:blackmaw-hold":{title:"Blackmaw Hold",summary:"Una gran ciudad f\xfarbolg tras una puerta sellada durante mucho tiempo en Azshara, donde el clan Blackmaw combate una corrupci\xf3n que se extiende.",body:["Tras una puerta de Azshara que permaneci\xf3 cerrada durante much\xedsimo tiempo se encuentra una gran ciudad de los f\xfarbolgs. El clan Blackmaw que vive all\xed combate una corrupci\xf3n que se filtra por sus arboledas y a lo largo de los sinuosos t\xfaneles bajo las monta\xf1as.","El basti\xf3n es una larga aventura para grupos de nivel m\xe1ximo, con varias rutas y muchos jefes. Se dice que en sus zonas m\xe1s profundas se oculta un camino que lleva todav\xeda m\xe1s abajo de Azeroth, y el resumen de bandas de Blizzard menciona Blackmaw Hold como una de las entradas a los Barrow Deeps."],unknowns:["Qu\xe9 es la corrupci\xf3n y de d\xf3nde viene.","Qui\xe9n sell\xf3 la puerta y por qu\xe9.","Qu\xe9 jefes aguardan dentro; los datos de esta gu\xeda a\xfan no recogen ninguno."]},"instance:lower-blackrock-spire":{title:"Cumbre de Roca Negra Inferior",summary:"Las salas inferiores de la cumbre que corona la Monta\xf1a Roca Negra, cuarteles de la Horda Oscura de Rend Pu\xf1o Negro.",body:["Durante siglos, la cumbre que corona la Monta\xf1a Roca Negra fue un basti\xf3n Hierro Negro. Eso termin\xf3 cuando Nefarian, hijo de Alamuerte, tom\xf3 sus niveles superiores con sus drac\xf3nidos y se volvi\xf3 contra los enanos. Encontr\xf3 un aliado en Rend Pu\xf1o Negro, un orco que se hace llamar Jefe de Guerra de una Horda Oscura que se niega a seguir a Thrall.","La Cumbre de Roca Negra Inferior es el cuartel de esa Horda Oscura. Legiones de orcos Roca Negra, ogros Spirestone a las \xf3rdenes del Alto Se\xf1or Omokk, trols Smolderthorn del cazador de las sombras Vosh'gajin y las ara\xf1as que rodean a Mother Smolderweb comparten sus salas en ruinas bajo el mando del Se\xf1or Supremo Wyrmthalak. La \xe9lite y los dragones aguardan a\xfan m\xe1s arriba, en la Cumbre de Roca Negra Superior."]},"instance:capital-gardens":{title:"Capital Gardens",summary:"El distrito occidental de Eldre'Thalas, donde los \xfaltimos Altonato de los Shen'dralar se alimentan de un demonio enjaulado.",body:["Eldre'Thalas, hoy llamada La Masacre, se construy\xf3 para guardar los secretos arcanos de la reina Azshara, y sus custodios, los Shen'dralar, sobrevivieron a la Gran Escisi\xf3n. Privados del poder del Pozo de la Eternidad, su l\xedder, el pr\xedncipe Tortheldrin, mand\xf3 alzar cinco pilones para encerrar al demonio Immol'thar, y su pueblo se nutr\xeda de su energ\xeda para seguir siendo inmortal.","Con el paso de los siglos, la prisi\xf3n se debilit\xf3. Para conservar su propio poder, Tortheldrin se volvi\xf3 contra los dem\xe1s Shen'dralar y los consumi\xf3. Los Capital Gardens, anta\xf1o parque y corte de los Altonato, albergan ahora a sus \xfaltimos seguidores leales, \xe1rboles marchitos, ancestros furiosos y al propio demonio enjaulado."]},"instance:scholomance":{title:"Scholomance",summary:"La escuela de nigromancia de Kel'Thuzad en las criptas bajo Caer Darrow, entregada a la Plaga por la familia Barov.",body:["En una isla del Lago Darrowmere, en las Tierras de la Peste del Oeste, se alza Caer Darrow, anta\xf1o la fortaleza de la noble familia Barov. Cuando el mago Kel'Thuzad reuni\xf3 seguidores para su Culto de los Malditos, prometi\xf3 la inmortalidad en nombre del Rey Ex\xe1nime, y los Barov le entregaron su fortaleza y sus criptas. El culto convirti\xf3 las criptas en Scholomance, una escuela donde los nigromantes se formaban para propagar la peste.","Los Barov vieron cumplido su deseo de la peor manera y ahora rondan las salas como no-muertos. El ex\xe1nime Ras Frostwhisper gobierna la escuela para la Plaga, el Maestro Oscuro Gandling ejerce de director y el Ravenian acecha abajo, listo para devorar a los alumnos d\xe9biles."]},"instance:shapers-terrace":{title:"Shaper's Terrace",summary:"Una antigua instalaci\xf3n de los titanes en las colinas del norte del Cr\xe1ter de Un'Goro, que funciona con cristales de poder reunidos por todo el cr\xe1ter.",body:["En las alturas del norte del Cr\xe1ter de Un'Goro, una antigua instalaci\xf3n de los titanes domina una tierra que el tiempo parece haber dejado en paz. Dinosaurios, pozos de alquitr\xe1n, estructuras de los titanes y cristales luminosos forman parte de esta expedici\xf3n, pensada para grupos cercanos al nivel m\xe1ximo.","Su enigma va m\xe1s all\xe1 de sus muros: los grupos recogen cristales de poder por el cr\xe1ter y los usan en consolas dentro de la terraza, de modo que lo que encuentran en el exterior da forma a los desaf\xedos del interior."],unknowns:["Qui\xe9n construy\xf3 la terraza y para qu\xe9 serv\xeda.","Qu\xe9 hacen las consolas y qu\xe9 jefes aguardan dentro; los datos de esta gu\xeda a\xfan no recogen ninguno."]},"instance:stratholme":{title:"Stratholme",summary:"La ruina en llamas de la gran ciudad del norte de Lordaeron, dividida entre la Plaga del bar\xf3n Osahendido y la Cruzada Escarlata.",body:["Stratholme era la ciudad m\xe1s orgullosa del norte de Lordaeron y la cuna de la Orden de la Mano de Plata. En la Tercera Guerra, el pr\xedncipe Arthas pas\xf3 a cuchillo a sus habitantes antes que permitir que, tocados por la peste, se alzaran como no-muertos, y rompi\xf3 as\xed con su mentor Uther. La Plaga se instal\xf3 poco despu\xe9s, y la ciudad arde desde entonces.","Hoy dos enemigos se la reparten. La Cruzada Escarlata ocupa un lado bajo el Gran Cruzado Dathrohan, sin sospechar que en realidad es el se\xf1or del terror Balnazzar disfrazado. El otro lado pertenece a la Plaga y al caballero de la Muerte bar\xf3n Osahendido, un rico terrateniente de Stratholme y amigo de Kel'Thuzad antes de unirse al Culto de los Malditos."]},"instance:gordok-commons":{title:"Gordok Commons",summary:"El distrito norte de La Masacre, sede del rey Gordok y sus ogros, donde quien mata al rey se queda con la corona.",body:["Los ogros del clan Gordunni se han adue\xf1ado del barrio norte de la antigua Eldre'Thalas, la ciudad en ruinas de los Altonato hoy llamada La Masacre. Sus guerreros m\xe1s fuertes, los Gordok, gobiernan desde los Commons, y su rey adopta el nombre de rey Gordok.","Aqu\xed la costumbre ogra es sencilla: quien mata al rey se convierte en el nuevo rey Gordok. Los grupos astutos se escabullen entre los guardias Mol'dar, Fengus y Slip'kik, el Pisoteador Kreeg y el capit\xe1n Kromcrush para atacar solo al rey, y los ogros que sobreviven tratan a los vencedores como sus nuevos gobernantes y les pagan tributo. Cho'Rush el Observador est\xe1 al lado del rey."]},"instance:barrow-deeps":{title:"Barrow Deeps",summary:"Una banda de diez jugadores en la prisi\xf3n bajo Kalimdor que retuvo a Illidan Tempestira durante diez mil a\xf1os.",body:["En lo m\xe1s profundo bajo Kalimdor, los Barrow Deeps mantuvieron cautivo a Illidan Tempestira durante diez mil a\xf1os. Ahora el camino a sus t\xfaneles est\xe1 abierto, y las bandas descienden para descubrir qu\xe9 fue de quienes quedaron en la oscuridad y qu\xe9 piensan hacer las celadoras ante la amenaza que se agita abajo.","Tres caminos llevan al interior, conectados con el monte Hyjal, Cuna del Invierno y Blackmaw Hold. Diez jugadores se enfrentan a ocho jefes durante el descenso, desde la Deepscar Matriarch y Khalith the Dreadspinner hasta Del'lynar Songwood y, en \xfaltimo lugar, Sonya Darkhallow."],unknowns:["Qui\xe9n abri\xf3 los pasajes y cu\xe1l es el peligro que hay abajo.","Qui\xe9nes son las celadoras y cu\xe1les son las historias de los ocho jefes."]},"instance:hyjal-summit":{title:"Hyjal Summit",summary:"Una banda de veinte jugadores en la cima del monte Hyjal, cerca del \xc1rbol del Mundo Nordrassil, con trece jefes y muchos caminos.",body:["Hyjal Summit se encuentra en la cima del monte Hyjal, cerca del \xc1rbol del Mundo Nordrassil. Un antiguo guardi\xe1n cierra el paso al principio; despu\xe9s, las bandas eligen sus propias rutas por la monta\xf1a, entre ruinas en la superficie y bajo ella, y combaten todo lo que amenaza Hyjal hasta que se abre el camino a las batallas finales.","Veinte jugadores se enfrentan a trece jefes, entre ellos Bandalar, el Time-Lost Battalion, el Council of Thorns, el Wild King y el Ancient of Decay. El \xfaltimo de todos es Nythus the Dreambound."],unknowns:["Qu\xe9 fuerza amenaza Hyjal; el resumen oficial no la nombra.","Qui\xe9n es el antiguo guardi\xe1n y qui\xe9n es Nythus the Dreambound."]},"instance:onyxias-lair":{title:"Guarida de Onyxia",summary:"La guarida de Onyxia, madre de la progenie del Vuelo Negro, en el Marjal Revolcafango; solo pueden entrar quienes portan el Drakefire Amulet.",body:["En el Wyrmbog del Marjal Revolcafango, Onyxia, hija de Alamuerte y hermana de Nefarian, custodia su progenie en una caverna de fuego. Su arma m\xe1s poderosa es el enga\xf1o. Con forma humana, como lady Katrana Prestor, susurra en la corte de Ventormenta y trabaja para enfrentar entre s\xed a los reinos mortales.","Cuarenta jugadores se enfrentan a ella en una batalla de llamas en tres fases, as\xed que las bandas re\xfanen primero resistencia al fuego. Cada miembro debe llevar adem\xe1s el Drakefire Amulet, que se obtiene con una larga cadena de misiones: la Alianza, a trav\xe9s de la huida del mariscal Windsor de las Profundidades de Roca Negra y el desenmascaramiento en Ventormenta; la Horda, a trav\xe9s de Rexxar y el draco Emberstrife. Ambas terminan con el general Drakkisath en la Cumbre de Roca Negra Superior."]}}},991,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"items",{enumerable:!0,get:function(){return o}});const o={"item:demon-soul":{title:"El Alma de Drag\xf3n (Alma Demon\xedaca)",summary:"Un disco dorado forjado por Neltharion para dominar a todos los dragones; dio origen a Alamuerte y, eras despu\xe9s, encaden\xf3 al Vuelo Rojo a la Horda.",body:["Antes de la Guerra de los Ancestros, el Guardi\xe1n de la Tierra Neltharion hizo que sus sirvientes goblins fabricaran un disco dorado de aspecto sencillo, impregnado en secreto de la corrupci\xf3n de los Dioses Antiguos. Convenci\xf3 a los dem\xe1s Aspectos de que vertieran en \xe9l parte de su poder para luchar contra la Legi\xf3n Ardiente, y luego lo volvi\xf3 contra demonios y aliados por igual. Las energ\xedas del Alma de Drag\xf3n desgarraron su cuerpo, y Neltharion se convirti\xf3 en Alamuerte.","Tras la Gran Escisi\xf3n, los Aspectos escondieron el disco en lo m\xe1s profundo de lo que hoy son las Monta\xf1as Crestagrana. Siguiendo las visiones de Alamuerte, el clan Faucedraco lo recuper\xf3, lo rebautiz\xf3 como Alma Demon\xedaca y lo us\xf3 para esclavizar a Alexstrasza en Grim Batol. All\xed acab\xf3 haci\xe9ndose a\xf1icos, y los dragones rojos quedaron libres."]},"item:atiesh":{title:"Atiesh, gran bast\xf3n del Guardi\xe1n",summary:"El bast\xf3n de los Guardianes de Tirisfal, llevado por \xfaltimo por Medivh, despu\xe9s hecho pedazos y buscado por Kel'Thuzad.",body:["Atiesh pas\xf3 de Guardi\xe1n en Guardi\xe1n durante generaciones, hasta llegar a Medivh, el \xfaltimo de ellos. Las leyendas dicen que creci\xf3 de una \xabsemilla de odio\xbb y concede a su portador un poder sin fin; los cuervos se re\xfanen a su alrededor, y puede abrir un camino a Karazhan. Tras la ca\xedda de Medivh, el Kirin Tor guard\xf3 el bast\xf3n bajo llave en Dalaran, donde todo mago que lo toc\xf3 tuvo un final funesto.","Cuando Archimonde destruy\xf3 Dalaran, Atiesh se rompi\xf3 en decenas de pedazos que se esparcieron por Azeroth, y Kel'Thuzad se propuso reunirlos. En el juego original, las bandas arrancaban sus astillas de su necr\xf3polis de Naxxramas, hac\xedan restaurar el armaz\xf3n con ayuda del drag\xf3n bronce Anachronos y despu\xe9s ten\xedan que purificar el bast\xf3n en Stratholme derrotando al demonio encerrado en su interior."]},"item:scepter-of-the-shifting-sands":{title:"El Cetro de las Arenas Movedizas",summary:"La llave del Muro del Escarabajo que sellaba Ahn'Qiraj, hecha pedazos por un afligido Fandral Corzocelada.",body:["Casi mil a\xf1os antes de la Primera Guerra, los insectoides qiraji salieron en masa de Ahn'Qiraj, azuzados por el Dios Antiguo C'Thun. El archidruida Fandral Corzocelada dirigi\xf3 a los elfos de la noche contra ellos, pero su hijo Valstann cay\xf3 ante sus ojos y la guerra cambi\xf3 de rumbo. Solo con la ayuda de cuatro vuelos de dragones se logr\xf3 hacer retroceder a los enjambres y encerrarlos tras el Muro del Escarabajo.","El muro solo pod\xeda abrirse golpeando el Gong del Escarabajo con este cetro. Fandral, en la furia de su dolor, lo hizo pedazos, y sus fragmentos se dispersaron. En el juego original, los aventureros volvieron a montar el cetro, hicieron sonar el gong y abrieron Ahn'Qiraj una vez m\xe1s."]},"item:doomhammer":{title:"Martillo Maldito",summary:"El martillo de guerra heredado del linaje Martillo Maldito, que Orgrim llev\xf3 durante dos guerras y entreg\xf3 a Thrall.",body:["Forjado hace mucho en Draenor, el gran martillo de piedra negra pas\xf3 de padre a hijo dentro de una sola familia orca, y sobre \xe9l pesaba una antigua profec\xeda de los Roca Negra: el \xfaltimo del linaje traer\xeda a los orcos primero la salvaci\xf3n y luego la perdici\xf3n, antes de que un extra\xf1o alzara el martillo por la justicia. Orgrim Martillo Maldito lo empu\xf1\xf3 en la Primera y la Segunda Guerra y con \xe9l abati\xf3 a Anduin Lothar, haciendo pedazos la runoespada del caballero.","Tras la derrota de la Horda, Orgrim escap\xf3 del cautiverio y luch\xf3 por liberar a su pueblo de los campos de internamiento. Herido de muerte en una de esas batallas, entreg\xf3 el martillo a Thrall, que no era ni de su clan ni de su sangre. Thrall lo llev\xf3 como s\xedmbolo de una Horda renacida, y la profec\xeda encontr\xf3 a su extra\xf1o."]},"item:book-of-medivh":{title:"El Libro de Medivh",summary:"El \xfaltimo libro de hechizos de Medivh que se conserva, usado dos veces para abrir a la fuerza el paso entre los mundos.",body:["Tras la muerte de Medivh, su libro de hechizos se guard\xf3 en la biblioteca real de la Ventormenta reconstruida, hasta que unos agentes de Alterac lo robaron. Por un trato entre el rey de Alterac y el caballero de la Muerte de la Horda Teron Sanguino, pas\xf3 a manos de los orcos, y en Draenor Ner'zhul lo us\xf3 junto con otras reliquias para abrir nuevos portales, grietas que desgarraron su mundo. Antes de que cayera el Portal Oscuro, Khadgar recuper\xf3 el libro y lo envi\xf3 a casa a lomos de un grifo.","El Kirin Tor lo sell\xf3 en una c\xe1mara de Dalaran. Durante la Tercera Guerra, Kel'Thuzad destroz\xf3 esa c\xe1mara y, con el poder del libro, abri\xf3 la grieta por la que Archimonde y la Legi\xf3n Ardiente entraron en Azeroth. Despu\xe9s, el libro qued\xf3 en manos del ex\xe1nime."]},"item:frostmourne":{title:"Agon\xeda de Escarcha",summary:"La runoespada del Rey Ex\xe1nime, que se cobr\xf3 el alma de Arthas Menethil en el hielo de Rasganorte.",body:["Agon\xeda de Escarcha estaba ligada a la prisi\xf3n del Rey Ex\xe1nime en Corona de Hielo, y Ner'zhul la expuls\xf3 del Trono Helado para atraer a un campe\xf3n. Aguardaba custodiada en una caverna helada de Rasganorte, con la advertencia de que su poder marcar\xeda el alma de quien la tomara. El pr\xedncipe Arthas, desesperado por detener la peste, ignor\xf3 la advertencia y empu\xf1\xf3 la espada mientras Muradin Barbabronce yac\xeda abatido por un fragmento de hielo.","La espada devora las almas de quienes mata. Con ella, Arthas mat\xf3 al se\xf1or del terror Mal'Ganis, luego a su propio padre, el rey Terenas, y a su antiguo mentor Uther. En el a\xf1o 25 descansa junto al propio Rey Ex\xe1nime. En historias posteriores, m\xe1s all\xe1 de Classic, Tirion Fordring la hizo pedazos con la Crematoria."]},"item:ashbringer":{title:"La Crematoria",summary:"Una espada sagrada forjada en Forjaz para reducir a cenizas a los no-muertos, despu\xe9s traicionada y corrompida en las Tierras de la Peste.",body:["Durante la Segunda Guerra, el alto se\xf1or Alexandros Mograine de la Mano de Plata encontr\xf3 un cristal oscuro en el cuerpo de un brujo orco abatido. Cuando la Plaga amenaz\xf3 Lordaeron, los l\xedderes de la orden intentaron destruirlo con magia sagrada; en cambio, el cristal absorbi\xf3 la Luz y se volvi\xf3 radiante. El rey Magni Barbabronce lo forj\xf3 como espada sobre el Gran Yunque de Forjaz, y en manos de Mograine la Crematoria reduc\xeda a cenizas a los no-muertos.","El se\xf1or del terror Balnazzar y Kel'Thuzad tramaron su ca\xedda. Renault, el hijo de Mograine, lo condujo a una emboscada de la Plaga en Stratholme y lo mat\xf3 con su propia espada, corrompi\xe9ndola. En el a\xf1o 25, Alexandros sirve a Kel'Thuzad como caballero de la Muerte, mientras Renault dirige el Monasterio Escarlata. Solo en historias posteriores se purific\xf3 la espada."]},"item:skull-of-guldan":{title:"El Cr\xe1neo de Gul'dan",summary:"El cr\xe1neo del brujo, una reliquia demon\xedaca que abri\xf3 portales, envenen\xf3 Vallefresno y transform\xf3 a Illidan.",body:["Gul'dan fue despedazado por los demonios en la Tumba de Sargeras, pero su cr\xe1neo conserv\xf3 una astilla de su malicia. Pas\xf3 por varias manos orcas hasta que Grom Grito Infernal se lo llev\xf3 a Ner'zhul, que lo us\xf3 para ayudar a reabrir el Portal Oscuro. M\xe1s tarde, Khadgar lo envi\xf3 a Dalaran junto con el Libro de Medivh, y el Kirin Tor custodi\xf3 ambos.","Cuando Dalaran cay\xf3 en la Tercera Guerra, el se\xf1or del terror Tichondrius rob\xf3 el cr\xe1neo, y su poder corrompi\xf3 los bosques de Vallefresno y Frondavil. Illidan Tempestira consumi\xf3 su magia, se convirti\xf3 en medio demonio y mat\xf3 a Tichondrius con ese poder. La c\xe1scara vac\xeda del cr\xe1neo qued\xf3 en manos de Illidan."]},"item:gorehowl":{title:"Gorehowl",summary:"El hacha aullante de la familia Grito Infernal, que derrib\xf3 tanto a Cenarius como a Mannoroth.",body:["Gorehowl se forj\xf3 generaciones antes de que Grom Grito Infernal la heredara, y una leyenda de los Grito de Guerra dice que el hacha se templ\xf3 con los corazones de poderosos gronn. Grom, jefe del clan Grito de Guerra, fue el primero en beber la sangre del se\xf1or del foso Mannoroth, atando as\xed a los orcos a la Legi\xf3n Ardiente. En Vallefresno volvi\xf3 a beber y, con Gorehowl, mat\xf3 al semidi\xf3s Cenarius.","Thrall lo liber\xf3 del dominio del demonio, y juntos se enfrentaron a Mannoroth. Grom parti\xf3 el arma del se\xf1or del foso y lo mat\xf3 de un solo golpe, rompiendo la maldici\xf3n de su pueblo a costa de su propia vida. Despu\xe9s, Thrall guard\xf3 el hacha en Orgrimmar."]},"item:horn-of-cenarius":{title:"El Cuerno de Cenarius",summary:"El cuerno del semidi\xf3s, que despert\xf3 a los druidas de su largo sue\xf1o y llam\xf3 a los ancestros de los elfos de la noche en Hyjal.",body:["Tras la ca\xedda de Cenarius, su cuerno permaneci\xf3 en el Claro de la Luna bajo la vigilancia de antiguos guardianes. Cuando la Legi\xf3n Ardiente regres\xf3 en la Tercera Guerra, la sacerdotisa Tyrande Susurravientos lo recuper\xf3 y lo us\xf3 para despertar a Malfurion Tempestira de su largo sue\xf1o. Malfurion, a su vez, lo hizo sonar para despertar a los druidas dormidos del Espol\xf3n y de la Garra.","En el momento culminante de la Batalla del Monte Hyjal, Malfurion volvi\xf3 a tocar el cuerno. Miles de esp\xedritus ancestrales respondieron y se abalanzaron sobre Archimonde, destruyendo al se\xf1or demon\xedaco al pie del \xc1rbol del Mundo, aunque el poder desatado dej\xf3 herido a Nordrassil."]},"item:sulfuras":{title:"Sulfuras, mano de Ragnaros",summary:"El martillo ardiente del Se\xf1or del Fuego y la copia m\xe1s peque\xf1a que los maestros herreros aprendieron a forjar a su imagen.",body:["Sulfuras es el colosal martillo de Ragnaros, una masa de elementium rojo en llamas que el Se\xf1or del Fuego nunca suelta. En las guerras elementales de un pasado remoto, abati\xf3 con \xe9l a Thunderaan, el pr\xedncipe del Aire. Desde la invocaci\xf3n de Thaurissan, Ragnaros gobierna el N\xfacleo de Magma, bajo la Monta\xf1a Roca Negra, con el martillo en la mano.","El arma verdadera es demasiado enorme para manos mortales, pero se puede hacer una r\xe9plica. En el juego original, un maestro herrero obten\xeda los planos de un Martillo de Sulfuron de Lokhtos Tratoscuro, de la Hermandad del Torio, en las Profundidades de Roca Negra, y luego lo un\xeda al raro Ojo de Sulfuras arrebatado al propio Ragnaros, creando una Mano de Ragnaros a la medida de un mortal."]},"item:thunderfury":{title:"Furia de Trueno, Espada Bendita del Buscavientos",summary:"Una espada forjada en torno a la \xfaltima esencia de Thunderaan, el pr\xedncipe del Aire, al que Ragnaros hab\xeda encarcelado.",body:["En una antigua guerra entre el fuego y el aire, Ragnaros y sus lugartenientes Garr y el bar\xf3n Geddon derrotaron a Thunderaan, el pr\xedncipe del Aire. El Se\xf1or del Fuego se aliment\xf3 de su esencia, pero no pudo devorarla entera, as\xed que sell\xf3 el resto en un talism\xe1n, lo parti\xf3 en dos y entreg\xf3 una mitad a cada lugarteniente: las Ataduras del Buscavientos.","En el juego original, las bandas arrebataban ambas mitades a Garr y a Geddon en el N\xfacleo de Magma y las llevaban al alto se\xf1or Demitrian, en Silithus. Con la esencia del propio Se\xf1or del Fuego y barras de elementium encantado, las ataduras invocaban al debilitado pr\xedncipe; una vez derrotado, Demitrian forjaba el poder que le quedaba en Furia de Trueno, una espada que crepita con una tormenta viva."]},"item:seal-of-ascension":{title:"Sello de Ascensi\xf3n",summary:"Un anillo forjado en fuego de drag\xf3n negro que abr\xeda la ciudadela superior de la Cumbre de Roca Negra.",body:["Las salas superiores de la Cumbre de Roca Negra, donde Rend Pu\xf1o Negro y el Vuelo Negro ten\xedan su corte, estaban selladas contra los intrusos. En la cumbre inferior, un extra\xf1o disfrazado llamado Vaelan, en realidad el drag\xf3n rojo Vaelastrasz, que hab\xeda jurado dar caza a Nefarian, ense\xf1aba a los aventureros a fabricar una llave: un sello sin adornos engastado con tres gemas arrebatadas a los comandantes Smolderthorn, Spirestone y Hacha de Sangre de la Cumbre.","Despu\xe9s, el sello deb\xeda forjarse en fuego de drag\xf3n negro. Los h\xe9roes viajaban al Wyrmbog del Marjal Revolcafango y obligaban al draco Emberstrife a soplar sobre \xe9l. El anillo terminado abr\xeda la ciudadela superior y, en la lucha contra Rend, pod\xeda llamar una proyecci\xf3n de Vaelastrasz al lado de los h\xe9roes."]},"item:drakefire-amulet":{title:"Drakefire Amulet",summary:"El amuleto roto de Onyxia, rehecho con la sangre de un drag\xf3n negro hasta convertirse en la llave de su propia guarida.",body:["Disfrazada de lady Katrana Prestor, Onyxia se abri\xf3 paso en la corte de Ventormenta con un colgante llamado el Ojo del Drag\xf3n. No dominaba las mentes directamente, pero despertaba deseos ocultos y apartaba de ella las sospechas. Cuando el mariscal Windsor desenmascar\xf3 la farsa, el colgante se hizo a\xf1icos, y el drag\xf3n azul Haleh reh\xedzo sus pedazos, con la sangre del general Drakkisath, hasta formar el Drakefire Amulet.","Los h\xe9roes de la Horda llegan al mismo amuleto por otro camino, a trav\xe9s de Rexxar y las pruebas del antiguo draco Emberstrife. Todo miembro de una banda que entre en la Guarida de Onyxia debe llevarlo, y Forever mantiene esta sintonizaci\xf3n como una cadena de misiones distinta para cada facci\xf3n."]},"item:head-of-onyxia":{title:"Cabeza de Onyxia",summary:"La prueba de la muerte de la Madre de la Progenie, alzada sobre las puertas de Ventormenta u Orgrimmar como estandarte de \xe1nimo.",body:["Onyxia, hija de Alamuerte y hermana menor de Nefarian, custodia su progenie en una caverna del Marjal Revolcafango mientras conspira para doblegar a su voluntad los reinos mortales de Azeroth. Derrotarla puso fin a uno de los enga\xf1os m\xe1s largos del Vuelo Negro.","En el juego original, su cabeza se llevaba a casa como trofeo: los campeones de la Alianza la presentaban en Ventormenta, y los de la Horda, ante Thrall en Orgrimmar. Alzada sobre las puertas de la ciudad, otorgaba el Grito de batalla del Cazadragones a todos los que estaban en la ciudad, y toda la capital celebraba la victoria."]},"item:quel-serrar":{title:"Quel'Serrar",summary:"Una antigua espada de los elfos de la noche que guardaban los Shen'dralar y que solo se completa en el aliento de un drag\xf3n.",body:["Quel'Serrar es una de las espadas prism\xe1ticas que los herreros elfos de la noche forjaron hace mucho con ayuda de los vuelos de dragones; su gemela, Quel'Delar, fue entregada a los altos elfos. Durante miles de a\xf1os, los Shen'dralar de Eldre'Thalas la guardaron a la espera de un portador lo bastante fuerte para despertarla.","En el juego original, un guerrero o palad\xedn que encontraba un viejo compendio sobre la caza de dragones se lo llevaba al Tradicionalista Lydros, en la biblioteca de La Masacre, y recib\xeda una hoja sin templar. Calentado por el aliento profundo de Onyxia y hundido en el drag\xf3n abatido, el acero se convert\xeda en Quel'Serrar una vez devuelto a Lydros."]},"item:rhokdelar":{title:"Rhok'delar y Lok'delar",summary:"Un arco largo y un bast\xf3n vivos, moldeados por los Ancestros corrompidos de Frondavil para el cazador que los veng\xf3.",body:["Cuando la Legi\xf3n Ardiente arras\xf3 Kalimdor, envenen\xf3 el valle que se convirti\xf3 en Frondavil. Sus Ancestros m\xe1s poderosos se marchitaron hasta quedar como c\xe1scaras petrificadas, pero sus esp\xedritus perduraron. Una hoja de uno de ellos, Vartrus, acab\xf3 en el tesoro del Se\xf1or del Fuego, en el N\xfacleo de Magma.","En el juego original, el cazador que devolv\xeda la hoja a Vartrus era enviado a dar caza en solitario a cuatro agentes de la Legi\xf3n, sin siquiera una mascota. A cambio, los Ancestros creaban Rhok'delar, un arco largo que florece por s\xed solo, y su compa\xf1ero Lok'delar, un bast\xf3n que brilla con el poder de la naturaleza."]},"item:taelans-hammer":{title:"El martillo de Taelan",summary:"El martillo de juguete de un ni\xf1o, que ayud\xf3 a Tirion Fordring a llegar al hijo que la Cruzada Escarlata le hab\xeda arrebatado.",body:["En su s\xe9ptimo cumplea\xf1os, el joven Taelan recibi\xf3 de su padre, Tirion Fordring, un martillo de guerra en miniatura, copia del de Tirion. Despu\xe9s de que Tirion fuera desterrado por defender al orco Eitrigg, la madre de Taelan le dijo al ni\xf1o que su padre hab\xeda muerto y lo llev\xf3 a una tumba falsa en el Undercroft, en las Tierras de la Peste del Este, donde el ni\xf1o enterr\xf3 el martillo y, con \xe9l, el recuerdo.","A\xf1os despu\xe9s, Taelan lleg\xf3 a ser alto se\xf1or de la Cruzada Escarlata en Vega del Amparo. En el juego original, los aventureros recuperaban el martillo para el anciano Tirion y ayudaban a Taelan a ver en qu\xe9 se hab\xeda convertido la Cruzada. Mientras hu\xeda de Vega del Amparo, el gran inquisidor Isillien lo abati\xf3 ante los ojos de su padre; Tirion mat\xf3 a Isillien y jur\xf3 volver a forjar la Mano de Plata."]},"item:heart-of-hakkar":{title:"Coraz\xf3n de Hakkar",summary:"El coraz\xf3n todav\xeda ardiente del Dios de la Sangre, llevado a los Zandalari despu\xe9s de que Hakkar muriera en Zul'Gurub.",body:["Unos quince siglos antes del Portal Oscuro, los hambrientos trols Gurubashi recurrieron a Hakkar el Desollador de Almas, un loa de la sangre. \xc9l les dio poder y un imperio, y luego exigi\xf3 cada vez m\xe1s vidas, hasta que las tribus se alzaron contra \xe9l y desterraron a sus sacerdotes Atal'ai. Cuando los sacerdotes levantaron un templo para traerlo de vuelta, Ysera lo destroz\xf3 y lo hundi\xf3 bajo las ci\xe9nagas del Pantano de las Penas.","En el juego original, los sacerdotes Hakkari lograron por fin atraer al Desollador de Almas a Zul'Gurub. Los h\xe9roes reunidos por la tribu Zandalar lo mataron all\xed y llevaron su coraz\xf3n, a\xfan resplandeciente, a Molthor, en la Isla de Yojamba, cuyo rito bendec\xeda con el Esp\xedritu de Zandalar a todos los que estaban en la isla y en Bah\xeda del Bot\xedn."]},"item:phylactery-of-kelthuzad":{title:"La filacteria de Kel'Thuzad",summary:"El recipiente que guarda el alma del archiex\xe1nime, sacado de Naxxramas tras su derrota.",body:["Kel'Thuzad, anta\xf1o archimago del Kirin Tor, fund\xf3 el Culto de los Malditos y propag\xf3 la peste para el Rey Ex\xe1nime. Asesinado por Arthas y llevado m\xe1s tarde a la Fuente del Sol para renacer como ex\xe1nime, lleg\xf3 a gobernar la Plaga en Lordaeron desde la necr\xf3polis flotante de Naxxramas.","Un ex\xe1nime perdura mientras sobreviva el recipiente que guarda su alma. En el juego original, las bandas que derrotaban a Kel'Thuzad recuperaban su filacteria y se la entregaban al Alba Argenta para que la custodiara. Historias posteriores revelaron que uno de sus sacerdotes, el padre Inigo Montoy, traicion\xf3 esa confianza y la llev\xf3 a Rasganorte, dando al archiex\xe1nime tiempo para regresar."]}}},992,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"terms",{enumerable:!0,get:function(){return o}});const o={"term:argent-dawn":{title:"Alba Argenta",summary:"Una orden que ha jurado defender Azeroth de la Plaga sin el odio ciego de la Cruzada Escarlata.",body:["Cuando los supervivientes de la Mano de Plata en Lordaeron se endurecieron hasta convertirse en la fan\xe1tica Cruzada Escarlata, algunos se negaron a seguirlos. Encabezados por figuras como lord Maxwell Tyrosus, formaron el Alba Argenta, que acoge a cualquiera dispuesto a luchar contra los no-muertos. Desde la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, la orden vigila a la Plaga y recompensa a quienes ayudan a mantener la l\xednea."]},"term:burning-legion":{title:"Legi\xf3n Ardiente",summary:"El ej\xe9rcito infinito de demonios del tit\xe1n ca\xeddo Sargeras, que ha jurado reducir a cenizas toda la creaci\xf3n.",body:["Anta\xf1o campe\xf3n del Pante\xf3n de los titanes, Sargeras descubri\xf3 que los poderes del Vac\xedo pretend\xedan corromper las almas del mundo y, desesperado, decidi\xf3 quemar la creaci\xf3n antes que dejar que cayera en sus manos. Liber\xf3 a los demonios que hab\xeda encarcelado y se gan\xf3 a los se\xf1ores eredar Kil'jaeden y Archimonde para que los dirigieran. La Legi\xf3n invadi\xf3 Azeroth en la Guerra de los Ancestros y de nuevo en la Tercera Guerra, y sus agentes a\xfan acechan en lugares como Frondavil y Las Tierras Devastadas."]},"term:cenarion-circle":{title:"C\xedrculo Cenarion",summary:"La orden dru\xeddica de elfos de la noche y tauren que protege el equilibrio de la naturaleza desde el Claro de la Luna.",body:["Llamado as\xed por el semidi\xf3s Cenarius, que ense\xf1\xf3 a los primeros druidas, el C\xedrculo une a druidas elfos de la noche y tauren en una sola orden. Su coraz\xf3n es la aldea de Amparo de la Noche, en el Claro de la Luna, un santuario donde est\xe1 prohibido luchar, y sus miembros tambi\xe9n vigilan los peligros de Silithus desde el Fuerte Cenarion."]},"term:cult-of-the-damned":{title:"Culto de los Malditos",summary:"El culto al Rey Ex\xe1nime fundado por Kel'Thuzad, que promet\xeda la vida eterna y trajo la peste.",body:["El archimago Kel'Thuzad dio la espalda al Kirin Tor para estudiar nigromancia y reuni\xf3 a los pobres y desesperados de Lordaeron con promesas de una vida mejor y sin muerte. El culto ocult\xf3 la peste del Rey Ex\xe1nime en cargamentos de grano y convirti\xf3 aldeas enteras en Plaga. Sus nigromantes a\xfan ense\xf1an en Scholomance, en Caer Darrow, la antigua fortaleza de la familia Barov."]},"term:dark-portal":{title:"Portal Oscuro",summary:"La puerta entre Draenor y Azeroth por la que invadi\xf3 la Horda orca.",body:["El brujo orco Gul'dan y el Guardi\xe1n pose\xeddo Medivh abrieron el Portal Oscuro, que uni\xf3 Draenor con La Ci\xe9naga Negra de Azeroth. Su apertura dio comienzo a la Primera Guerra, y los a\xf1os de la historia de Warcraft todav\xeda se cuentan desde ella. La Alianza lo destruy\xf3 tras la Segunda Guerra, Ner'zhul volvi\xf3 a abrirlo a la fuerza y Khadgar lo derrumb\xf3 desde el lado de Draenor. Su armaz\xf3n inactivo a\xfan se alza sobre Las Tierras Devastadas."]},"term:defias-brotherhood":{title:"Hermandad Defias",summary:"Canteros de Ventormenta a los que nunca pagaron, convertidos en bandidos bajo Edwin VanCleef.",body:["El Gremio de Canteros reconstruy\xf3 Ventormenta tras la Segunda Guerra, pero los nobles se negaron a pagarle. Su l\xedder, Edwin VanCleef, llev\xf3 a los airados canteros a los P\xe1ramos de Poniente y los forj\xf3 como la Hermandad Defias, una banda de ladrones y saboteadores escondida en las Minas de la Muerte. En Forever, sus miembros tambi\xe9n aparecen dentro de Alcaz Prison, enzarzados en una lucha con los nagas."]},"term:dragon-aspects":{title:"Aspectos Drag\xf3n",summary:"Cinco grandes dragones a los que los titanes dieron poder para proteger Azeroth, cada uno al frente de un vuelo de dragones.",body:["Los titanes eligieron a cinco dragones y dieron a cada uno una parte de su poder: Alexstrasza la Protectora de la Vida, del Vuelo Rojo; Ysera la So\xf1adora, del verde; Nozdormu el Atemporal, del bronce; Malygos el Tejehechizos, del azul; y Neltharion el Guardi\xe1n de la Tierra, del negro. La traici\xf3n de Neltharion lo convirti\xf3 en Alamuerte, y sus hijos Onyxia y Nefarian a\xfan conspiran en Azeroth."]},"term:elemental-lords":{title:"Se\xf1ores Elementales",summary:"Los cuatro soberanos del fuego, la tierra, el aire y el agua, anta\xf1o servidores de los Dioses Antiguos.",body:["Ragnaros del fuego, Therazane de la tierra, Al'Akir del aire y Neptulon del agua dirigieron a los elementales en la guerra de los Dioses Antiguos contra los servidores de los titanes. Cuando cay\xf3 el Imperio Negro, los guardianes los encerraron en el Plano Elemental. Los chamanes procuran mantener los elementos en equilibrio, mientras que el error del hechicero Hierro Negro Thaurissan devolvi\xf3 a Ragnaros al mundo, bajo la Monta\xf1a Roca Negra."]},"term:elune":{title:"Elune",summary:"La diosa lunar de los elfos de la noche, cuyas sacerdotisas gu\xedan a su pueblo.",body:["Los elfos de la noche adoran a Elune desde los albores de su civilizaci\xf3n y encuentran gu\xeda en la luz de la luna. La Hermandad de Elune, dirigida por la suma sacerdotisa Tyrande Susurravientos, act\xfaa a la vez como clero y como gobierno en Darnassus, y los sacerdotes elfos de la noche obtienen de la diosa su poder de sanaci\xf3n."]},"term:emerald-dream":{title:"Sue\xf1o Esmeralda",summary:"Un reflejo on\xedrico de las tierras salvajes e intactas de Azeroth, vigilado por Ysera y recorrido por los druidas.",body:["El Sue\xf1o Esmeralda refleja el mundo tal como podr\xeda haber sido sin la mano de los mortales. Ysera y su vuelo verde lo custodian, y los druidas entran en \xe9l en esp\xedritu, a veces durmiendo durante siglos. En el presente de Azeroth, algo est\xe1 agriando el Sue\xf1o: una pesadilla que se extiende retuerce los sue\xf1os de Naralex en las Cuevas de los Lamentos y ha enloquecido a los dragones verdes del Templo Sumergido."]},"term:explorers-league":{title:"Liga de Expedicionarios",summary:"La sociedad de arque\xf3logos enanos de Forjaz, que excava en busca de los secretos de los titanes.",body:["Desde la Sala de los Expedicionarios de Forjaz, la Liga env\xeda enanos por todo el mundo en busca de reliquias que puedan explicar de d\xf3nde procede su pueblo. Su miembro m\xe1s famoso es Brann Barbabronce, el inquieto hermano del rey. Los excavadores de la Liga desenterraron las c\xe1maras tit\xe1nicas de Uldaman, y en Forever las extra\xf1as ruinas congeladas en el tiempo m\xe1s all\xe1 del Whelgar's Excavation Site, en Los Humedales, son exactamente el tipo de misterio que persigue la Liga."]},"term:fel":{title:"Magia vil",summary:"La magia ardiente y corruptora de la Legi\xf3n Ardiente.",body:["La magia vil es la magia de los demonios: poderosa, adictiva y ruinosa para todo lo que toca. Los brujos de Gul'dan la usaron para drenar la vida de Draenor y atar a los orcos a la Legi\xf3n, y su m\xe1cula les volvi\xf3 la piel verde. Los brujos a\xfan la empu\xf1an hoy, y sus cicatrices marcan Frondavil, donde la corrupci\xf3n demon\xedaca ha envenenado un bosque ancestral."]},"term:guardian-of-tirisfal":{title:"Guardi\xe1n de Tirisfal",summary:"Un mago al que se otorga el poder conjunto de un consejo secreto para combatir en solitario a la Legi\xf3n Ardiente.",body:["Magos altos elfos y humanos formaron el secreto Consejo de Tirisfal para impedir que los demonios se colaran en el mundo a trav\xe9s de una magia imprudente. En cada era, el consejo vert\xeda su poder en un \xfanico campe\xf3n, el Guardi\xe1n. Aegwynn desempe\xf1\xf3 ese papel durante siglos; su hijo Medivh, el \xfaltimo Guardi\xe1n, estaba pose\xeddo en secreto por Sargeras y abri\xf3 el camino a los orcos."]},"term:highborne":{title:"Altonatos",summary:"La aristocracia arcana del antiguo imperio de los elfos de la noche, cuya sed de magia atrajo a la Legi\xf3n.",body:["Los Altonatos serv\xedan a la reina Azshara como su corte y sus hechiceros, y beb\xedan cada vez m\xe1s del Pozo de la Eternidad hasta que sus hechizos llamaron la atenci\xf3n de Sargeras. Tras la Gran Escisi\xf3n, la mayor\xeda de los supervivientes fueron desterrados y fundaron Quel'Thalas como altos elfos. Otros, los Shen'dralar, permanecieron ocultos en Eldre'Thalas, la ciudad que hoy se llama La Masacre."]},"term:holy-light":{title:"La Luz Sagrada",summary:"El poder de la esperanza y la virtud que canalizan paladines y sacerdotes.",body:["Los humanos veneran la Luz a trav\xe9s de la Iglesia de la Luz Sagrada, cuyos cl\xe9rigos curan a los heridos y cuyas catedrales se alzan en Ventormenta y anta\xf1o se alzaron en Lordaeron. Los enanos tambi\xe9n la abrazaron. Durante la Segunda Guerra, el arzobispo Alonsus Faol uni\xf3 fe y acero al fundar a los paladines de la Mano de Plata, y la Luz sigue siendo la perdici\xf3n de los no-muertos."]},"term:kaldorei":{title:"Kaldorei",summary:"Los elfos de la noche, \xabhijos de las estrellas\xbb, una de las civilizaciones m\xe1s antiguas de Kalimdor.",body:["Descendientes de trols transformados por el Pozo de la Eternidad, los elfos de la noche construyeron bajo la reina Azshara un imperio deslumbrante antes de que se hundiera en la Gran Escisi\xf3n. Durante diez mil a\xf1os vivieron como druidas y Centinelas, sin envejecer gracias a Nordrassil, hasta que la Tercera Guerra les cost\xf3 la inmortalidad. Hoy gobiernan desde Darnassus, en lo alto de Teldrassil, y est\xe1n del lado de la Alianza."]},"term:kirin-tor":{title:"Kirin Tor",summary:"El consejo de magos que gobierna Dalaran y guarda la magia peligrosa.",body:["Fundado en la ciudad de los magos, Dalaran, el Kirin Tor supervisa el estudio de la magia arcana y guarda bajo llave los artefactos demasiado peligrosos para el mundo. Archimonde dej\xf3 Dalaran en ruinas durante la Tercera Guerra, y en el juego original la ciudad permanec\xeda oculta bajo una c\xfapula violeta. En Forever esa barrera ha ca\xeddo y deja ver una restauraci\xf3n arrollada por un caos arcano desbocado."]},"term:ley-lines":{title:"L\xedneas Ley",summary:"Corrientes de energ\xeda arcana que recorren Azeroth como venas.",body:["Las l\xedneas ley transportan poder arcano en bruto por todo el mundo, y donde se cruzan, la magia gana fuerza. Los altos elfos levantaron la Fuente del Sol en uno de esos nexos, y los magos llevan mucho tiempo buscando estas corrientes. En Forever, los Skyborne de la High Order pueden aprovecharlas con su habilidad racial Read Ley Line, que dura mucho m\xe1s si se usa cerca de una de ellas."]},"term:lich-king":{title:"Rey Ex\xe1nime",summary:"El se\xf1or inmortal de la Plaga, entronizado en el hielo de Rasganorte.",body:["Kil'jaeden arranc\xf3 el esp\xedritu del cham\xe1n orco Ner'zhul de su cuerpo y lo sell\xf3 en un bloque de hielo en lo alto de Corona de Hielo, el Trono Helado, para preparar Azeroth para la Legi\xf3n. Desde all\xed, el Rey Ex\xe1nime alz\xf3 a la Plaga y propag\xf3 la peste. Tras la Tercera Guerra, el pr\xedncipe Arthas subi\xf3 al trono y se fusion\xf3 con \xe9l, y el Rey Ex\xe1nime unificado aguarda ahora en Rasganorte."]},"term:loa":{title:"Loa",summary:"Los poderosos esp\xedritus animales y dioses que veneran los trols.",body:["Toda tribu trol honra a los loa, esp\xedritus antiguos que a menudo adoptan la forma de grandes bestias, y negocia con ellos para obtener fuerza. Algunos son volubles pero justos; otros, crueles. Hakkar el Desollador de Almas, el loa de la sangre, estuvo a punto de devorar el Imperio Gurubashi, y sus seguidores a\xfan se agitan en la Vega de Tuercespina y el Pantano de las Penas."]},"term:nathrezim":{title:"Nathrezim",summary:"Los se\xf1ores del terror: demonios astutos y vamp\xedricos que sirven a la Legi\xf3n mediante el enga\xf1o.",body:["Los nathrezim prefieren los susurros a la guerra abierta. La Legi\xf3n encarg\xf3 a se\xf1ores del terror como Mal'Ganis, Tichondrius y Balnazzar vigilar al Rey Ex\xe1nime y guiar la conquista de Lordaeron por parte de la Plaga. Cuando el Rey Ex\xe1nime se liber\xf3 de ellos, se dispersaron, pero algunos a\xfan se ocultan a la vista de todos: Balnazzar lleva el rostro del Gran Cruzado de la Cruzada Escarlata."]},"term:nordrassil":{title:"Nordrassil",summary:"El \xc1rbol del Mundo del monte Hyjal, plantado por los Aspectos para sellar el segundo Pozo de la Eternidad.",body:["Tras la Gran Escisi\xf3n, Illidan verti\xf3 en secreto agua robada del Pozo de la Eternidad en un lago del monte Hyjal. Para sellar ese nuevo pozo, los Aspectos Drag\xf3n plantaron una semilla encantada que creci\xf3 hasta convertirse en Nordrassil, y su bendici\xf3n hizo que los elfos de la noche no envejecieran. La ca\xedda de Archimonde a sus ra\xedces hiri\xf3 al \xe1rbol, y la banda Hyjal Summit de Forever asciende hasta la cumbre que hay a su lado."]},"term:old-gods":{title:"Dioses Antiguos",summary:"Seres ancestrales del Vac\xedo que se enterraron en Azeroth para corromper su alma del mundo.",body:["Mucho antes de que los mortales caminaran por el mundo, los Dioses Antiguos, entre ellos C'Thun, Yogg-Saron, N'Zoth e Y'Shaarj, se estrellaron contra Azeroth y alzaron un Imperio Negro. Arrancar a Y'Shaarj hiri\xf3 al propio mundo, as\xed que los titanes optaron por encerrar a los dem\xe1s bajo tierra. Sus susurros a\xfan impulsan cultos como el Martillo Crepuscular, y C'Thun se agita bajo Ahn'Qiraj, en Silithus."]},"term:silver-hand":{title:"Orden de la Mano de Plata",summary:"La primera orden de paladines, fundada en Lordaeron durante la Segunda Guerra.",body:["El arzobispo Alonsus Faol comprendi\xf3 que los cl\xe9rigos por s\xed solos no sobrevivir\xedan a la Horda, as\xed que adiestr\xf3 a guerreros en los caminos de la Luz. Uther el Iluminado fue el primero de los Caballeros de la Mano de Plata. La orden combati\xf3 durante toda la Segunda Guerra, pero la ca\xedda de Arthas la quebr\xf3: Uther muri\xf3 a manos de su antiguo alumno, y muchos supervivientes acabaron uni\xe9ndose a la Cruzada Escarlata."]},"term:queldorei":{title:"Quel'dorei",summary:"Los altos elfos de Quel'Thalas, herederos de los Altonatos desterrados.",body:["Casi siete mil a\xf1os antes del Portal Oscuro, Altonatos desterrados cruzaron el mar, fundaron Quel'Thalas y encendieron la Fuente del Sol. Se aliaron con los humanos de Arathor en las Guerras Trol y les ense\xf1aron la magia. Cuando la Plaga de Arthas asol\xf3 su reino y profan\xf3 la Fuente del Sol, la mayor\xeda de los supervivientes adopt\xf3 un nuevo nombre en memoria de sus muertos: los sin'dorei, o elfos de sangre."]},"term:scarlet-crusade":{title:"Cruzada Escarlata",summary:"Fan\xe1ticos que dan caza a los no-muertos y a cualquiera de quien sospechen que porta la peste, dirigidos en secreto por un se\xf1or del terror.",body:["Nacida de los paladines y soldados supervivientes de Lordaeron, la Cruzada jur\xf3 purgar a la Plaga, pero se volvi\xf3 tan fan\xe1tica que ataca por igual a los Renegados y a los viajeros vivos. Su Gran Cruzado es en secreto el se\xf1or del terror Balnazzar. Entre sus bastiones est\xe1n el Monasterio Escarlata, en los Claros de Tirisfal, Vega del Amparo y la Mano de Tyr."]},"term:scourge":{title:"Plaga",summary:"El ej\xe9rcito de no-muertos del Rey Ex\xe1nime, propagado por la peste y la nigromancia.",body:["La Plaga est\xe1 sometida a la voluntad del Rey Ex\xe1nime: necr\xf3fagos, abominaciones, ex\xe1nimes y caballeros de la Muerte alzados de entre los ca\xeddos. La peste que la cre\xf3 arras\xf3 Lordaeron en la Tercera Guerra y dej\xf3 atr\xe1s las Tierras de la Peste. Bajo el mando de Kel'Thuzad, la Plaga a\xfan ocupa Stratholme y Scholomance, y su alcance llega hasta la Zah\xfarda Rajacieno, en Los Bald\xedos."]},"term:skywall":{title:"Skywall",summary:"El Plano Elemental del aire, reino de Al'Akir, el Se\xf1or del Viento.",body:["Cuando los servidores de los titanes encerraron a los elementales, los se\xf1ores del aire quedaron confinados en Skywall, un reino de cielo sin fin gobernado por Al'Akir. En Forever, Skywall alberga tambi\xe9n Zephras Isle, la zona inicial flotante de los Skyborne. Los elementales de aire de la isla desaparecieron hace siglos, y la magia que la mantiene en el aire se est\xe1 agotando poco a poco."]},"term:sunwell":{title:"Fuente del Sol",summary:"El manantial de poder arcano en el coraz\xf3n de Quel'Thalas.",body:["Dath'Remar Caminante del Sol verti\xf3 un vial robado del Pozo de la Eternidad en un lago donde confluyen l\xedneas ley, y la Fuente del Sol cobr\xf3 vida con un resplandor. Durante milenios aliment\xf3 la magia y la cultura de los altos elfos. En la Tercera Guerra, Arthas us\xf3 sus aguas para alzar a Kel'Thuzad como ex\xe1nime y profan\xf3 el manantial; su p\xe9rdida dej\xf3 a los supervivientes con un hambre de magia que nunca los abandon\xf3."]},"term:titan-forged":{title:"Forjados por los titanes",summary:"Los guardianes y dem\xe1s servidores que los titanes crearon para poner orden en Azeroth.",body:["Los titanes moldearon servidores para completar su obra: imponentes guardianes y razas de piedra y metal como los terr\xe1neos y los mecagnomos. Con el paso de las eras, la Maldici\xf3n de la Carne de los Dioses Antiguos volvi\xf3 mortales a muchos de ellos, y de ellos descienden los enanos y los gnomos. Guardianes forjados por los titanes a\xfan custodian c\xe1maras como Uldaman, y Forever a\xf1ade m\xe1s lugares de los titanes, desde la excavaci\xf3n de Los Humedales hasta Shaper's Terrace, en el Cr\xe1ter de Un'Goro."]},"term:titans":{title:"Titanes",summary:"Colosales almas del mundo que quisieron poner orden en el cosmos y dieron forma a Azeroth.",body:["Los titanes son almas del mundo que despertaron como seres divinos. Su Pante\xf3n, dirigido por Aman'Thul, recorri\xf3 el cosmos en busca de almas del mundo dormidas y encontr\xf3 en Azeroth una muy prometedora. Arrancaron del mundo al Dios Antiguo Y'Shaarj, encarcelaron a los dem\xe1s y dejaron a sus servidores la tarea de dar forma a la tierra. Su campe\xf3n m\xe1s poderoso, Sargeras, cay\xf3 m\xe1s tarde y fund\xf3 la Legi\xf3n Ardiente."]},"term:twilights-hammer":{title:"Martillo Crepuscular",summary:"Anta\xf1o un clan orco, hoy un culto apocal\xedptico al servicio de los Dioses Antiguos.",body:["Dirigido por el mago ogro de dos cabezas Cho'gall, el Martillo Crepuscular luch\xf3 en la Segunda Guerra como clan orco antes de convertirse en un culto que anhela el fin del mundo. Sus miembros, procedentes de todas las razas, se re\xfanen en lugares como las Cavernas de Brazanegra y Silithus. En Forever, el culto ocupa tambi\xe9n las ruinas de Sunnyglade, en los Riverglades."]},"term:well-of-eternity":{title:"Pozo de la Eternidad",summary:"El lago de poder arcano en bruto en el coraz\xf3n del antiguo Kalimdor, cuya implosi\xf3n parti\xf3 el mundo.",body:["El Pozo se form\xf3 donde los titanes arrancaron a Y'Shaarj del mundo, y los guardianes calmaron la herida sangrante hasta convertirla en un lago de poder puro. Los elfos de la noche construyeron su imperio en sus orillas, y los temerarios hechizos de los Altonatos atrajeron a la Legi\xf3n a trav\xe9s de \xe9l. Su colapso en la Guerra de los Ancestros caus\xf3 la Gran Escisi\xf3n, y la Vor\xe1gine se agita donde antes estaba."]}}},993,[]);